UPDATE modalities SET functional_impacts = '{"Mood":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/35919420/","notes":"Using CGM in healthy adults, this study reported that lower mean glucose levels and greater glycemic variability were associated with worse mood and higher anxiety, linking blood sugar stability to emotional well-being.","title":"Continuous glucose monitoring reveals associations of glucose levels with mood and fatigue in healthy young adults"}]},"Focus":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/15331351/","notes":"This comprehensive review establishes that both high and low glucose levels, as well as rapid fluctuations, impair cognitive functions including attention, learning, and memory, highlighting the importance of glucose stability for mental clarity.","title":"Glucose regulation and cognitive functioning: the role of glucose and insulin"}]},"Energy":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/35919420/","notes":"This study in healthy young adults using CGM found that higher glucose variability was significantly associated with greater fatigue, demonstrating the direct link between stable blood sugar and sustained energy.","title":"Continuous glucose monitoring reveals associations of glucose levels with mood and fatigue in healthy young adults"}]},"Sleep Quality":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/33722749/","notes":"In individuals without diabetes, this study showed that higher nocturnal glucose levels and greater glycemic variability were associated with poorer subjective sleep quality, longer sleep latency, and reduced sleep efficiency.","title":"Association between nocturnal glucose levels and sleep quality in subjects without diabetes"}]},"metabolic_health":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Improves peripheral insulin sensitivity and AMPK signaling","biomarkers":["Fasting Insulin","HOMA-IR","HbA1c"],"mechanism":"Activates hepatic and muscular AMPK phosphorylation to facilitate glucose uptake.","studies":[{"pmid":"32060683","title":"Targeting AMPK in Metabolic Disease and Aging","url":"https://pubmed.ncbi.nlm.nih.gov/32060683/","type":"Systematic Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Deregulated Nutrient Sensing"]'::text[] WHERE id = 'continuous_glucose_monitor';

