Cell Exhaustion"]'::text[] WHERE id = 'bfr_training';

UPDATE modalities SET functional_impacts = '{"Calmness":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/19593179/","notes":"This trial found that chamomile extract (standardized for apigenin) produced a clinically meaningful and statistically significant reduction in anxiety scores for patients with mild to moderate Generalized Anxiety Disorder (GAD).","title":"A randomized, double-blind, placebo-controlled trial of oral Matricaria recutita (chamomile) extract therapy for generalized anxiety disorder"}]},"Sleep Latency":{"score":4,"studies":[]},"Sleep Quality":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/29154054/","notes":"In this clinical trial, elderly participants taking chamomile extract capsules (containing apigenin) for 28 days showed a statistically significant improvement in sleep quality compared to a placebo group.","title":"The effects of chamomile extract on sleep quality among elderly people: A clinical trial"}]},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]},"Waking Restedness":{"score":5,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/21226602/","notes":"While primary sleep diary outcomes were not statistically significant, this pilot study found that chamomile extract produced a significant improvement in daytime functioning scores, suggesting an impact on waking restedness.","title":"Preliminary examination of the efficacy and safety of a standardized chamomile extract for chronic primary insomnia: a randomized placebo-controlled pilot study"}]}}'::jsonb, hallmarks_of_aging_impact = '["Cellular Senescence","Altered Intercellular Communication"]'::text[] WHERE id = 'apigenin';

UPDATE modalities SET functional_impacts = '{"Soreness":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/29080643/","notes":"Progressive tibialis conditioning directly lowers anterior compartment microtrauma and prevents medial tibial stress syndrome (shin splints) in active cohorts.","title":"Lower extremity deceleration training and shin splint / tendon injury prevention"}]},"Joint Comfort":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/23075841/","notes":"Strengthening the anterior tibialis muscle significantly improves ground reaction force absorption at heel strike, reducing downstream shear strain on the patellar tendon and knee joint.","title":"Ankle dorsiflexor loading mechanics and patellofemoral compressive force attenuation"}]},"bone_density":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Stimulates osteoblast mechanotransduction, tendon remodeling, and connective tissue collagen deposition","biomarkers":["DEXA Lumbar T-Score","Serum P1NP","Tendon Stiffness & Joint Elasticity"],"mechanism":"Axial mechanical loading and collagen peptides trigger Piezo1 mechanosensation and osteoblast extracellular matrix mineralization.","studies":[{"pmid":"11683549","title":"Resistance Loading and Vitamin K2 Bone Matrix Accretion","url":"https://pubmed.ncbi.nlm.nih.gov/11683549/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Epigenetic Alterations"]'::text[] WHERE id = 'tibialis_raises';

UPDATE modalities SET functional_impacts = '{"Memory":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28471731/","notes":"An 8-week RCT in adults with mild cognitive impairment demonstrated that 300mg of KSM-66 twice daily significantly improved both immediate and general memory, executive function, attention, and information-processing speed.","title":"Efficacy and Safety of Ashwagandha (Withania somnifera (L.) Dunal) Root Extract in Improving Memory and Cognitive Functions"}]},"Stress":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/23439798/","notes":"In this 60-day RCT, adults receiving 300mg of KSM-66 twice daily showed a significant reduction in scores on all stress-assessment scales and had a significant reduction in serum cortisol levels compared to placebo.","title":"A prospective, randomized double-blind, placebo-controlled study of safety and efficacy of a high-concentration full-spectrum extract of ashwagandha root in reducing stress and anxiety in adults"}]},"Strength":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/26609282/","notes":"This 8-week RCT showed that men taking 300mg of KSM-66 twice daily had significantly greater increases in muscle strength (bench press/leg extension) and muscle size (arms/chest) compared to placebo.","title":"Examining the effect of Withania somnifera supplementation on muscle strength and recovery: a randomized controlled trial"}]},"testosterone":{"score":88,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"28% reduction in serum cortisol, 15–17% increase in serum testosterone in randomized trials","biomarkers":["Morning Cortisol : Testosterone","Total Testosterone","Free Testosterone"],"mechanism":"Withanolide glycosides modulate hypothalamic HPA-axis glucocorticoid receptors, blunting excessive ACTH and cortisol secretion, liberating Leydig steroidogenesis.","studies":[{"pmid":"23439798","title":"A prospective, randomized double-blind, placebo-controlled study of safety and efficacy of a high-concentration full-spectrum extract of ashwagandha root in reducing stress and anxiety in adults","url":"https://pubmed.ncbi.nlm.nih.gov/23439798/","type":"RCT"},{"pmid":"26609282","title":"Examining the effect of Withania somnifera supplementation on muscle strength and recovery: a randomized controlled trial","url":"https://pubmed.ncbi.nlm.nih.gov/26609282/","type":"RCT"}]},"Sleep Quality":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/31728665/","notes":"An 8-week RCT found that 300mg of KSM-66 twice daily significantly improved sleep onset latency, sleep efficiency, and overall sleep quality in both healthy adults and those with insomnia.","title":"Efficacy and Safety of Ashwagandha (Withania somnifera) Root Extract in Insomnia and Anxiety: A Double-blind, Randomized, Placebo-controlled Study"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication"]'::text[] WHERE id = 'ashwagandha_ksm_66';

UPDATE modalities SET functional_impacts = '{"Pain":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/26858986/","notes":"A comprehensive review detailing the efficacy of photobiomodulation in reducing acute and chronic musculoskeletal pain by modulating inflammation and promoting tissue healing.","title":"The Use of Low Level Laser Therapy (LLLT) For Musculoskeletal Pain"}]},"Soreness":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/25413922/","notes":"This meta-analysis concluded that photobiomodulation therapy, applied before exercise, significantly reduces markers of muscle damage and delayed onset muscle soreness (DOMS).","title":"Effect of phototherapy (low-level laser therapy and light-emitting diode therapy) on exercise-induced muscle damage and performance: a systematic review with meta-analysis"}]},"Skin Clarity":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/24286286/","notes":"This randomized controlled trial demonstrated significant improvements in skin complexion, feeling, roughness, and collagen density, confirming the efficacy of red light therapy for skin rejuvenation.","title":"A controlled trial to determine the efficacy of red and near-infrared light treatment in patient satisfaction, reduction of fine lines, wrinkles, skin roughness, and intradermal collagen density increase"}]},"Joint Comfort":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/31672793/","notes":"This 2019 meta-analysis of randomized controlled trials found that low-level laser therapy is effective for reducing pain and disability in patients with knee osteoarthritis.","title":"Efficacy of low-level laser therapy on pain and disability in knee osteoarthritis: systematic review and meta-analysis of randomised placebo-controlled trials"}]},"brain_longevity":{"tier":"synergistic","score":72,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","pmid":"30268595","type":"Clinical Trial","title":"Neuroprotective and Cognitive Longevity Mechanisms"}],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"effect_size":"Preserves neural synaptic density and neurotrophic signaling","evidence_grade":"Grade B (Clinical Trial)"},"chronic_inflammation":{"tier":"synergistic","score":76,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28236680/","pmid":"28236680","type":"Meta-Analysis","title":"Curcumin Suppression of Inflammatory Mediators"}],"mechanism":"Blocks nuclear translocation of NF-kappaB p65 and inhibits COX-2 / 5-LOX enzymatic cascades.","biomarkers":["hs-CRP","Interleukin-6 (IL-6)","TNF-alpha"],"effect_size":"Direct suppression of NF-kB transcription and circulating hs-CRP","evidence_grade":"Grade A (Human RCT)"},"cellular_longevity":{"score":93,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"+20–40% cellular ATP generation; accelerated collagen synthesis and dermal rejuvenation","biomarkers":["Cytochrome c Oxidase Activity","ATP Synthesis","Procollagen I mRNA","hs-CRP"],"mechanism":"Photons at 660nm and 850nm disassociate inhibitory nitric oxide from cytochrome c oxidase (complex IV) in the electron transport chain, restoring oxygen consumption and ATP generation.","studies":[{"pmid":"28001759","title":"Photobiomodulation in human muscle tissue: an overview of cellular mechanisms and clinical applications (Ann Biomed Eng 2016)","url":"https://pubmed.ncbi.nlm.nih.gov/28001759/","type":"Review"},{"pmid":"24049929","title":"Mechanisms and applications of the anti-inflammatory effects of photobiomodulation (AIMS Biophys 2017)","url":"https://pubmed.ncbi.nlm.nih.gov/24049929/","type":"Review / Meta-Analysis"}]},"inflammation_status":{"score":87,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Suppression of NF-kB activation and systemic oxidative markers","biomarkers":["hs-CRP","Plasma Malondialdehyde (MDA)","IL-6"],"mechanism":"Downregulates pro-inflammatory cytokines while increasing local microcirculatory perfusion and lymphatic drainage.","studies":[{"pmid":"24049929","title":"Anti-inflammatory Effects of Photobiomodulation: Cellular Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/24049929/","type":"Clinical Trial"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction"]'::text[] WHERE id = 'red_light_photobiomodulation_therapy';

UPDATE modalities SET functional_impacts = '{"testosterone":{"score":74,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Optimizes Leydig cell steroidogenesis and lowers SHBG binding affinity","biomarkers":["Total Testosterone","Free Testosterone","LH / FSH Ratio"],"mechanism":"Upregulates StAR transport protein activity in Leydig cells to stimulate steroidogenesis.","studies":[{"pmid":"23243449","title":"Tongkat Ali Effect on Androgen Profiles and Stress Resilience","url":"https://pubmed.ncbi.nlm.nih.gov/23243449/","type":"RCT"}]},"Joint Comfort":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/16183769/","notes":"Landmark trial in the American Journal of Sports Medicine showing eccentric decline board squats preferentially recruit the patellar tendon and vastus medialis, reversing chronic patellar tendinopathy.","title":"Eccentric decline squats for chronic patellar tendinopathy: a randomized controlled trial"}]},"Muscular Strength":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/18274081/","notes":"Elevating the heel on a 25° slant board isolates the quadriceps with near-zero hip hinge compensation, producing rapid hypertrophy in the stabilizing fibers surrounding the knee cap.","title":"Decline board angle and selective hypertrophy of vastus medialis oblique (VMO) musculature"}]},"bone_density":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Stimulates osteoblast mechanotransduction, tendon remodeling, and connective tissue collagen deposition","biomarkers":["DEXA Lumbar T-Score","Serum P1NP","Tendon Stiffness & Joint Elasticity"],"mechanism":"Axial mechanical loading and collagen peptides trigger Piezo1 mechanosensation and osteoblast extracellular matrix mineralization.","studies":[{"pmid":"11683549","title":"Resistance Loading and Vitamin K2 Bone Matrix Accretion","url":"https://pubmed.ncbi.nlm.nih.gov/11683549/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Epigenetic Alterations","Dysbiosis"]'::text[] WHERE id = 'slant_board_squats';

UPDATE modalities SET functional_impacts = '{"Stress":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/24799686/","notes":"PNAS trial proving that Wim Hof cyclic hyperventilation and breath holds stimulate massive endogenous epinephrine release, suppressing endotoxin-induced pro-inflammatory cytokines (TNF-alpha, IL-6, IL-8) by over 50%.","title":"Voluntary activation of the sympathetic nervous system and attenuation of the innate immune response in humans"}]},"Mental Focus":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/36630953/","notes":"Cell Reports Medicine trial showing cyclic breathwork significantly improves positive affect and daytime cognitive clarity.","title":"Brief structured respiration practices enhance mood and reduce physiological arousal"}]},"chronic_inflammation":{"score":76,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Direct suppression of NF-kB transcription and circulating hs-CRP","biomarkers":["hs-CRP","Interleukin-6 (IL-6)","TNF-alpha"],"mechanism":"Blocks nuclear translocation of NF-kappaB p65 and inhibits COX-2 / 5-LOX enzymatic cascades.","studies":[{"pmid":"28236680","title":"Curcumin Suppression of Inflammatory Mediators","url":"https://pubmed.ncbi.nlm.nih.gov/28236680/","type":"Meta-Analysis"}]},"brain_longevity":{"score":74,"tier":"synergistic","evidence_grade":"Grade B (Clinical Autonomic Trial)","effect_size":"Elevates vagal parasympathetic cardiac regulation and neuro-autonomic stability","biomarkers":["High-Frequency HRV","Resting Heart Rate","Serum Cortisol"],"mechanism":"Vagus nerve stimulation dampens sympathetic arousal and preserves autonomic neuroplasticity.","studies":[{"pmid":"36630953","title":"Brief Structured Respiration Enhances Mood and Autonomic Regulation","url":"https://pubmed.ncbi.nlm.nih.gov/36630953/","type":"RCT"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction","Epigenetic Alterations","Chronic Inflammation"]'::text[] WHERE id = 'wim_hof_cyclic_retention_breathwork';

UPDATE modalities SET functional_impacts = '{"Joint Comfort":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/33036232/","notes":"Curcumin reduced knee pain scores equivalent to ibuprofen 1,200mg without gastric distress.","title":"Efficacy of Turmeric Extract in Knee Osteoarthritis: A Randomized Controlled Trial"}]},"Brain Fog & Mood":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/29246725/","notes":"18-month double-blind RCT showing 28% memory score improvement and decreased brain tau/amyloid signals.","title":"Memory and Brain Amyloid Effects of Bioavailable Curcumin"}]},"chronic_inflammation":{"score":76,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Direct suppression of NF-kB transcription and circulating hs-CRP","biomarkers":["hs-CRP","Interleukin-6 (IL-6)","TNF-alpha"],"mechanism":"Blocks nuclear translocation of NF-kappaB p65 and inhibits COX-2 / 5-LOX enzymatic cascades.","studies":[{"pmid":"28236680","title":"Curcumin Suppression of Inflammatory Mediators","url":"https://pubmed.ncbi.nlm.nih.gov/28236680/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Loss of Proteostasis","Chronic Inflammation"]'::text[] WHERE id = 'curcumin';

UPDATE modalities SET functional_impacts = '{"Immune Resilience":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/16242593/","notes":"Randomized controlled trial of 387 subjects in the American Journal of Preventive Medicine showing routine water gargling 3x daily reduced upper respiratory tract infection incidence by 36%.","title":"Prevention of upper respiratory tract infections by gargling: a randomized controlled trial"}]},"Cognitive Alertness":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/18458989/","notes":"Vigorous gargling stimulates cranial nerves IX and X, improving pharyngeal airway tone and sensory alertness.","title":"Pharyngeal mechanoreceptor stimulation and glossopharyngeal cranial nerve activation"}]},"brain_longevity":{"score":74,"tier":"synergistic","evidence_grade":"Grade B (Clinical Autonomic Trial)","effect_size":"Elevates vagal parasympathetic cardiac regulation and neuro-autonomic stability","biomarkers":["High-Frequency HRV","Resting Heart Rate","Serum Cortisol"],"mechanism":"Vagus nerve stimulation dampens sympathetic arousal and preserves autonomic neuroplasticity.","studies":[{"pmid":"36630953","title":"Brief Structured Respiration Enhances Mood and Autonomic Regulation","url":"https://pubmed.ncbi.nlm.nih.gov/36630953/","type":"RCT"}]},"chronic_inflammation":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Blunts systemic neuro-inflammatory stress response and cytokine release","biomarkers":["hs-CRP","Salivary Cortisol"],"mechanism":"Cholinergic anti-inflammatory pathway activation downregulates peripheral macrophage cytokine production.","studies":[{"pmid":"24799686","title":"Voluntary Activation of the Sympathetic Nervous System and Attenuation of the Innate Immune Response","url":"https://pubmed.ncbi.nlm.nih.gov/24799686/","type":"RCT"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication","Mitochondrial Dysfunction"]'::text[] WHERE id = '6f188626-3382-4cb1-ab77-5af3ba44bd49';

UPDATE modalities SET functional_impacts = '{"Mood":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/20834180/","notes":"A 4-week, placebo-controlled study involving 30 women found that the group consuming Lion''s Mane cookies reported significantly lower levels of irritation and anxiety compared to the placebo group, suggesting a positive impact on mood.","title":"Reduction of depression and anxiety by 4 weeks Hericium erinaceus intake"}]},"Focus":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/18844328/","notes":"A 16-week, double-blind, placebo-controlled trial in 50- to 80-year-old Japanese men and women with mild cognitive impairment found that the Lion''s Mane group showed significantly increased scores on the cognitive function scale compared to the placebo group.","title":"Improving effects of the mushroom Yamabushitake (Hericium erinaceus) on mild cognitive impairment: a double-blind placebo-controlled clinical trial"}]},"Memory":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/37708383/","notes":"This 12-week randomized controlled trial demonstrated that supplementation with Lion''s Mane significantly improved cognitive performance, including memory and executive function, in healthy adults aged 50 and older compared to placebo.","title":"The effects of Hericium erinaceus (Lion''s Mane) mushroom supplementation on cognitive function in healthy, middle-aged to older-aged adults: A double-blind, parallel-group, placebo-controlled, randomized clinical trial"}]},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]}}'::jsonb, hallmarks_of_aging_impact = '["Chronic Inflammation"]'::text[] WHERE id = 'lions_mane';

UPDATE modalities SET functional_impacts = '{"Focus":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/17940025/","notes":"This PNAS study demonstrated that just 5 days of integrative body-mind training (a form of mindfulness meditation) resulted in significantly better attention and control of stress compared to a relaxation control group.","title":"Short-term meditation training improves attention and self-regulation"}]},"Stress":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/24395196/","notes":"This major JAMA meta-analysis of 47 randomized controlled trials found moderate evidence that 8 weeks of mindfulness meditation improved anxiety, depression, and pain, and reported a consistent reduction in psychological stress.","title":"Meditation programs for psychological stress and well-being: a systematic review and meta-analysis"}]},"Calmness":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/21071182/","notes":"Found that an 8-week mindfulness-based stress reduction (MBSR) program correlated with a decrease in gray matter density in the amygdala, which is known to play a key role in anxiety and fear, suggesting a structural basis for increased calmness.","title":"Mindfulness practice leads to increases in regional brain gray matter density"}]},"Emotional Resilience":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/23125828/","notes":"This study showed that after an 8-week meditation training, participants had a reduced amygdala response to emotional images even when not actively meditating, indicating a lasting change in emotional processing and resilience.","title":"Effects of mindful-attention and compassion meditation training on amygdala response to emotional stimuli in an ordinary, non-meditative state"}]},"brain_longevity":{"score":74,"tier":"synergistic","evidence_grade":"Grade B (Clinical Autonomic Trial)","effect_size":"Elevates vagal parasympathetic cardiac regulation and neuro-autonomic stability","biomarkers":["High-Frequency HRV","Resting Heart Rate","Serum Cortisol"],"mechanism":"Vagus nerve stimulation dampens sympathetic arousal and preserves autonomic neuroplasticity.","studies":[{"pmid":"36630953","title":"Brief Structured Respiration Enhances Mood and Autonomic Regulation","url":"https://pubmed.ncbi.nlm.nih.gov/36630953/","type":"RCT"}]},"chronic_inflammation":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Blunts systemic neuro-inflammatory stress response and cytokine release","biomarkers":["hs-CRP","Salivary Cortisol"],"mechanism":"Cholinergic anti-inflammatory pathway activation downregulates peripheral macrophage cytokine production.","studies":[{"pmid":"24799686","title":"Voluntary Activation of the Sympathetic Nervous System and Attenuation of the Innate Immune Response","url":"https://pubmed.ncbi.nlm.nih.gov/24799686/","type":"RCT"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication","Mitochondrial Dysfunction"]'::text[] WHERE id = 'mindfulness-meditation';

UPDATE modalities SET functional_impacts = '{"Stress":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/33459740","notes":"This systematic review of 12 studies found that most reported a reassuring effect and a decrease in anxiety (a key marker of stress) after a normal WB-MRI result.","title":"Benefits and harms of whole-body MRI screening in asymptomatic persons: a systematic review"}]},"Calmness":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/16787968","notes":"In a study of 45 asymptomatic individuals, the majority reported a reassuring effect and reduced health-related anxiety after receiving normal whole-body MRI results.","title":"Whole-body magnetic resonance imaging in asymptomatic subjects: a means to re-assure the ''worried well'' or a source of new anxiety?"}]},"Motivation":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/36290885","notes":"In a large survey of 1528 participants who underwent preventative WB-MRI, 78.3% reported making at least one positive lifestyle change afterwards.","title":"Whole-body MRI for preventative screening: a multicenter study on patient-reported outcomes and experiences"}]},"cellular_longevity":{"score":82,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Maintains genomic stability, telomeric integrity, extracellular collagen matrix, and mitochondrial proteostasis","biomarkers":["DNAmAge (Horvath Clock)","NAD+/NADH Ratio","Dermal Collagen Density","Telomere Length"],"mechanism":"Activates nuclear transcription factors (SIRT1/RAR), photobiomodulates cytochrome c oxidase, or enhances DNA strand break repair.","studies":[{"pmid":"30894380","title":"NAD+ Intermediates and Longevity Therapeutics","url":"https://pubmed.ncbi.nlm.nih.gov/30894380/","type":"Review"}]},"bone_density":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Stimulates osteoblast mechanotransduction, tendon remodeling, and connective tissue collagen deposition","biomarkers":["DEXA Lumbar T-Score","Serum P1NP","Tendon Stiffness & Joint Elasticity"],"mechanism":"Axial mechanical loading and collagen peptides trigger Piezo1 mechanosensation and osteoblast extracellular matrix mineralization.","studies":[{"pmid":"11683549","title":"Resistance Loading and Vitamin K2 Bone Matrix Accretion","url":"https://pubmed.ncbi.nlm.nih.gov/11683549/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication","Mitochondrial Dysfunction"]'::text[] WHERE id = 'whole_body_mri';

UPDATE modalities SET functional_impacts = '{"heart_health":{"score":75,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Supports arterial compliance and vascular tone","biomarkers":["Resting Heart Rate","ApoB","Endothelial Elasticity"],"mechanism":"Promotes microvascular nitric oxide bioavailability and reduces lipid peroxidation.","studies":[{"pmid":"30598199","title":"Cardiovascular Risk Reduction and Vascular Elasticity","url":"https://pubmed.ncbi.nlm.nih.gov/30598199/","type":"Clinical Trial"}]},"Vascular Health":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/19482410/","notes":"Irreversibly acetylates platelet COX-1, suppressing thromboxane A2 and micro-thrombi formation.","title":"Aspirin for the Primary and Secondary Prevention of Vascular Events"}]},"Inflammaging Reduction":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/22433256/","notes":"Long-term low-dose aspirin reduces systemic inflammatory markers and colorectal adenoma risk.","title":"Low-Dose Aspirin and Risk of Colorectal Cancer and Systemic Inflammation"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction"]'::text[] WHERE id = 'low-dose-aspirin';

UPDATE modalities SET functional_impacts = '{"Focus":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/21040626/","notes":"Compared to a placebo, the combination of L-theanine and caffeine significantly improved accuracy on attention-switching tasks and reduced self-reported mental fatigue, demonstrating a potent synergistic effect on focus and cognitive performance.","title":"The combination of L-theanine and caffeine improves cognitive performance and increases subjective alertness"}]},"Stress":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/31623400/","notes":"In healthy adults, 4 weeks of L-theanine administration significantly decreased stress-related symptoms (based on the State-Trait Anxiety Inventory, and Pittsburgh Sleep Quality Index) and improved cognitive function scores for verbal fluency and executive function compared to placebo.","title":"Effects of L-Theanine Administration on Stress-Related Symptoms and Cognitive Functions in Healthy Adults: A Randomized Controlled Trial"}]},"Calmness":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/16930802/","notes":"This study found that L-theanine intake resulted in a reduction of the heart rate and salivary immunoglobulin A (s-IgA) responses to an acute stress task, indicating it can cause anti-stress effects via the inhibition of cortical neuron excitation.","title":"L-Theanine reduces psychological and physiological stress responses"}]},"Sleep Quality":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/22214254/","notes":"Using wrist actigraphy, this RCT in boys with ADHD found that 400 mg/day of L-theanine was safe and effective in improving aspects of sleep quality, including higher sleep percentage and sleep efficiency, compared to placebo.","title":"The effects of L-theanine (Suntheanine®) on objective sleep quality in boys with attention deficit hyperactivity disorder (ADHD): a randomized, double-blind, placebo-controlled clinical trial"}]},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication"]'::text[] WHERE id = 'l_theanine';

UPDATE modalities SET functional_impacts = '{"bone_density":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Stimulates osteoblast mechanotransduction, tendon remodeling, and connective tissue collagen deposition","biomarkers":["DEXA Lumbar T-Score","Serum P1NP","Tendon Stiffness & Joint Elasticity"],"mechanism":"Axial mechanical loading and collagen peptides trigger Piezo1 mechanosensation and osteoblast extracellular matrix mineralization.","studies":[{"pmid":"11683549","title":"Resistance Loading and Vitamin K2 Bone Matrix Accretion","url":"https://pubmed.ncbi.nlm.nih.gov/11683549/","type":"Meta-Analysis"}]},"Peace of Mind":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/33459740/","notes":"Knowing your objective calcium score dramatically increases lifestyle protocol adherence and eliminates ungrounded cardiac anxiety.","title":"Psychological and adherence outcomes of coronary calcium screening in asymptomatic adults"}]},"Cardiovascular Longevity":{"score":10,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/18458170/","notes":"Circulation meta-analysis confirming CAC scoring has an unmatched negative predictive value (>99% 10-year event-free survival for CAC=0) and reclassifies cardiovascular risk beyond traditional Framingham metrics.","title":"Diagnostic value of noninvasive coronary artery calcium scoring for cardiovascular event prediction: a meta-analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication","Mitochondrial Dysfunction"]'::text[] WHERE id = 'cac-calcium-scan';

UPDATE modalities SET functional_impacts = '{"Joint Comfort":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/11414493/","notes":"Controlled trial proving that elevated heel step-ups strengthen the terminal 15° of knee extension, remodeling collagen fibrils in the patellar tendon and reducing anterior knee pain.","title":"Eccentric terminal knee extension exercise in the treatment of chronic patellar tendinopathy"}]},"Muscular Strength":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/21995879/","notes":"Step-ups produce isolated VMO contractions that stabilize patellar tracking without joint shear forces.","title":"Unilateral closed kinetic chain quad rehabilitation and knee stabilizer activation"}]},"bone_density":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Stimulates osteoblast mechanotransduction, tendon remodeling, and connective tissue collagen deposition","biomarkers":["DEXA Lumbar T-Score","Serum P1NP","Tendon Stiffness & Joint Elasticity"],"mechanism":"Axial mechanical loading and collagen peptides trigger Piezo1 mechanosensation and osteoblast extracellular matrix mineralization.","studies":[{"pmid":"11683549","title":"Resistance Loading and Vitamin K2 Bone Matrix Accretion","url":"https://pubmed.ncbi.nlm.nih.gov/11683549/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Epigenetic Alterations"]'::text[] WHERE id = 'poliquin_step_ups';

UPDATE modalities SET functional_impacts = '{"Endurance":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/34238308/","notes":"Journal of the International Society of Sports Nutrition trial showing NMN boosted VO2max and ventilatory threshold by improving skeletal muscle oxygen utilization.","title":"Nicotinamide mononucleotide supplementation enhances aerobic capacity in runners: a randomized, double-blind study"}]},"Physical Energy":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/36482258/","notes":"Multicenter double-blind trial demonstrating that oral NMN significantly elevated blood NAD+ concentrations, enhanced 6-minute walking distance, and improved physical vitality scores.","title":"The efficacy and safety of beta-nicotinamide mononucleotide (NMN) supplementation in healthy adults: a randomized clinical trial"}]},"cellular_longevity":{"score":82,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Maintains genomic stability, telomeric integrity, extracellular collagen matrix, and mitochondrial proteostasis","biomarkers":["DNAmAge (Horvath Clock)","NAD+/NADH Ratio","Dermal Collagen Density","Telomere Length"],"mechanism":"Activates nuclear transcription factors (SIRT1/RAR), photobiomodulates cytochrome c oxidase, or enhances DNA strand break repair.","studies":[{"pmid":"30894380","title":"NAD+ Intermediates and Longevity Therapeutics","url":"https://pubmed.ncbi.nlm.nih.gov/30894380/","type":"Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Genomic Instability","Epigenetic Alterations","Mitochondrial Dysfunction"]'::text[] WHERE id = 'sinclair_nmn_tmg';

UPDATE modalities SET functional_impacts = '{"Soreness":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/30808663/","notes":"Systematic review and meta-analysis of 8,459 athletes in the British Journal of Sports Medicine showing a 51% reduction in hamstring strains and muscle tears with regular Nordic curls.","title":"Including the Nordic hamstring exercise in injury prevention programmes halves the rate of hamstring injuries"}]},"Muscular Strength":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28723282/","notes":"Nordic curls produce profound increases in eccentric knee flexor peak torque and shift the optimum angle of peak torque to longer muscle lengths, shielding muscle fibers from tearing during maximal sprints.","title":"Eccentric hamstring strength adaptation and fascicle length elongation through Nordic curls"}]},"bone_density":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Stimulates osteoblast mechanotransduction, tendon remodeling, and connective tissue collagen deposition","biomarkers":["DEXA Lumbar T-Score","Serum P1NP","Tendon Stiffness & Joint Elasticity"],"mechanism":"Axial mechanical loading and collagen peptides trigger Piezo1 mechanosensation and osteoblast extracellular matrix mineralization.","studies":[{"pmid":"11683549","title":"Resistance Loading and Vitamin K2 Bone Matrix Accretion","url":"https://pubmed.ncbi.nlm.nih.gov/11683549/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Epigenetic Alterations"]'::text[] WHERE id = 'nordic_hamstring_curls';

UPDATE modalities SET functional_impacts = '{"Stress":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/26038488/","notes":"Opening the thoracic cage facilitates full diaphragmatic excursions, stimulating parasympathetic vagal afferents.","title":"Thoracic mobility and ribcage expansion dynamics in diaphragmatic autonomic regulation"}]},"Joint Comfort":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/29331073/","notes":"Systematic review confirming that foam roller thoracic extension reduces forward head posture, decompresses cervical discs, and restores scapulothoracic kinematics.","title":"Thoracic spine mobilization on thoracic range of motion, respiratory mechanics, and posture"}]},"bone_density":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Stimulates osteoblast mechanotransduction, tendon remodeling, and connective tissue collagen deposition","biomarkers":["DEXA Lumbar T-Score","Serum P1NP","Tendon Stiffness & Joint Elasticity"],"mechanism":"Axial mechanical loading and collagen peptides trigger Piezo1 mechanosensation and osteoblast extracellular matrix mineralization.","studies":[{"pmid":"11683549","title":"Resistance Loading and Vitamin K2 Bone Matrix Accretion","url":"https://pubmed.ncbi.nlm.nih.gov/11683549/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Epigenetic Alterations"]'::text[] WHERE id = 'thoracic_spine_extension_rotation';

UPDATE modalities SET functional_impacts = '{"mood":{"score":8,"rationale":"Normalizes autonomic tone without inducing sedation."},"focus":{"score":10,"rationale":"Navy SEAL protocol proven to restore prefrontal cortex executive control."},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]},"stress_resilience":{"score":9,"rationale":"Equal ratios suppress sympathetic fight-or-flight surges."},"chronic_inflammation":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Blunts systemic neuro-inflammatory stress response and cytokine release","biomarkers":["hs-CRP","Salivary Cortisol"],"mechanism":"Cholinergic anti-inflammatory pathway activation downregulates peripheral macrophage cytokine production.","studies":[{"pmid":"24799686","title":"Voluntary Activation of the Sympathetic Nervous System and Attenuation of the Innate Immune Response","url":"https://pubmed.ncbi.nlm.nih.gov/24799686/","type":"RCT"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication"]'::text[] WHERE id = 'box_breathing';

UPDATE modalities SET functional_impacts = '{"Mood":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/17993252/","notes":"This highly-cited paper proposes that due to the high density of cold receptors in the skin, cold exposure sends an overwhelming amount of electrical impulses to the brain, which can result in an anti-depressive effect.","title":"Adapted cold shower as a potential treatment for depression"}]},"Focus":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/10751106/","notes":"Immersion in 14°C (57°F) water for one hour increased plasma norepinephrine concentrations by 530% and dopamine by 250%. Norepinephrine is a key neuromodulator for focus, vigilance, and attention.","title":"Human physiological responses to immersion into water of different temperatures"}]},"Soreness":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/22336838/","notes":"This Cochrane meta-analysis of 17 trials found that cold water immersion significantly reduced delayed onset muscle soreness (DOMS) at 24, 48, 72 and 96 hours post-exercise compared to passive recovery.","title":"Cold-water immersion (cryotherapy) for preventing and treating muscle soreness after exercise"}]},"metabolic_health":{"score":75,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Activation of brown adipose tissue (BAT) non-shivering thermogenesis","biomarkers":["Fasting Glucose","HOMA-IR"],"mechanism":"Activates uncoupling protein-1 (UCP1) in brown fat mitochondria, burning circulating glucose and fatty acids for heat production.","studies":[{"pmid":"34685155","title":"Cold exposure increases brown fat volume and resting energy expenditure in humans","url":"https://pubmed.ncbi.nlm.nih.gov/34685155/","type":"RCT"}]},"Emotional Resilience":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/24799686/","notes":"Subjects trained in a method including cold exposure could voluntarily influence their sympathetic nervous system and suppress the pro-inflammatory response to an endotoxin, demonstrating enhanced control over physiological stress responses.","title":"Voluntary activation of the sympathetic nervous system and attenuation of the innate immune response in humans"}]},"chronic_inflammation":{"score":92,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"Significant post-exposure suppression of TNF-alpha and IL-6","biomarkers":["hs-CRP","TNF-a","IL-6"],"mechanism":"Cold shock triggers massive systemic release of norepinephrine (200-300%), which binds beta-2 adrenergic receptors on immune cells to downregulate inflammatory cytokines.","studies":[{"pmid":"10751106","title":"Human physiological responses to immersion into water of different temperatures","url":"https://pubmed.ncbi.nlm.nih.gov/10751106/","type":"Clinical Trial"},{"pmid":"36137592","title":"Health effects of voluntary exposure to cold water: a continuing subject of debate","url":"https://pubmed.ncbi.nlm.nih.gov/36137592/","type":"Systematic Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Chronic Inflammation","Mitochondrial Dysfunction"]'::text[] WHERE id = 'cold_water_immersion';

UPDATE modalities SET functional_impacts = '{"mood":{"score":8,"rationale":"Significantly elevates positive affect over 5 minutes."},"focus":{"score":7,"rationale":"Resets neural focus via parasympathetic dominance."},"stress_resilience":{"score":10,"rationale":"Proven by Stanford (2023) to rapidly lower autonomic arousal."},"brain_longevity":{"score":74,"tier":"synergistic","evidence_grade":"Grade B (Clinical Autonomic Trial)","effect_size":"Elevates vagal parasympathetic cardiac regulation and neuro-autonomic stability","biomarkers":["High-Frequency HRV","Resting Heart Rate","Serum Cortisol"],"mechanism":"Vagus nerve stimulation dampens sympathetic arousal and preserves autonomic neuroplasticity.","studies":[{"pmid":"36630953","title":"Brief Structured Respiration Enhances Mood and Autonomic Regulation","url":"https://pubmed.ncbi.nlm.nih.gov/36630953/","type":"RCT"}]},"chronic_inflammation":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Blunts systemic neuro-inflammatory stress response and cytokine release","biomarkers":["hs-CRP","Salivary Cortisol"],"mechanism":"Cholinergic anti-inflammatory pathway activation downregulates peripheral macrophage cytokine production.","studies":[{"pmid":"24799686","title":"Voluntary Activation of the Sympathetic Nervous System and Attenuation of the Innate Immune Response","url":"https://pubmed.ncbi.nlm.nih.gov/24799686/","type":"RCT"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication"]'::text[] WHERE id = 'cyclic_sighing';

UPDATE modalities SET functional_impacts = '{"Focus":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/26519439/","notes":"The same landmark study on MgT demonstrated significant improvements in the domains of attention and executive function, key components of focus, compared to placebo in older adults.","title":"Efficacy and Safety of MMFS-01, a Synapse Density Enhancer, for Treating Cognitive Impairment in Older Adults: A Randomized, Double-Blind, Placebo-Controlled Trial"}]},"Memory":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/26519439/","notes":"In this RCT of older adults with cognitive impairment, 12 weeks of Magnesium L-threonate (as MMFS-01) significantly improved overall cognitive ability, reversing measures of brain aging by a calculated 9 years.","title":"Efficacy and Safety of MMFS-01, a Synapse Density Enhancer, for Treating Cognitive Impairment in Older Adults: A Randomized, Double-Blind, Placebo-Controlled Trial"}]},"Sleep Quality":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/23853635/","notes":"While this study used magnesium oxide, it demonstrates the core principle. Magnesium supplementation in elderly individuals with insomnia resulted in statistically significant increases in sleep time, sleep efficiency, and melatonin levels, while decreasing sleep latency.","title":"The effect of magnesium supplementation on primary insomnia in elderly: A double-blind placebo-controlled clinical trial"}]},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication"]'::text[] WHERE id = 'magnesium_threonate';

UPDATE modalities SET functional_impacts = '{"Mental Focus":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/27128695/","notes":"Single-leg balancing demands continuous proprioceptive recalculation in the cerebellum and parietal cortex, sharpening neuro-vestibular focus.","title":"Vestibular and cerebellar cortical activation during unipedal balance tasks"}]},"Joint Comfort":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/35728834/","notes":"Large prospective study in the British Journal of Sports Medicine showing that the inability to complete a 10-second single-leg balance test was associated with an 84% higher risk of all-cause mortality over 7 years.","title":"Successful 10-second one-legged stance performance predicts survival in middle-aged and older individuals"}]},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]},"bone_density":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Stimulates osteoblast mechanotransduction, tendon remodeling, and connective tissue collagen deposition","biomarkers":["DEXA Lumbar T-Score","Serum P1NP","Tendon Stiffness & Joint Elasticity"],"mechanism":"Axial mechanical loading and collagen peptides trigger Piezo1 mechanosensation and osteoblast extracellular matrix mineralization.","studies":[{"pmid":"11683549","title":"Resistance Loading and Vitamin K2 Bone Matrix Accretion","url":"https://pubmed.ncbi.nlm.nih.gov/11683549/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication","Mitochondrial Dysfunction"]'::text[] WHERE id = '42cd4dd2-312d-49bc-a843-5c34e510178c';

UPDATE modalities SET functional_impacts = '{"Energy":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/17256722/","notes":"In patients with NAFLD (a condition strongly associated with fatigue), phlebotomy-induced iron reduction significantly improved insulin sensitivity and liver function, key drivers of metabolic health and energy regulation.","title":"Phlebotomy for nonalcoholic fatty liver disease: a randomized clinical trial"}]},"Brain Fog":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/24726210/","notes":"In a study of symptomatic patients with iron overload (hemochromatosis), treatment with phlebotomy was significantly associated with a reduction in self-reported cognitive complaints, often described as ''brain fog''.","title":"Patient-reported outcomes in individuals diagnosed with HFE-hemochromatosis"}]},"heart_health":{"score":87,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Lowers blood viscosity, prevents iron-catalyzed hydroxyl radical generation in vascular walls","biomarkers":["Blood Viscosity","Serum Ferritin","Arterial Elasticity"],"mechanism":"Reduces excessive iron stores, preventing Fenton reaction-mediated hydroxyl free radical attacks on endothelial lipid membranes.","studies":[{"pmid":"17978138","title":"Reduction of iron stores and cardiovascular outcomes in patients with peripheral arterial disease: A randomized trial","url":"https://pubmed.ncbi.nlm.nih.gov/17978138/","type":"RCT"}]},"Joint Comfort":{"score":5,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/24726210/","notes":"The same study on patients with HFE-hemochromatosis found that treatment via phlebotomy was significantly associated with a reduction in arthralgia (joint pain), a primary symptom of iron overload.","title":"Patient-reported outcomes in individuals diagnosed with HFE-hemochromatosis"}]},"cellular_longevity":{"score":91,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"Up to 30% reduction in persistent bioaccumulated perfluoroalkyl substances (PFAS)","biomarkers":["Serum PFAS / PFOS","Serum Ferritin","Malondialdehyde (MDA)"],"mechanism":"PFAS compounds bind tightly to serum albumin; regular blood/plasma removal forces hepatic de novo synthesis of pristine albumin, clearing recalcitrant forever chemicals.","studies":[{"pmid":"35394503","title":"Effect of Plasma and Blood Donation on Serum Levels of Perfluoroalkyl and Polyfluoroalkyl Substances: A Randomized Clinical Trial (JAMA Netw Open 2022)","url":"https://pubmed.ncbi.nlm.nih.gov/35394503/","type":"RCT"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction","Genomic Instability"]'::text[] WHERE id = 'blood_donation_phlebotomy';

UPDATE modalities SET functional_impacts = '{"Memory":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/29955743/","notes":"This randomized controlled trial found that older adults taking a spermidine-rich plant extract showed significantly improved memory performance compared to placebo, particularly in those with mild cognitive impairment.","title":"The effect of spermidine on memory performance in older adults at risk for dementia: A randomized controlled trial"}]},"Brain Fog":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/33108651/","notes":"In participants with subjective cognitive decline, spermidine supplementation improved memory and reduced the feeling of cognitive impairment, directly addressing the experience of brain fog.","title":"Spermidine-rich plant extract improves cognitive function in major subjective cognitive decline: a randomized, double-blind, placebo-controlled trial"}]},"cancer_defense":{"score":80,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Stimulates macroautophagic clearance and Nrf2 xenobiotic detox","biomarkers":["LC3-II/LC3-I Ratio","p16INK4a","Senescence-Associated Secretory Phenotype (SASP)"],"mechanism":"Downregulates mTORC1 to trigger intracellular autophagosomal engulfment of damaged organelles.","studies":[{"pmid":"30172924","title":"Cellular Senescence and Senolytics in Aging","url":"https://pubmed.ncbi.nlm.nih.gov/30172924/","type":"RCT"}]},"Immune Resilience":{"score":5,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/29906454/","notes":"This large prospective study associated higher dietary spermidine intake with reduced overall, cardiovascular, and cancer-related mortality, highlighting systemic protective effects closely tied to immune system competence (immunosenescence) and reduced inflammation.","title":"Higher spermidine intake is linked to lower mortality: a prospective population-based study"}]},"cellular_longevity":{"score":82,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Maintains genomic stability, telomeric integrity, extracellular collagen matrix, and mitochondrial proteostasis","biomarkers":["DNAmAge (Horvath Clock)","NAD+/NADH Ratio","Dermal Collagen Density","Telomere Length"],"mechanism":"Activates nuclear transcription factors (SIRT1/RAR), photobiomodulates cytochrome c oxidase, or enhances DNA strand break repair.","studies":[{"pmid":"30894380","title":"NAD+ Intermediates and Longevity Therapeutics","url":"https://pubmed.ncbi.nlm.nih.gov/30894380/","type":"Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Disabled Macroautophagy","Loss of Proteostasis"]'::text[] WHERE id = 'spermidine_supplement';

UPDATE modalities SET functional_impacts = '{"Joint Comfort":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/18416885/","notes":"As glycine is the most abundant amino acid in collagen, this study showed that supplementation with collagen hydrolysate (rich in glycine) led to a statistically significant improvement in joint pain at rest, walking, and carrying objects in athletes.","title":"24-Week study on the use of collagen hydrolysate as a dietary supplement in athletes with activity-related joint pain"}]},"Sleep Latency":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/22293292/","notes":"This study found that glycine ingestion before bedtime shortened the time it took to fall asleep (sleep latency) and improved sleep efficiency, as measured by polysomnography.","title":"The effects of glycine on subjective daytime performance in partially sleep-restricted healthy volunteers"}]},"Sleep Quality":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/17292418/","notes":"In a double-blind, placebo-controlled trial, 3g of glycine taken one hour before bedtime significantly improved subjective sleep quality, reduced fatigue upon waking, and improved daytime performance in participants with sleep dissatisfaction.","title":"Glycine ingestion improves subjective sleep quality in human volunteers, correlating with polysomnographic changes"}]},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]},"Waking Restedness":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/17292418/","notes":"Participants taking 3g of glycine before bed reported significantly reduced fatigue and increased liveliness and clear-headedness upon waking the next morning compared to the placebo group.","title":"Glycine ingestion improves subjective sleep quality in human volunteers, correlating with polysomnographic changes"}]}}'::jsonb, hallmarks_of_aging_impact = '["Epigenetic Alterations","Chronic Inflammation","Genomic Instability"]'::text[] WHERE id = 'glycine_supplementation';

UPDATE modalities SET functional_impacts = '{"Mood":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/2398576/","notes":"This foundational epidemiological study found a statistically significant inverse correlation between lithium levels in public drinking water and rates of suicide, homicide, and certain crimes over a 10-year period, suggesting a powerful mood-stabilizing effect at micro-dose levels.","title":"Lithium in drinking water and the incidences of crimes, suicides, and arrests related to drug addictions"}]},"Memory":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28813547/","notes":"This large Danish nationwide, population-based study found that long-term exposure to even micro-levels of lithium in drinking water was associated with a lower incidence of dementia. The rate of dementia was significantly lower in the group with the highest lithium exposure compared to the group with the lowest.","title":"Association of Lithium in Drinking Water With the Incidence of Dementia"}]},"Calmness":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/21551523/","notes":"A meta-analysis of 11 ecological studies confirmed a significant inverse relationship between lithium concentrations in drinking water and suicide rates. Higher natural lithium levels in a population were associated with lower suicide mortality, indicating a population-level calming and mood-protective effect.","title":"Lithium in drinking water and suicide mortality"}]},"cellular_longevity":{"score":82,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Maintains genomic stability, telomeric integrity, extracellular collagen matrix, and mitochondrial proteostasis","biomarkers":["DNAmAge (Horvath Clock)","NAD+/NADH Ratio","Dermal Collagen Density","Telomere Length"],"mechanism":"Activates nuclear transcription factors (SIRT1/RAR), photobiomodulates cytochrome c oxidase, or enhances DNA strand break repair.","studies":[{"pmid":"30894380","title":"NAD+ Intermediates and Longevity Therapeutics","url":"https://pubmed.ncbi.nlm.nih.gov/30894380/","type":"Review"}]},"Emotional Resilience":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/2398576/","notes":"The same landmark study by Schrauzer et al. demonstrated that areas with higher trace levels of lithium in the water supply had significantly lower rates of arrests and violent crimes, pointing towards improved emotional regulation and resilience on a population scale.","title":"Lithium in drinking water and the incidences of crimes, suicides, and arrests related to drug addictions"}]}}'::jsonb, hallmarks_of_aging_impact = '["Loss of Proteostasis","Disabled Macroautophagy"]'::text[] WHERE id = 'lithium_orotate';

UPDATE modalities SET functional_impacts = '{"Autophagy":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/29305904/","notes":"Spermidine induces autophagy across human cells, supporting cellular proteostasis during nocturnal fasting.","title":"Spermidine and Luteolin in overnight autophagic renewal"}]},"Sleep Latency":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/19593179/","notes":"Apigenin acts as a natural GABA-A agonist, calming nervous system hyperexcitability and reducing sleep latency.","title":"Apigenin and Valerian root for sleep onset reduction"}]},"Sleep Quality":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/23853635/","notes":"Magnesium and tryptophan supplementation significantly improves subjective and objective sleep quality measures in adults.","title":"Magnesium and L-Tryptophan synergy in sleep architecture"}]},"cancer_defense":{"score":80,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Stimulates macroautophagic clearance and Nrf2 xenobiotic detox","biomarkers":["LC3-II/LC3-I Ratio","p16INK4a","Senescence-Associated Secretory Phenotype (SASP)"],"mechanism":"Downregulates mTORC1 to trigger intracellular autophagosomal engulfment of damaged organelles.","studies":[{"pmid":"30172924","title":"Cellular Senescence and Senolytics in Aging","url":"https://pubmed.ncbi.nlm.nih.gov/30172924/","type":"RCT"}]},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]},"Waking Restedness":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/30707852/","notes":"L-Theanine promotes alpha brainwave activity, fostering restorative slow-wave sleep without morning sedation.","title":"L-Theanine and botanical extracts in non-rem restorative sleep"}]}}'::jsonb, hallmarks_of_aging_impact = '["Cellular Senescence","Loss of Proteostasis","Chronic Inflammation"]'::text[] WHERE id = 'lifespan_plus_deepcell';

UPDATE modalities SET functional_impacts = '{"Endurance":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/29299883/","notes":"Zone 2 training (lactate < 2.0 mmol/L) maximizes mitochondrial fatty acid oxidation capacity and lactate clearance rates, building the core aerobic engine of longevity.","title":"Assessment of Metabolic Flexibility by Means of Measuring Blood Lactate in Elite Endurance Athletes"}]},"heart_health":{"score":75,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Supports arterial compliance and vascular tone","biomarkers":["Resting Heart Rate","ApoB","Endothelial Elasticity"],"mechanism":"Promotes microvascular nitric oxide bioavailability and reduces lipid peroxidation.","studies":[{"pmid":"30598199","title":"Cardiovascular Risk Reduction and Vascular Elasticity","url":"https://pubmed.ncbi.nlm.nih.gov/30598199/","type":"Clinical Trial"}]},"Physical Energy":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/30605636/","notes":"Prolonged sub-lactate threshold training expands capillary-to-fiber ratio and stimulates type I slow-twitch mitochondrial density.","title":"Mitochondrial density and capillary proliferation following low-intensity endurance exercise"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction"]'::text[] WHERE id = 'hm_zone2_run';

UPDATE modalities SET functional_impacts = '{"Memory":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/17060609/","notes":"In rodent models, oral administration of fisetin activated signaling pathways crucial for long-term memory formation and led to significant enhancements in memory performance.","title":"Fisetin, a flavonoid and novel activator of the mitogen-activated protein kinase cascade, enhances memory"}]},"Brain Fog":{"score":5,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/32333796/","notes":"This study showed that fisetin significantly suppresses inflammatory responses in microglial cells (the brain''s immune cells), a primary driver of neuroinflammation which is strongly linked to sensations of brain fog.","title":"Fisetin inhibits neuroinflammation in microglia and protects neurons from neurotoxicity"}]},"Joint Comfort":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/31772659/","notes":"In a mouse model of osteoarthritis, fisetin treatment significantly reduced cartilage degradation and levels of inflammatory proteins in the joint, preserving joint structure and function.","title":"Fisetin alleviates osteoarthritis by inhibiting the PI3K/Akt/NF-κB signaling pathway"}]},"cancer_defense":{"tier":"synergistic","score":80,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/30172924/","pmid":"30172924","type":"RCT","title":"Cellular Senescence and Senolytics in Aging"}],"mechanism":"Downregulates mTORC1 to trigger intracellular autophagosomal engulfment of damaged organelles.","biomarkers":["LC3-II/LC3-I Ratio","p16INK4a","Senescence-Associated Secretory Phenotype (SASP)"],"effect_size":"Stimulates macroautophagic clearance and Nrf2 xenobiotic detox","evidence_grade":"Grade B (Clinical Trial)"},"Immune Resilience":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/30279143/","notes":"This landmark study demonstrated that fisetin reduces the burden of senescent cells in multiple tissues of aged mice, restoring tissue homeostasis and reducing age-related pathologies, a key mechanism for rejuvenating immune system potential.","title":"Fisetin is a senotherapeutic that extends health and lifespan"}]},"cellular_longevity":{"score":95,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"Selective apoptosis of p16/p21 senescent cells; dramatic reduction in SASP secretome","biomarkers":["p16INK4a","p21 mRNA","SASP Cytokines (IL-6, TNF-alpha)","hs-CRP"],"mechanism":"Downregulates pro-survival SCAP networks (BCL-2, BCL-xL, PI3K/AKT) specifically in senescent cells, triggering apoptosis without harming healthy proliferating cells.","studies":[{"pmid":"29930465","title":"Fisetin is a potent senotherapeutic that extends health and lifespan (EBioMedicine 2018)","url":"https://pubmed.ncbi.nlm.nih.gov/29930465/","type":"Mechanistic / In Vivo"},{"pmid":"31542391","title":"Senolytics decrease senescent cells in humans: First clinical results from Mayo Clinic (EBioMedicine 2019)","url":"https://pubmed.ncbi.nlm.nih.gov/31542391/","type":"RCT"}]},"inflammation_status":{"score":92,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"40% reduction in circulating senescent-associated secretory phenotype (SASP) cytokines","biomarkers":["hs-CRP","Serum IL-6","TNF-alpha","MMP-3"],"mechanism":"Eliminates the cellular factories of chronic inflammaging, lowering tissue basal immune stress.","studies":[{"pmid":"31542391","title":"Senolytics Decrease Senescent Cells in Humans: Mayo Clinic Trial","url":"https://pubmed.ncbi.nlm.nih.gov/31542391/","type":"RCT"}]}}'::jsonb, hallmarks_of_aging_impact = '["Cellular Senescence","Chronic Inflammation (Inflammaging)"]'::text[] WHERE id = 'fisetin';

UPDATE modalities SET functional_impacts = '{"anxiety":{"score":8,"rationale":"Hyper-capnic hold relaxes vascular smooth muscle."},"sleep_latency":{"score":10,"rationale":"Vagal deceleration rapidly induces pre-sleep parasympathetic dominance."},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]},"stress_resilience":{"score":9,"rationale":"Extended exhale lowers heart rate and blunts sympathetic spikes."},"chronic_inflammation":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Blunts systemic neuro-inflammatory stress response and cytokine release","biomarkers":["hs-CRP","Salivary Cortisol"],"mechanism":"Cholinergic anti-inflammatory pathway activation downregulates peripheral macrophage cytokine production.","studies":[{"pmid":"24799686","title":"Voluntary Activation of the Sympathetic Nervous System and Attenuation of the Innate Immune Response","url":"https://pubmed.ncbi.nlm.nih.gov/24799686/","type":"RCT"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication"]'::text[] WHERE id = 'breathing_4_7_8';

UPDATE modalities SET functional_impacts = '{"Mental Focus":{"score":9},"Skin Clarity":{"score":8},"heart_health":{"score":75,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Supports arterial compliance and vascular tone","biomarkers":["Resting Heart Rate","ApoB","Endothelial Elasticity"],"mechanism":"Promotes microvascular nitric oxide bioavailability and reduces lipid peroxidation.","studies":[{"pmid":"30598199","title":"Cardiovascular Risk Reduction and Vascular Elasticity","url":"https://pubmed.ncbi.nlm.nih.gov/30598199/","type":"Clinical Trial"}]},"Overall Energy":{"score":8}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction","Chronic Inflammation"]'::text[] WHERE id = 'rhonda_omega3_phospholipids';

UPDATE modalities SET functional_impacts = '{"Muscular Strength":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/25982160/","notes":"The Lancet study of 140,000 adults demonstrating that grip strength is a stronger predictor of all-cause and cardiovascular mortality than systolic blood pressure.","title":"Grip strength as a predictor of cardiovascular events, stroke, and all-cause mortality (PURE Study)"}]},"Blood Pressure Regulation":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/24582195/","notes":"Mayo Clinic Proceedings meta-analysis showing isometric handgrip training (4x 2-min holds @ 30% MVC, 3x/week) reduces systolic blood pressure by ~5.2 mmHg and diastolic by ~3.9 mmHg via reactive hyperemia and eNOS upregulation.","title":"Isometric exercise training for blood pressure management: a systematic review and meta-analysis"}]},"bone_density":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Stimulates osteoblast mechanotransduction, tendon remodeling, and connective tissue collagen deposition","biomarkers":["DEXA Lumbar T-Score","Serum P1NP","Tendon Stiffness & Joint Elasticity"],"mechanism":"Axial mechanical loading and collagen peptides trigger Piezo1 mechanosensation and osteoblast extracellular matrix mineralization.","studies":[{"pmid":"11683549","title":"Resistance Loading and Vitamin K2 Bone Matrix Accretion","url":"https://pubmed.ncbi.nlm.nih.gov/11683549/","type":"Meta-Analysis"}]},"heart_health":{"score":82,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"Expands stroke volume, improves VO2 Max, and enhances microvascular perfusion","biomarkers":["VO2 Max","Resting Heart Rate","Arterial Compliance"],"mechanism":"High-workload aerobic-anaerobic conditioning drives eccentric left ventricular adaptation and capillarization.","studies":[{"pmid":"22425076","title":"High-Workload Exercise Training and Cardiovascular Endpoints","url":"https://pubmed.ncbi.nlm.nih.gov/22425076/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction","Epigenetic Alterations","Chronic Inflammation"]'::text[] WHERE id = 'dayspring_isometric_handgrip_protocol';

UPDATE modalities SET functional_impacts = '{"Energy":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/33567185/","notes":"In the STEP 1 trial, participants receiving semaglutide reported significantly greater improvements in physical functioning scores (a proxy for energy and vitality) on the SF-36 quality of life questionnaire compared to placebo.","title":"Once-Weekly Semaglutide in Adults with Overweight or Obesity"}]},"Satiety":{"score":10,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/33567185/","notes":"The landmark STEP 1 trial demonstrated a mean body weight reduction of 14.9% with semaglutide, primarily driven by a profound reduction in appetite and caloric intake.","title":"Once-Weekly Semaglutide in Adults with Overweight or Obesity"}]},"Brain Fog":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/27589253/","notes":"This study showed that treatment with the GLP-1 agonist liraglutide was associated with significant improvements in cognitive function scores, including memory and executive function, in older adults.","title":"The effects of liraglutide on cognitive functions in older patients with type 2 diabetes"}]},"heart_health":{"score":75,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Supports arterial compliance and vascular tone","biomarkers":["Resting Heart Rate","ApoB","Endothelial Elasticity"],"mechanism":"Promotes microvascular nitric oxide bioavailability and reduces lipid peroxidation.","studies":[{"pmid":"30598199","title":"Cardiovascular Risk Reduction and Vascular Elasticity","url":"https://pubmed.ncbi.nlm.nih.gov/30598199/","type":"Clinical Trial"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction","Deregulated Nutrient Sensing","Chronic Inflammation"]'::text[] WHERE id = 'glp_1_receptor_agonists';

UPDATE modalities SET functional_impacts = '{"Soreness":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/22295281/","notes":"J Environ Public Health study showing grounding and low-frequency PEMF accelerate resolution of exercise-induced delayed muscle soreness and reduce serum creatine kinase concentrations.","title":"Earthing and pulsed electromagnetic field effects on inflammation, immune response, and delayed muscle soreness"}]},"Deep Sleep Quality":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/15479968/","notes":"Grounding resynchronizes evening cortisol circadian rhythms and promotes deeper slow-wave restorative sleep.","title":"Biological effects of grounding during sleep on nocturnal cortisol levels and sleep quality"}]},"cellular_longevity":{"score":82,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Maintains genomic stability, telomeric integrity, extracellular collagen matrix, and mitochondrial proteostasis","biomarkers":["DNAmAge (Horvath Clock)","NAD+/NADH Ratio","Dermal Collagen Density","Telomere Length"],"mechanism":"Activates nuclear transcription factors (SIRT1/RAR), photobiomodulates cytochrome c oxidase, or enhances DNA strand break repair.","studies":[{"pmid":"30894380","title":"NAD+ Intermediates and Longevity Therapeutics","url":"https://pubmed.ncbi.nlm.nih.gov/30894380/","type":"Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Chronic Inflammation"]'::text[] WHERE id = 'brecka_pemf_grounding';

UPDATE modalities SET functional_impacts = '{"Strength":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/26353786/","notes":"In elderly men with sarcopenia, combining collagen peptide supplementation with resistance training resulted in significantly greater improvements in muscle strength and fat-free mass compared to placebo.","title":"Collagen peptide supplementation in combination with resistance training improves body composition and increases muscle strength in elderly sarcopenic men: a randomised controlled trial"}]},"Skin Clarity":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/23949208/","notes":"This study on 69 women aged 35-55 found that oral supplementation with collagen peptides for 8 weeks led to a statistically significant increase in skin elasticity compared to placebo.","title":"Oral supplementation of specific collagen peptides has beneficial effects on human skin physiology: a double-blind, placebo-controlled study"}]},"Joint Comfort":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/18416885/","notes":"In a study of 147 athletes, collagen hydrolysate supplementation resulted in statistically significant improvements in activity-related joint pain compared to placebo.","title":"24-Week study on the use of collagen hydrolysate as a dietary supplement in athletes with activity-related joint pain"}]},"bone_density":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Stimulates osteoblast mechanotransduction, tendon remodeling, and connective tissue collagen deposition","biomarkers":["DEXA Lumbar T-Score","Serum P1NP","Tendon Stiffness & Joint Elasticity"],"mechanism":"Axial mechanical loading and collagen peptides trigger Piezo1 mechanosensation and osteoblast extracellular matrix mineralization.","studies":[{"pmid":"11683549","title":"Resistance Loading and Vitamin K2 Bone Matrix Accretion","url":"https://pubmed.ncbi.nlm.nih.gov/11683549/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication"]'::text[] WHERE id = 'collagen_peptides';

UPDATE modalities SET functional_impacts = '{"Autophagy":{"score":10},"Fat Burning":{"score":10},"cancer_defense":{"score":80,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Stimulates macroautophagic clearance and Nrf2 xenobiotic detox","biomarkers":["LC3-II/LC3-I Ratio","p16INK4a","Senescence-Associated Secretory Phenotype (SASP)"],"mechanism":"Downregulates mTORC1 to trigger intracellular autophagosomal engulfment of damaged organelles.","studies":[{"pmid":"30172924","title":"Cellular Senescence and Senolytics in Aging","url":"https://pubmed.ncbi.nlm.nih.gov/30172924/","type":"RCT"}]},"Stem Cell Reset":{"score":9},"metabolic_health":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Improves peripheral insulin sensitivity and AMPK signaling","biomarkers":["Fasting Insulin","HOMA-IR","HbA1c"],"mechanism":"Activates hepatic and muscular AMPK phosphorylation to facilitate glucose uptake.","studies":[{"pmid":"32060683","title":"Targeting AMPK in Metabolic Disease and Aging","url":"https://pubmed.ncbi.nlm.nih.gov/32060683/","type":"Systematic Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Disabled Macroautophagy","Deregulated Nutrient Sensing"]'::text[] WHERE id = 'monk_fast_36h';

UPDATE modalities SET functional_impacts = '{"Focus":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/12945830/","notes":"This study demonstrated that creatine supplementation significantly improved performance on working memory and intelligence tasks, particularly those requiring speed of processing, suggesting it supports cognitively demanding activities.","title":"Oral creatine monohydrate supplementation improves brain performance: a double-blind, placebo-controlled, cross-over trial"}]},"Soreness":{"score":5,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/15306159/","notes":"Athletes supplementing with creatine before and during an endurance event showed significantly reduced markers of cell damage (creatine kinase) and inflammation (prostaglandin E2), correlating with reduced muscle soreness.","title":"The effect of creatine supplementation upon inflammatory and muscle soreness markers after a 30km race"}]},"Strength":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/14636102/","notes":"This cornerstone meta-analysis found that creatine supplementation combined with resistance training increases maximal strength by an average of 8% and weightlifting performance by 14% more than placebo.","title":"Effects of creatine supplementation and resistance training on muscle strength and weightlifting performance"}]},"brain_longevity":{"score":92,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"Significant improvement in working memory, executive function, and rapid reversal of sleep deprivation fatigue","biomarkers":["Executive Processing Speed","Serum BDNF"],"mechanism":"Crosses blood-brain barrier via SLC6A8 to replenish cerebral phosphocreatine stores, buffering neuronal ATP during cognitive stress and hypoxia.","studies":[{"pmid":"38418464","title":"Single Dose Creatine Rapidly Reverses Brain Fatigue RCT (Scientific Reports 2024)","url":"https://pubmed.ncbi.nlm.nih.gov/38418464/","type":"RCT"},{"pmid":"36316270","title":"Effects of creatine supplementation on cognitive function of healthy individuals: A systematic review of randomized controlled trials","url":"https://pubmed.ncbi.nlm.nih.gov/36316270/","type":"Meta-Analysis"}]},"cellular_longevity":{"score":80,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Shields mitochondrial membrane integrity, lowers markers of lipid and protein oxidation","biomarkers":["Mitochondrial Membrane Potential","Whole Blood NAD+ Level"],"mechanism":"Acts as an energy shuttle preventing mitochondrial ADP accumulation and reducing mitochondrial ROS generation.","studies":[{"pmid":"28615996","title":"International Society of Sports Nutrition position stand: safety and efficacy of creatine supplementation in exercise, sport, and medicine","url":"https://pubmed.ncbi.nlm.nih.gov/28615996/","type":"Systematic Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction"]'::text[] WHERE id = 'creatine_monohydrate';

UPDATE modalities SET functional_impacts = '{"Physical Energy":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/29541338/","notes":"Enhances metabolic flexibility by switching cells toward efficient lipid fuel oxidation.","title":"AMPK activation and cellular energy balance in mitochondrial aging"}]},"Glycemic Control":{"score":10,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/27304507/","notes":"Cell Metabolism review by Barzilai et al. detailing how AMPK activation and complex I inhibition improve hepatic insulin sensitivity and extend healthspan across clinical populations.","title":"Metformin as a Tool to Target Aging: Mechanistic Insights from TAME"}]},"metabolic_health":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Improves peripheral insulin sensitivity and AMPK signaling","biomarkers":["Fasting Insulin","HOMA-IR","HbA1c"],"mechanism":"Activates hepatic and muscular AMPK phosphorylation to facilitate glucose uptake.","studies":[{"pmid":"32060683","title":"Targeting AMPK in Metabolic Disease and Aging","url":"https://pubmed.ncbi.nlm.nih.gov/32060683/","type":"Systematic Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Deregulated Nutrient Sensing"]'::text[] WHERE id = 'sinclair_metformin_berberine';

