UPDATE modalities SET functional_impacts = '{"Mood":{"score":5,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/30196522/","notes":"This clinical trial found that CoQ10, when used as an add-on therapy for patients with bipolar depression, resulted in a significant reduction in depression scores compared to placebo over 8 weeks.","title":"Evaluating the Effect of Coenzyme Q10 Augmentation on Treatment of Bipolar Depression: A Double-Blind Controlled Clinical Trial"}]},"Energy":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/36728514/","notes":"This 2023 meta-analysis of 17 randomized controlled trials found that CoQ10 supplementation significantly improved fatigue scores compared to placebo, particularly in individuals with conditions associated with fatigue.","title":"The effect of coenzyme Q10 supplementation on fatigue: A systematic review and meta-analysis of interventional studies"}]},"Soreness":{"score":5,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/22459704/","notes":"This study on professional athletes found that CoQ10 supplementation reduced markers of muscle damage (creatine kinase) and inflammation (IL-6) following strenuous exercise, suggesting a protective effect that can mitigate soreness.","title":"Coenzyme Q(10) supplementation ameliorates inflammatory signaling and oxidative stress associated with strenuous exercise"}]},"Endurance":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/18413341/","notes":"In this double-blind, placebo-controlled study, trained athletes supplementing with CoQ10 showed a statistically significant increase in maximal power output and time to exhaustion during cycling exercises.","title":"Effects of coenzyme Q10 supplementation on exercise performance in trained athletes"}]},"heart_health":{"score":75,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Supports arterial compliance and vascular tone","biomarkers":["Resting Heart Rate","ApoB","Endothelial Elasticity"],"mechanism":"Promotes microvascular nitric oxide bioavailability and reduces lipid peroxidation.","studies":[{"pmid":"30598199","title":"Cardiovascular Risk Reduction and Vascular Elasticity","url":"https://pubmed.ncbi.nlm.nih.gov/30598199/","type":"Clinical Trial"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction"]'::text[] WHERE id = 'coq10';

UPDATE modalities SET functional_impacts = '{"Energy":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/35513475/","notes":"A 12-week randomized, double-blind, placebo-controlled trial found that 250 mg/day of NMN supplementation in older men significantly improved physical performance (gait speed, grip strength) and tended to reduce drowsiness, indicating an increase in functional energy.","title":"Chronic nicotinamide mononucleotide supplementation elevates blood nicotinamide adenine dinucleotide levels and alters muscle function in healthy older men"}]},"Endurance":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/35058784/","notes":"In this 6-week study on amateur runners, NMN supplementation improved aerobic capacity, as measured by VO2 max and ventilatory threshold, with the benefits being more pronounced in higher dosage groups (600 and 1200 mg/day).","title":"Effect of 12-Week Nicotinamide Mononucleotide (NMN) Supplementation on Aerobic Capacity, Muscular Strength, and Body Composition in Healthy Amateur Runners"}]},"Waking Restedness":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/32062539/","notes":"While primarily a safety and pharmacokinetic study, it also assessed sleep quality using the Pittsburgh Sleep Quality Index (PSQI). After 12 weeks, the NMN group showed significant improvements in sleep duration, sleep latency, and daytime sleepiness.","title":"Effect of oral administration of nicotinamide mononucleotide on clinical parameters and nicotinamide metabolite levels in healthy Japanese men"}]},"cellular_longevity":{"score":82,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Maintains genomic stability, telomeric integrity, extracellular collagen matrix, and mitochondrial proteostasis","biomarkers":["DNAmAge (Horvath Clock)","NAD+/NADH Ratio","Dermal Collagen Density","Telomere Length"],"mechanism":"Activates nuclear transcription factors (SIRT1/RAR), photobiomodulates cytochrome c oxidase, or enhances DNA strand break repair.","studies":[{"pmid":"30894380","title":"NAD+ Intermediates and Longevity Therapeutics","url":"https://pubmed.ncbi.nlm.nih.gov/30894380/","type":"Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Genomic Instability","Epigenetic Alterations","Mitochondrial Dysfunction"]'::text[] WHERE id = 'nmn';

UPDATE modalities SET functional_impacts = '{"Skin Clarity":{"score":7},"Overall Energy":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/31534937/","title":"Senolytics reduce senescent cell burden in human clinical trials"}]},"cancer_defense":{"score":80,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Stimulates macroautophagic clearance and Nrf2 xenobiotic detox","biomarkers":["LC3-II/LC3-I Ratio","p16INK4a","Senescence-Associated Secretory Phenotype (SASP)"],"mechanism":"Downregulates mTORC1 to trigger intracellular autophagosomal engulfment of damaged organelles.","studies":[{"pmid":"30172924","title":"Cellular Senescence and Senolytics in Aging","url":"https://pubmed.ncbi.nlm.nih.gov/30172924/","type":"RCT"}]}}'::jsonb, hallmarks_of_aging_impact = '["Cellular Senescence"]'::text[] WHERE id = 'fisetin_quercetin_senolytic_pulse';

UPDATE modalities SET functional_impacts = '{"Sleep Latency":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/25535358/","notes":"PNAS study demonstrating that evening blue light suppresses pineal melatonin secretion by up to 55% and delays the circadian clock by over 1.5 hours, increasing sleep onset latency.","title":"Evening use of light-emitting devices negatively affects sleep, circadian timing, and morning alertness"}]},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]},"Waking Restedness":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/21552179/","notes":"Dimming blue light 2 hours before bed accelerates melatonin phase shift, producing deeper early-night slow-wave sleep and higher subjective waking vigor.","title":"Circadian blue-light filtering and nocturnal melatonin secretion dynamics"}]}}'::jsonb, hallmarks_of_aging_impact = '["Genomic Instability","Altered Intercellular Communication"]'::text[] WHERE id = 'walker_melatonin_dimming';

UPDATE modalities SET functional_impacts = '{"heart_health":{"score":75,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Supports arterial compliance and vascular tone","biomarkers":["Resting Heart Rate","ApoB","Endothelial Elasticity"],"mechanism":"Promotes microvascular nitric oxide bioavailability and reduces lipid peroxidation.","studies":[{"pmid":"30598199","title":"Cardiovascular Risk Reduction and Vascular Elasticity","url":"https://pubmed.ncbi.nlm.nih.gov/30598199/","type":"Clinical Trial"}]},"Immune Resilience":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/22280901/","notes":"Increased gamma-delta T-cells and NK cell proliferation, reducing cold/flu severity by 61%.","title":"Aged Garlic Extract Modulates Human Immune Response: A Randomized Trial"}]},"Cardiovascular Health":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/26764332/","notes":"Double-blind RCT showing 80% reduction in soft plaque progression and coronary artery calcification over 1 year.","title":"Aged Garlic Extract Reduces Low-Attenuation Coronary Plaque Volume"}]},"Blood Pressure Control":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/23725884/","notes":"Significantly reduced mean systolic BP by 11.5 mmHg via endothelial nitric oxide and hydrogen sulfide production.","title":"Aged Garlic Extract Lowers Blood Pressure in Hypertensive Patients"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction"]'::text[] WHERE id = 'aged-garlic-extract';

UPDATE modalities SET functional_impacts = '{"Pain":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/23103622/","notes":"This 12-month, randomized, placebo-controlled trial found that oral hyaluronic acid significantly reduced knee pain scores and symptoms of osteoarthritis in subjects aged 70 years or younger.","title":"Oral administration of polymer hyaluronic acid alleviates symptoms of knee osteoarthritis: a double-blind, placebo-controlled study over a 12-month period"}]},"Skin Clarity":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/25014997/","notes":"In a randomized, double-blind, placebo-controlled study, subjects taking oral hyaluronic acid for 6 weeks showed significantly increased skin moisture and a reduction in wrinkles compared to the placebo group.","title":"Ingested hyaluronan moisturizes dry skin"}]},"Joint Comfort":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/26490560/","notes":"A meta-analysis of randomized placebo-controlled trials concluded that oral hyaluronic acid is an effective treatment for knee osteoarthritis, significantly improving symptoms like pain and joint function.","title":"Oral hyaluronan relieves knee pain: a review"}]},"bone_density":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Stimulates osteoblast mechanotransduction, tendon remodeling, and connective tissue collagen deposition","biomarkers":["DEXA Lumbar T-Score","Serum P1NP","Tendon Stiffness & Joint Elasticity"],"mechanism":"Axial mechanical loading and collagen peptides trigger Piezo1 mechanosensation and osteoblast extracellular matrix mineralization.","studies":[{"pmid":"11683549","title":"Resistance Loading and Vitamin K2 Bone Matrix Accretion","url":"https://pubmed.ncbi.nlm.nih.gov/11683549/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Dysbiosis"]'::text[] WHERE id = 'hyaluronic_acid_oral';

UPDATE modalities SET functional_impacts = '{"Energy":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/33888596/","notes":"This landmark study showed that 10 weeks of NMN supplementation improved muscle insulin sensitivity and signaling in postmenopausal women with prediabetes, a key marker of improved metabolic health and cellular energy utilization.","title":"Nicotinamide mononucleotide increases muscle insulin sensitivity in prediabetic women"}]},"Endurance":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/34238308/","notes":"Healthy amateur runners taking NMN for 6 weeks showed dose-dependent improvements in aerobic capacity (VO2 max and ventilatory threshold), suggesting enhanced oxygen utilization during exercise.","title":"Nicotinamide mononucleotide supplementation enhances aerobic capacity in amateur runners: a randomized, double-blind study"}]},"Sleep Quality":{"score":5,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/36014894/","notes":"Older adults taking NMN in the afternoon for 12 weeks experienced significant improvements in sleep quality measured by the Pittsburgh Sleep Quality Index (PSQI), alongside reduced fatigue and better physical performance.","title":"Effect of 12-Week Intake of Nicotinamide Mononucleotide on Sleep Quality, Fatigue, and Physical Performance in Older Japanese Adults: A Randomized, Double-Blind Placebo-Controlled Study"}]},"cellular_longevity":{"score":82,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Maintains genomic stability, telomeric integrity, extracellular collagen matrix, and mitochondrial proteostasis","biomarkers":["DNAmAge (Horvath Clock)","NAD+/NADH Ratio","Dermal Collagen Density","Telomere Length"],"mechanism":"Activates nuclear transcription factors (SIRT1/RAR), photobiomodulates cytochrome c oxidase, or enhances DNA strand break repair.","studies":[{"pmid":"30894380","title":"NAD+ Intermediates and Longevity Therapeutics","url":"https://pubmed.ncbi.nlm.nih.gov/30894380/","type":"Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Genomic Instability","Epigenetic Alterations"]'::text[] WHERE id = 'nad_precursors';

UPDATE modalities SET functional_impacts = '{"Physical Energy":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/33783832/","notes":"Clinical trial in J Gerontol A showing GlyNAC supplementation for 24 weeks reversed intracellular glutathione deficiency, corrected mitochondrial fuel oxidation, lowered systemic inflammation, and improved physical strength.","title":"Supplementing Glycine and N-Acetylcysteine (GlyNAC) in Older Adults Improves Glutathione Deficiency, Mitochondrial Dysfunction, and Hallmarks of Aging"}]},"Muscular Strength":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/35975308/","notes":"Supplying both rate-limiting glutathione precursors restored muscle power output and lowered toxic lipid hydroperoxides.","title":"GlyNAC supplementation improves cognitive performance, gait speed, and muscular strength in humans"}]},"cellular_longevity":{"score":82,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Maintains genomic stability, telomeric integrity, extracellular collagen matrix, and mitochondrial proteostasis","biomarkers":["DNAmAge (Horvath Clock)","NAD+/NADH Ratio","Dermal Collagen Density","Telomere Length"],"mechanism":"Activates nuclear transcription factors (SIRT1/RAR), photobiomodulates cytochrome c oxidase, or enhances DNA strand break repair.","studies":[{"pmid":"30894380","title":"NAD+ Intermediates and Longevity Therapeutics","url":"https://pubmed.ncbi.nlm.nih.gov/30894380/","type":"Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction","Epigenetic Alterations","Chronic Inflammation"]'::text[] WHERE id = 'glynac_glutathione_pulse';

UPDATE modalities SET functional_impacts = '{"Focus":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/11081987/","notes":"A double-blind crossover study of physicians on night duty found that Rhodiola extract significantly reduced mental fatigue and improved performance on complex cognitive tasks by approximately 20% compared to placebo.","title":"Rhodiola rosea in stress induced fatigue--a double blind cross-over study of a standardized extract SHR-5 with a repeated low-dose regimen on the mental performance of healthy physicians during night duty"}]},"Energy":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/10839209/","notes":"This double-blind, placebo-controlled study demonstrated that students taking Rhodiola during a stressful examination period had significantly reduced fatigue, improved well-being, and better physical and mental performance scores.","title":"A double-blind, placebo-controlled pilot study of the stimulating and adaptogenic effect of Rhodiola rosea SHR-5 extract in students on a background of stress and fatigue with respect to their exams"}]},"Stress":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/19016404/","notes":"This randomized controlled trial on 60 subjects with stress-related fatigue found that Rhodiola extract SHR-5 significantly reduced cortisol awakening response and improved performance on mental fatigue tests compared to placebo.","title":"A randomised, double-blind, placebo-controlled, parallel-group study of the standardised extract shr-5 of the roots of Rhodiola rosea in the treatment of subjects with stress-related fatigue"}]},"Emotional Resilience":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/25837277/","notes":"In a randomized trial for mild-to-moderate major depressive disorder, Rhodiola significantly reduced depressive symptoms, offering a favorable risk-to-benefit ratio and highlighting its role in supporting emotional balance.","title":"Rhodiola rosea versus sertraline for major depressive disorder: A randomized placebo-controlled trial"}]},"bone_density":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Stimulates osteoblast mechanotransduction, tendon remodeling, and connective tissue collagen deposition","biomarkers":["DEXA Lumbar T-Score","Serum P1NP","Tendon Stiffness & Joint Elasticity"],"mechanism":"Axial mechanical loading and collagen peptides trigger Piezo1 mechanosensation and osteoblast extracellular matrix mineralization.","studies":[{"pmid":"11683549","title":"Resistance Loading and Vitamin K2 Bone Matrix Accretion","url":"https://pubmed.ncbi.nlm.nih.gov/11683549/","type":"Meta-Analysis"}]},"heart_health":{"score":82,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"Expands stroke volume, improves VO2 Max, and enhances microvascular perfusion","biomarkers":["VO2 Max","Resting Heart Rate","Arterial Compliance"],"mechanism":"High-workload aerobic-anaerobic conditioning drives eccentric left ventricular adaptation and capillarization.","studies":[{"pmid":"22425076","title":"High-Workload Exercise Training and Cardiovascular Endpoints","url":"https://pubmed.ncbi.nlm.nih.gov/22425076/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication","Mitochondrial Dysfunction"]'::text[] WHERE id = 'rhodiola_rosea';

UPDATE modalities SET functional_impacts = '{"Soreness":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/31804179/","notes":"Pulsed senolytics clear destructive senescence-associated secretory phenotype (SASP) proteases from articular joints, restoring painless mobility.","title":"Senolytic ablation of senescent chondrocytes alleviates post-traumatic osteoarthritis and joint pain"}]},"Joint Comfort":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/30279143/","notes":"Landmark EBioMedicine study from the Mayo Clinic showing intermittent high-dose pulsed Fisetin selectively induces apoptosis in senescent cells, suppresses pro-inflammatory SASP cytokines, and restores tissue homeostasis.","title":"Fisetin is a senotherapeutic that extends health and lifespan and clears senescent cells in aged tissues"}]},"cancer_defense":{"score":80,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Stimulates macroautophagic clearance and Nrf2 xenobiotic detox","biomarkers":["LC3-II/LC3-I Ratio","p16INK4a","Senescence-Associated Secretory Phenotype (SASP)"],"mechanism":"Downregulates mTORC1 to trigger intracellular autophagosomal engulfment of damaged organelles.","studies":[{"pmid":"30172924","title":"Cellular Senescence and Senolytics in Aging","url":"https://pubmed.ncbi.nlm.nih.gov/30172924/","type":"RCT"}]}}'::jsonb, hallmarks_of_aging_impact = '["Cellular Senescence"]'::text[] WHERE id = 'longo_fisetin_quercetin_senolytic_pulse';

UPDATE modalities SET functional_impacts = '{"Energy":{"score":5,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28757962/","notes":"This pilot study on trained athletes found that 8 weeks of MK-7 supplementation was associated with a 12% increase in maximal cardiac output, a key determinant of endurance performance and energy availability during exercise.","title":"Oral Consumption of Vitamin K2 for 8 Weeks Associated With Increased Maximal Cardiac Output During Exercise"}]},"Strength":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/23495440/","notes":"This 3-year, double-blind, placebo-controlled trial found that 180 mcg/day of MK-7 significantly improved vitamin K status and decreased age-related decline in bone mineral density and bone strength in healthy postmenopausal women.","title":"Three-year low-dose menaquinone-7 supplementation helps prevent bone loss in healthy postmenopausal women"}]},"bone_density":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Stimulates osteoblast mechanotransduction, tendon remodeling, and connective tissue collagen deposition","biomarkers":["DEXA Lumbar T-Score","Serum P1NP","Tendon Stiffness & Joint Elasticity"],"mechanism":"Axial mechanical loading and collagen peptides trigger Piezo1 mechanosensation and osteoblast extracellular matrix mineralization.","studies":[{"pmid":"11683549","title":"Resistance Loading and Vitamin K2 Bone Matrix Accretion","url":"https://pubmed.ncbi.nlm.nih.gov/11683549/","type":"Meta-Analysis"}]},"heart_health":{"score":75,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Supports arterial compliance and vascular tone","biomarkers":["Resting Heart Rate","ApoB","Endothelial Elasticity"],"mechanism":"Promotes microvascular nitric oxide bioavailability and reduces lipid peroxidation.","studies":[{"pmid":"30598199","title":"Cardiovascular Risk Reduction and Vascular Elasticity","url":"https://pubmed.ncbi.nlm.nih.gov/30598199/","type":"Clinical Trial"}]},"Joint Comfort":{"score":5,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/23389518/","notes":"This large observational study found that low plasma vitamin K levels were associated with an increased risk of developing and progressing knee osteoarthritis, suggesting a protective role in maintaining joint cartilage and structure.","title":"Vitamin K deficiency is associated with incident and progressive radiographic knee osteoarthritis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction"]'::text[] WHERE id = 'vitamin_k2_mk7';

UPDATE modalities SET functional_impacts = '{"Focus":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/22746404","notes":"In this randomized, placebo-controlled trial, elderly participants taking Bacopa for 12 weeks showed significant improvements in attention and cognitive processing speed compared to placebo.","title":"Effects of 12-Week Bacopa monnieri Consumption on Attention, Cognitive Processing, Working Memory, and Functions of both Cholinergic and Monoaminergic Systems in Healthy Elderly Volunteers"}]},"Memory":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/11498727","notes":"This landmark double-blind RCT found that 12 weeks of Bacopa supplementation (300 mg/day) significantly improved the rate of learning, memory consolidation, and information processing in healthy adults.","title":"The chronic effects of an extract of Bacopa monniera (Brahmi) on cognitive function in healthy human subjects"}]},"Stress":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/18611150","notes":"This 12-week RCT demonstrated that Bacopa extract significantly reduced scores on anxiety scales in participants over 65, highlighting its adaptogenic and anxiolytic properties.","title":"Effects of a standardized Bacopa monnieri extract on cognitive performance, anxiety, and depression in the elderly: a randomized, double-blind, placebo-controlled trial"}]},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication","Mitochondrial Dysfunction"]'::text[] WHERE id = 'bacopa_monnieri';

UPDATE modalities SET functional_impacts = '{"Mood":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/29800984/","notes":"A meta-analysis of 33 randomized clinical trials found that resistance training was associated with a significant reduction in depressive symptoms, supporting its role as an effective mood-enhancing therapy.","title":"Association of Efficacy of Resistance Exercise Training With Depressive Symptoms: Meta-analysis and Meta-regression Analysis of Randomized Clinical Trials"}]},"Energy":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/35535805/","notes":"A meta-analysis of 16 studies demonstrated that resistance training has a significant, moderate effect on reducing fatigue and improving energy levels in both healthy and clinical populations.","title":"Resistance training for fatigue in disease and healthy populations: A systematic review and meta-analysis"}]},"Strength":{"score":10,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28834797/","notes":"This meta-analysis firmly establishes that resistance training leads to substantial increases in muscular strength, regardless of whether high or low loads are used, confirming it as the principal method for strength development.","title":"Strength and Hypertrophy Adaptations Between Low- vs. High-Load Resistance Training: A Systematic Review and Meta-analysis"}]},"bone_density":{"score":96,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"+2.5–3.8% increase in lumbar spine and femoral neck BMD in adults","biomarkers":["DEXA Femoral Neck T-Score","Serum P1NP","Serum CTx"],"mechanism":"High-magnitude axial ground reaction forces deform the crystalline bone matrix, creating fluid shear stress across osteocytes via Piezo1 ion channels to trigger osteoblastic mineral deposition.","studies":[{"pmid":"28975375","title":"High-Intensity Resistance and Impact Training Improves Bone Mineral Density and Physical Function in Postmenopausal Women (LIFTMOR Trial)","url":"https://pubmed.ncbi.nlm.nih.gov/28975375/","type":"RCT"},{"pmid":"30232483","title":"Targeted exercise for bone density in aging adults: systematic review","url":"https://pubmed.ncbi.nlm.nih.gov/30232483/","type":"Meta-Analysis"}]},"testosterone":{"score":90,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"Significant acute and chronic elevation in bioavailable free testosterone","biomarkers":["Total Testosterone","Free Testosterone","Morning Cortisol : Testosterone"],"mechanism":"Large muscle mass recruitment (squats, deadlifts) stimulates hypothalamic GnRH pulse frequency while upregulating skeletal muscle androgen receptor (AR) content.","studies":[{"pmid":"17530977","title":"Endocrine and hormonal adaptations to resistance exercise in men","url":"https://pubmed.ncbi.nlm.nih.gov/17530977/","type":"Review"}]},"Joint Comfort":{"score":5,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/34215753/","notes":"This meta-analysis found that resistance training significantly reduced pain intensity in patients with chronic pain conditions like fibromyalgia, suggesting a direct benefit for joint and muscle comfort.","title":"Effect of resistance training on pain in adults with fibromyalgia: A systematic review and meta-analysis of randomized controlled trials"}]},"metabolic_health":{"score":88,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"Increases whole-body glucose disposal capacity proportionally to myofibrillar hypertrophy","biomarkers":["HbA1c","Fasting Insulin"],"mechanism":"Expands the body’s largest non-insulin-mediated glucose reservoir (skeletal muscle mass) and boosts resting metabolic rate (RMR).","studies":[{"pmid":"28630650","title":"Resistance training and metabolic health: a systematic review of RCTs","url":"https://pubmed.ncbi.nlm.nih.gov/28630650/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Epigenetic Alterations","Stem Cell Exhaustion"]'::text[] WHERE id = 'resistance_training';

UPDATE modalities SET functional_impacts = '{"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]},"Systemic Recovery":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/10523415/","notes":"Pulsatile growth hormone acceleration promotes collagen synthesis, connective tissue repair, and slow-wave sleep depth.","title":"Growth hormone secretagogues in nitrogen retention, protein synthesis, and lean tissue preservation"}]},"Deep Sleep Quality":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/9849822/","notes":"Eur J Endocrinol study proving Ipamorelin selectively binds ghrelin/GHS-R1a receptors to stimulate physiologic nocturnal GH pulses without elevating cortisol, ACTH, or prolactin.","title":"Ipamorelin, the first selective growth hormone secretagogue: receptor selectivity and pituitary pulsatility"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication"]'::text[] WHERE id = 'ipamorelin_subq';

