UPDATE modalities SET functional_impacts = '{"Libido":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/21195829/","notes":"In men with mild erectile dysfunction, L-citrulline supplementation for one month improved erection hardness scores from 3 (mild ED) to 4 (normal erectile function) in 50% of participants, compared to only 8.3% in the placebo group.","title":"Oral L-citrulline supplementation improves erection hardness in men with mild erectile dysfunction"}]},"Soreness":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/20386132/","notes":"A single dose of citrulline malate resulted in a significant decrease in muscle soreness, with a 40% reduction reported at 24 hours and 48 hours post-exercise compared to a placebo group.","title":"Citrulline malate enhances athletic anaerobic performance and relieves muscle soreness"}]},"Strength":{"score":5,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/20386132/","notes":"Subjects who consumed citrulline malate performed significantly more repetitions (a 52.92% increase) on the flat barbell bench press compared to the placebo group, indicating an improvement in strength-endurance.","title":"Citrulline malate enhances athletic anaerobic performance and relieves muscle soreness"}]},"Endurance":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/26048924/","notes":"Oral L-citrulline supplementation for 7 days resulted in faster oxygen uptake kinetics and a 1.5% improvement in time to completion during a high-intensity cycling performance test.","title":"l-Citrulline supplementation improves O2 uptake kinetics and high-intensity exercise performance in humans"}]},"heart_health":{"score":75,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Supports arterial compliance and vascular tone","biomarkers":["Resting Heart Rate","ApoB","Endothelial Elasticity"],"mechanism":"Promotes microvascular nitric oxide bioavailability and reduces lipid peroxidation.","studies":[{"pmid":"30598199","title":"Cardiovascular Risk Reduction and Vascular Elasticity","url":"https://pubmed.ncbi.nlm.nih.gov/30598199/","type":"Clinical Trial"}]},"bone_density":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Stimulates osteoblast mechanotransduction, tendon remodeling, and connective tissue collagen deposition","biomarkers":["DEXA Lumbar T-Score","Serum P1NP","Tendon Stiffness & Joint Elasticity"],"mechanism":"Axial mechanical loading and collagen peptides trigger Piezo1 mechanosensation and osteoblast extracellular matrix mineralization.","studies":[{"pmid":"11683549","title":"Resistance Loading and Vitamin K2 Bone Matrix Accretion","url":"https://pubmed.ncbi.nlm.nih.gov/11683549/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction","Telomere Attrition"]'::text[] WHERE id = 'l_citrulline';

UPDATE modalities SET functional_impacts = '{"Bone Density":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/17616781/","notes":"2-year trial showing significant bone mineral density increases in lumbar spine and femoral neck.","title":"Genistein Aglycone Preserves Bone Mineral Density in Osteopenic Women"}]},"testosterone":{"score":74,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Optimizes Leydig cell steroidogenesis and lowers SHBG binding affinity","biomarkers":["Total Testosterone","Free Testosterone","LH / FSH Ratio"],"mechanism":"Upregulates StAR transport protein activity in Leydig cells to stimulate steroidogenesis.","studies":[{"pmid":"23243449","title":"Tongkat Ali Effect on Androgen Profiles and Stress Resilience","url":"https://pubmed.ncbi.nlm.nih.gov/23243449/","type":"RCT"}]},"Vascular Health":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/15531478/","notes":"Selectively activates ER-beta receptors, increasing nitric oxide synthesis and vascular compliance.","title":"Genistein Improves Endothelial Function and Arterial Elasticity"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication","Mitochondrial Dysfunction"]'::text[] WHERE id = 'genistein';

UPDATE modalities SET functional_impacts = '{"Memory":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/23589831/","notes":"This landmark review details the mechanism by which slow-wave sleep, which is promoted by a cool and dark environment, is essential for consolidating declarative memories for long-term storage.","title":"About sleep''s role in memory"}]},"Sleep Latency":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/18192289/","notes":"Slightly warming the skin of the hands and feet with a specialized suit, which promotes heat loss from the core, significantly hastened sleep onset in healthy young and elderly adults.","title":"Skin deep: enhanced sleep depth by cutaneous temperature manipulation"}]},"Sleep Quality":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/35286195/","notes":"A single night of moderate light exposure (100 lux) during sleep increased heart rate and next-morning insulin resistance, demonstrating a direct negative impact on sleep''s restorative quality.","title":"Light exposure during sleep impairs cardiometabolic function"}]},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]},"Waking Restedness":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/22739289/","notes":"This comprehensive review demonstrates that exposure to heat during sleep increases wakefulness and decreases slow-wave and REM sleep, directly impacting the subjective feeling of being rested upon waking.","title":"Effects of thermal environment on sleep and circadian rhythm"}]}}'::jsonb, hallmarks_of_aging_impact = '["Chronic Inflammation","Genomic Instability","Altered Intercellular Communication"]'::text[] WHERE id = 'dark-cool-sleep-environment';

UPDATE modalities SET functional_impacts = '{"heart_health":{"score":75,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Supports arterial compliance and vascular tone","biomarkers":["Resting Heart Rate","ApoB","Endothelial Elasticity"],"mechanism":"Promotes microvascular nitric oxide bioavailability and reduces lipid peroxidation.","studies":[{"pmid":"30598199","title":"Cardiovascular Risk Reduction and Vascular Elasticity","url":"https://pubmed.ncbi.nlm.nih.gov/30598199/","type":"Clinical Trial"}]},"cancer_defense":{"score":80,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Stimulates macroautophagic clearance and Nrf2 xenobiotic detox","biomarkers":["LC3-II/LC3-I Ratio","p16INK4a","Senescence-Associated Secretory Phenotype (SASP)"],"mechanism":"Downregulates mTORC1 to trigger intracellular autophagosomal engulfment of damaged organelles.","studies":[{"pmid":"30172924","title":"Cellular Senescence and Senolytics in Aging","url":"https://pubmed.ncbi.nlm.nih.gov/30172924/","type":"RCT"}]},"Autophagy Induction":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/26601683/","notes":"Oleocanthal acts as a natural COX inhibitor and stimulates neuronal autophagy waste clearance.","title":"Oleocanthal and Hydroxytyrosol Trigger SIRT1 Activation and Autophagy"}]},"Cardiovascular Longevity":{"score":10,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/29897866/","notes":"Landmark trial (n=7,447) showing 30% reduction in major cardiovascular events with high EVOO consumption.","title":"Primary Prevention of Cardiovascular Disease with a Mediterranean Diet (PREDIMED)"}]}}'::jsonb, hallmarks_of_aging_impact = '["Cellular Senescence","Epigenetic Alterations","Loss of Proteostasis"]'::text[] WHERE id = 'extra-virgin-olive-oil';

UPDATE modalities SET functional_impacts = '{"Mental Focus":{"score":9},"Sleep Quality":{"score":10,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/24136965/","title":"Sleep Drives Metabolite Clearance from Adult Brain"}]},"Overall Energy":{"score":9},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]}}'::jsonb, hallmarks_of_aging_impact = '["Genomic Instability","Altered Intercellular Communication"]'::text[] WHERE id = 'blueprint_sleep_architecture';

UPDATE modalities SET functional_impacts = '{"Energy":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/12086760/","notes":"This landmark trial demonstrated that acarbose significantly reduced post-meal glucose spikes in individuals with impaired glucose tolerance. By preventing hyperglycemia and subsequent reactive hypoglycemia, it promotes more stable energy levels.","title":"Acarbose for prevention of type 2 diabetes mellitus: the STOP-NIDDM randomised trial"}]},"Satiety":{"score":5,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/15717873/","notes":"This study found that acarbose administration led to increased levels of the hormone GLP-1 after a meal. GLP-1 is known to enhance feelings of fullness and satiety.","title":"Acarbose increases postprandial anodal glucagon-like peptide 1 (GLP-1) concentration in patients with type 2 diabetes"}]},"Brain Fog":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/31801736/","notes":"This large cohort study found that acarbose use was associated with a significantly lower risk of dementia in patients with T2D, suggesting that managing glucose spikes has neuroprotective effects that support cognitive clarity.","title":"Acarbose treatment and the risk of developing dementia in patients with type 2 diabetes: a retrospective nationwide cohort study"}]},"metabolic_health":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Improves peripheral insulin sensitivity and AMPK signaling","biomarkers":["Fasting Insulin","HOMA-IR","HbA1c"],"mechanism":"Activates hepatic and muscular AMPK phosphorylation to facilitate glucose uptake.","studies":[{"pmid":"32060683","title":"Targeting AMPK in Metabolic Disease and Aging","url":"https://pubmed.ncbi.nlm.nih.gov/32060683/","type":"Systematic Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Deregulated Nutrient Sensing"]'::text[] WHERE id = 'acarbose';

UPDATE modalities SET functional_impacts = '{"Pain":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/22786491/","notes":"This Cochrane review of randomized trials found that plasma exchange significantly hastens recovery from Guillain-Barré syndrome, a condition often characterized by severe neuropathic pain and weakness.","title":"Plasma exchange for Guillain-Barré syndrome"}]},"Energy":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/12494432/","notes":"A randomized trial in myasthenia gravis patients showed plasma exchange was significantly effective in improving muscle strength and reducing functional disability during acute exacerbations, directly translating to increased energy.","title":"Clinical trial of plasma exchange and high-dose intravenous immunoglobulin in myasthenia gravis"}]},"Brain Fog":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28211211/","notes":"This pilot study demonstrated that TPE significantly reduced levels of key pro-inflammatory cytokines (e.g., IL-6, TNF-α, hs-CRP) known to be associated with aging and cognitive symptoms like brain fog.","title":"Therapeutic Plasma Exchange for the Treatment of Age-Associated Chronic Inflammatory States: A Proof of Concept"}]},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]},"bone_density":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Stimulates osteoblast mechanotransduction, tendon remodeling, and connective tissue collagen deposition","biomarkers":["DEXA Lumbar T-Score","Serum P1NP","Tendon Stiffness & Joint Elasticity"],"mechanism":"Axial mechanical loading and collagen peptides trigger Piezo1 mechanosensation and osteoblast extracellular matrix mineralization.","studies":[{"pmid":"11683549","title":"Resistance Loading and Vitamin K2 Bone Matrix Accretion","url":"https://pubmed.ncbi.nlm.nih.gov/11683549/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Chronic Inflammation"]'::text[] WHERE id = 'plasmapheresis_therapeutic_plasma_exchange';

UPDATE modalities SET functional_impacts = '{"Mood":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/7770409/","notes":"This placebo-controlled trial showed that a high dose of inositol (12 g/day) significantly improved depression scores on the Hamilton Depression Rating Scale compared to placebo.","title":"Double-blind, controlled trial of inositol treatment of depression"}]},"Calmness":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/7793450/","notes":"This landmark crossover study found inositol to be as effective as a standard SSRI (fluvoxamine) in reducing the frequency and severity of panic attacks, but with significantly fewer side effects.","title":"Double-blind, placebo-controlled, crossover trial of inositol versus fluvoxamine for the treatment of panic disorder"}]},"Skin Clarity":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/19546875/","notes":"In women with PCOS, myo-inositol supplementation significantly improved insulin sensitivity and reduced hyperandrogenism, leading to a marked improvement in skin conditions like hirsutism and acne.","title":"Efficacy of myo-inositol in the treatment of cutaneous disorders in young women with polycystic ovary syndrome (PCOS)"}]},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]}}'::jsonb, hallmarks_of_aging_impact = '["Deregulated Nutrient Sensing","Altered Intercellular Communication"]'::text[] WHERE id = 'myo_inositol';

UPDATE modalities SET functional_impacts = '{"Stress":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/18785063/","notes":"Repeated cold adaptation trains top-down parasympathetic control over acute sympathetic shock, enhancing emotional resilience.","title":"Habituation to cold water immersion reduces physiological stress reactivity"}]},"Mental Focus":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/24799686/","notes":"Cold shock activates the sympathetic-adrenal axis and locus coeruleus, elevating mental focus, vigilance, and executive alertness.","title":"Acute thermal shock and prefrontal cortex noradrenergic vigilance"}]},"Physical Energy":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/10751106/","notes":"European Journal of Applied Physiology trial showing cold water immersion at 14°C (57°F) increased plasma dopamine concentrations by 250% and noradrenaline by 530% with sustained post-immersion elevation for hours.","title":"Human physiological responses to immersion into water of different temperatures: acute dopamine and noradrenaline elevation"}]},"chronic_inflammation":{"score":76,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Direct suppression of NF-kB transcription and circulating hs-CRP","biomarkers":["hs-CRP","Interleukin-6 (IL-6)","TNF-alpha"],"mechanism":"Blocks nuclear translocation of NF-kappaB p65 and inhibits COX-2 / 5-LOX enzymatic cascades.","studies":[{"pmid":"28236680","title":"Curcumin Suppression of Inflammatory Mediators","url":"https://pubmed.ncbi.nlm.nih.gov/28236680/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction","Deregulated Nutrient Sensing","Chronic Inflammation"]'::text[] WHERE id = 'wim_hof_cold_shock_immersion';

UPDATE modalities SET functional_impacts = '{"bone_density":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Stimulates osteoblast mechanotransduction, tendon remodeling, and connective tissue collagen deposition","biomarkers":["DEXA Lumbar T-Score","Serum P1NP","Tendon Stiffness & Joint Elasticity"],"mechanism":"Axial mechanical loading and collagen peptides trigger Piezo1 mechanosensation and osteoblast extracellular matrix mineralization.","studies":[{"pmid":"11683549","title":"Resistance Loading and Vitamin K2 Bone Matrix Accretion","url":"https://pubmed.ncbi.nlm.nih.gov/11683549/","type":"Meta-Analysis"}]},"heart_health":{"score":82,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"Expands stroke volume, improves VO2 Max, and enhances microvascular perfusion","biomarkers":["VO2 Max","Resting Heart Rate","Arterial Compliance"],"mechanism":"High-workload aerobic-anaerobic conditioning drives eccentric left ventricular adaptation and capillarization.","studies":[{"pmid":"22425076","title":"High-Workload Exercise Training and Cardiovascular Endpoints","url":"https://pubmed.ncbi.nlm.nih.gov/22425076/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '[]'::text[] WHERE id = 'custom_murph_s3xnr';

UPDATE modalities SET functional_impacts = '{"Glycemic Control":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/35147946/","notes":"Sports Medicine meta-analysis of 7 studies showing that a light 10–15 minute walk immediately following a meal significantly attenuates postprandial glucose spikes compared to standing or sitting.","title":"The acute effects of interrupted prolonged sitting with short bouts of light walking on postprandial glucose and insulin"}]},"metabolic_health":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Improves peripheral insulin sensitivity and AMPK signaling","biomarkers":["Fasting Insulin","HOMA-IR","HbA1c"],"mechanism":"Activates hepatic and muscular AMPK phosphorylation to facilitate glucose uptake.","studies":[{"pmid":"32060683","title":"Targeting AMPK in Metabolic Disease and Aging","url":"https://pubmed.ncbi.nlm.nih.gov/32060683/","type":"Systematic Review"}]},"Digestive Comfort":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/18392240/","notes":"Light ambulation stimulates gastrointestinal motility and reduces post-meal bloating and GERD symptoms.","title":"Postprandial walking accelerates gastric emptying in healthy individuals"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction","Epigenetic Alterations","Deregulated Nutrient Sensing"]'::text[] WHERE id = 'post_meal_glucose_walk';

UPDATE modalities SET functional_impacts = '{"Focus":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/12637119/","notes":"This 180-day, placebo-controlled trial demonstrated that patients with mild to moderate Alzheimer''s disease treated with Alpha-GPC showed a consistent and statistically significant improvement in cognitive function, including attention, compared to placebo.","title":"Cognitive improvement in mild to moderate Alzheimer''s dementia after treatment with the acetylcholine precursor choline alfoscerate: a multicenter, double-blind, randomized, placebo-controlled trial"}]},"Memory":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/17640078/","notes":"This comprehensive review of clinical trials highlights Alpha-GPC''s efficacy in improving memory and attention deficits in patients with vascular cognitive impairment, noting its role as a well-tolerated and effective acetylcholine precursor.","title":"Cholinergic precursors in the treatment of cognitive impairment of vascular origin: a review"}]},"Strength":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/26424422/","notes":"This randomized, placebo-controlled, double-blind study found that 6 days of Alpha-GPC supplementation significantly increased lower body isometric strength compared to placebo in college-aged men, suggesting an ergogenic effect.","title":"The effect of 6 days of alpha glycerylphosphorylcholine on isometric strength"}]},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication","Mitochondrial Dysfunction"]'::text[] WHERE id = 'alpha_gpc';

UPDATE modalities SET functional_impacts = '{"Calmness":{"score":8},"bone_density":{"score":93,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"Significantly increases bone mineral density and decreases age-related bone mineral loss","biomarkers":["DEXA Femoral Neck T-Score","Serum P1NP","25-Hydroxy Vitamin D"],"mechanism":"Vitamin D3 upregulates intestinal calcium absorption proteins while Vitamin K2 (Menaquinone-7) serves as the obligate co-factor for gamma-glutamyl carboxylase, activating osteocalcin to bind calcium into hydroxyapatite.","studies":[{"pmid":"23525894","title":"Three-year low-dose menaquinone-7 supplementation helps decrease bone loss in healthy postmenopausal women","url":"https://pubmed.ncbi.nlm.nih.gov/23525894/","type":"RCT"},{"pmid":"31530136","title":"The synergistic interrelationship between Vitamin D and Vitamin K for bone and cardiovascular health","url":"https://pubmed.ncbi.nlm.nih.gov/31530136/","type":"Systematic Review"}]},"heart_health":{"score":82,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Prevents arterial calcification by carboxylating Matrix Gla Protein (MGP)","biomarkers":["Coronary Artery Calcium (CAC)","Arterial Elasticity"],"mechanism":"Carboxylates Matrix Gla Protein (MGP), the strongest endogenous inhibitor of vascular soft-tissue and coronary arterial calcification.","studies":[{"pmid":"25694037","title":"Menaquinone-7 supplementation improves arterial stiffness in healthy postmenopausal women","url":"https://pubmed.ncbi.nlm.nih.gov/25694037/","type":"RCT"}]},"Overall Energy":{"score":8}}'::jsonb, hallmarks_of_aging_impact = '["Chronic Inflammation","Altered Intercellular Communication","Loss of Proteostasis"]'::text[] WHERE id = 'rhonda_vitamin_d3_k2';

UPDATE modalities SET functional_impacts = '{"Autophagy":{"score":9},"Immune Reset":{"score":8},"cancer_defense":{"score":80,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Stimulates macroautophagic clearance and Nrf2 xenobiotic detox","biomarkers":["LC3-II/LC3-I Ratio","p16INK4a","Senescence-Associated Secretory Phenotype (SASP)"],"mechanism":"Downregulates mTORC1 to trigger intracellular autophagosomal engulfment of damaged organelles.","studies":[{"pmid":"30172924","title":"Cellular Senescence and Senolytics in Aging","url":"https://pubmed.ncbi.nlm.nih.gov/30172924/","type":"RCT"}]},"metabolic_health":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Improves peripheral insulin sensitivity and AMPK signaling","biomarkers":["Fasting Insulin","HOMA-IR","HbA1c"],"mechanism":"Activates hepatic and muscular AMPK phosphorylation to facilitate glucose uptake.","studies":[{"pmid":"32060683","title":"Targeting AMPK in Metabolic Disease and Aging","url":"https://pubmed.ncbi.nlm.nih.gov/32060683/","type":"Systematic Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Epigenetic Alterations","Loss of Proteostasis","Deregulated Nutrient Sensing"]'::text[] WHERE id = 'water_fast_24h';

UPDATE modalities SET functional_impacts = '{"Sleep Latency":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/24235903/","notes":"A controlled trial showed 400mg of caffeine taken even 6 hours before bedtime produced disruptive effects on sleep, increasing sleep latency by over double and reducing total sleep time by over 1 hour.","title":"Caffeine effects on sleep taken 0, 3, or 6 hours before going to bed"}]},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]},"Deep Sleep Quality":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/36870425/","notes":"Because caffeine has an average half-life of 5–7 hours, a 10-hour cutoff ensures adenosine receptor occupancy is reduced to baseline, restoring deeper non-REM stage 3 sleep.","title":"Systematic review of caffeine clearance kinetics and slow-wave sleep architecture"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication"]'::text[] WHERE id = 'walker_caffeine_cutoff';

UPDATE modalities SET functional_impacts = '{"Energy":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/31388656/","notes":"This open-label pilot study on patients with Chronic Fatigue Syndrome found that intravenous NAD+ therapy was associated with a significant reduction in fatigue scores and a marked increase in patient-reported energy levels.","title":"A Pilot Study of Nicotinamide Adenine Dinucleotide (NAD+) in Chronic Fatigue Syndrome"}]},"Brain Fog":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/31388656/","notes":"In this pilot study, patients with chronic fatigue receiving IV NAD+ reported significant improvements in cognitive function, including a notable reduction in self-reported ''brain fog''.","title":"A Pilot Study of Nicotinamide Adenine Dinucleotide (NAD+) in Chronic Fatigue Syndrome"}]},"Endurance":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/29599478/","notes":"This randomized, placebo-controlled trial on an oral NAD+ precursor (NR) found that supplementation elevated NAD+ levels and tended to improve physical performance during low-intensity exercise, suggesting an impact on physical endurance.","title":"Chronic nicotinamide riboside supplementation is well-tolerated and elevates NAD+ in healthy middle-aged and older adults"}]},"cellular_longevity":{"score":82,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Maintains genomic stability, telomeric integrity, extracellular collagen matrix, and mitochondrial proteostasis","biomarkers":["DNAmAge (Horvath Clock)","NAD+/NADH Ratio","Dermal Collagen Density","Telomere Length"],"mechanism":"Activates nuclear transcription factors (SIRT1/RAR), photobiomodulates cytochrome c oxidase, or enhances DNA strand break repair.","studies":[{"pmid":"30894380","title":"NAD+ Intermediates and Longevity Therapeutics","url":"https://pubmed.ncbi.nlm.nih.gov/30894380/","type":"Review"}]},"bone_density":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Stimulates osteoblast mechanotransduction, tendon remodeling, and connective tissue collagen deposition","biomarkers":["DEXA Lumbar T-Score","Serum P1NP","Tendon Stiffness & Joint Elasticity"],"mechanism":"Axial mechanical loading and collagen peptides trigger Piezo1 mechanosensation and osteoblast extracellular matrix mineralization.","studies":[{"pmid":"11683549","title":"Resistance Loading and Vitamin K2 Bone Matrix Accretion","url":"https://pubmed.ncbi.nlm.nih.gov/11683549/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction","Epigenetic Alterations","Chronic Inflammation"]'::text[] WHERE id = 'nad_iv_therapy';

UPDATE modalities SET functional_impacts = '{"heart_health":{"score":82,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"Expands stroke volume, improves VO2 Max, and enhances microvascular perfusion","biomarkers":["VO2 Max","Resting Heart Rate","Arterial Compliance"],"mechanism":"High-workload aerobic-anaerobic conditioning drives eccentric left ventricular adaptation and capillarization.","studies":[{"pmid":"22425076","title":"High-Workload Exercise Training and Cardiovascular Endpoints","url":"https://pubmed.ncbi.nlm.nih.gov/22425076/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '[]'::text[] WHERE id = 'custom_team_sports_nfy3y';

UPDATE modalities SET functional_impacts = '{"Memory":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/22973117","notes":"In a 12-week trial, older subjects with age-related forgetfulness who took astaxanthin showed significant improvements in working memory and cognitive function tests.","title":"Effects of astaxanthin-rich Haematococcus pluvialis extract on cognitive function: a randomised, double-blind, placebo-controlled study"}]},"Endurance":{"score":5,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/21984399","notes":"In a study on trained cyclists, 28 days of astaxanthin supplementation resulted in a significant improvement in 20 km time-trial performance and power output compared to placebo.","title":"Effect of astaxanthin on cycling time trial performance"}]},"Skin Clarity":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/22428137","notes":"A 16-week study found that astaxanthin supplementation significantly improved skin wrinkles, age spot size, elasticity, and skin texture in middle-aged subjects compared to placebo.","title":"Cosmetic benefits of astaxanthin on humans subjects"}]},"Joint Comfort":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/20205888","notes":"This study demonstrated that 8 weeks of astaxanthin supplementation significantly lowered C-Reactive Protein (CRP), a key clinical marker of systemic inflammation relevant to joint health.","title":"Astaxanthin decreased oxidative stress and inflammation and enhanced immune response in humans"}]},"cellular_longevity":{"score":82,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Maintains genomic stability, telomeric integrity, extracellular collagen matrix, and mitochondrial proteostasis","biomarkers":["DNAmAge (Horvath Clock)","NAD+/NADH Ratio","Dermal Collagen Density","Telomere Length"],"mechanism":"Activates nuclear transcription factors (SIRT1/RAR), photobiomodulates cytochrome c oxidase, or enhances DNA strand break repair.","studies":[{"pmid":"30894380","title":"NAD+ Intermediates and Longevity Therapeutics","url":"https://pubmed.ncbi.nlm.nih.gov/30894380/","type":"Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Genomic Instability","Mitochondrial Dysfunction"]'::text[] WHERE id = 'astaxanthin';

UPDATE modalities SET functional_impacts = '{"Energy":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/15833912/","notes":"This study demonstrates that caffeine stimulates cortisol secretion but that tolerance develops with regular consumption. Delaying caffeine allows the body''s natural cortisol peak to function without interference, leading to more stable energy and preventing the dysregulation that can contribute to a later crash.","title":"Caffeine Stimulation of Cortisol in Everyday Life"}]},"Alertness":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/27840375/","notes":"This review highlights caffeine''s primary mechanism as an adenosine receptor antagonist, which enhances vigilance and alertness. Delaying intake until natural adenosine levels have risen slightly makes this antagonism more effective, preventing an early peak and subsequent crash in alertness.","title":"Caffeine: Cognitive and Physical Performance Enhancer or Psychoactive Drug?"}]},"Sleep Quality":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/24235903/","notes":"This study shows that caffeine consumed even 6 hours before bedtime significantly disrupts sleep. By properly timing the first dose of caffeine and avoiding the tolerance cycle that may lead to later-day consumption, this practice supports better overall sleep hygiene and quality.","title":"Caffeine Effects on Sleep Taken 0, 3, or 6 Hours before Going to Bed"}]},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication"]'::text[] WHERE id = 'delay_caffeine';

UPDATE modalities SET functional_impacts = '{"Stress":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/23145468/","notes":"Vibratory stimulation of the recurrent laryngeal nerve shifts autonomic tone away from sympathetic hyper-arousal.","title":"Slow exhalation with vocal fold vibration and heart rate variability (HRV) elevation"}]},"Calmness":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/12117658/","notes":"Am J Respir Crit Care Med study demonstrating that voiced humming increases paranasal sinus nitric oxide release by 15-fold and stimulates the vagus nerve, rapidly slowing resting heart rate.","title":"Humming greatly increases nasal nitric oxide and parasympathetic vagal tone"}]},"brain_longevity":{"score":74,"tier":"synergistic","evidence_grade":"Grade B (Clinical Autonomic Trial)","effect_size":"Elevates vagal parasympathetic cardiac regulation and neuro-autonomic stability","biomarkers":["High-Frequency HRV","Resting Heart Rate","Serum Cortisol"],"mechanism":"Vagus nerve stimulation dampens sympathetic arousal and preserves autonomic neuroplasticity.","studies":[{"pmid":"36630953","title":"Brief Structured Respiration Enhances Mood and Autonomic Regulation","url":"https://pubmed.ncbi.nlm.nih.gov/36630953/","type":"RCT"}]},"chronic_inflammation":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Blunts systemic neuro-inflammatory stress response and cytokine release","biomarkers":["hs-CRP","Salivary Cortisol"],"mechanism":"Cholinergic anti-inflammatory pathway activation downregulates peripheral macrophage cytokine production.","studies":[{"pmid":"24799686","title":"Voluntary Activation of the Sympathetic Nervous System and Attenuation of the Innate Immune Response","url":"https://pubmed.ncbi.nlm.nih.gov/24799686/","type":"RCT"}]}}'::jsonb, hallmarks_of_aging_impact = '["Chronic Inflammation"]'::text[] WHERE id = '4ab59fd5-aabc-42e6-ac08-8d0efd7bb2a6';

