UPDATE modalities SET functional_impacts = '{"Skin Clarity":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/17951395/","title":"Protection against UV dermal oxidation by Nrf2 activation"}]},"Overall Energy":{"score":7},"Digestive Comfort":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28611480/","title":"Sulforaphane and Gut Microbiota Diversity"}]},"chronic_inflammation":{"score":76,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Direct suppression of NF-kB transcription and circulating hs-CRP","biomarkers":["hs-CRP","Interleukin-6 (IL-6)","TNF-alpha"],"mechanism":"Blocks nuclear translocation of NF-kappaB p65 and inhibits COX-2 / 5-LOX enzymatic cascades.","studies":[{"pmid":"28236680","title":"Curcumin Suppression of Inflammatory Mediators","url":"https://pubmed.ncbi.nlm.nih.gov/28236680/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Chronic Inflammation","Genomic Instability","Dysbiosis"]'::text[] WHERE id = 'blueprint_super_veggie';

UPDATE modalities SET functional_impacts = '{"Mood":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/10549478/","notes":"This landmark randomized controlled trial (the SMILE study) found that a 16-week program of aerobic exercise was as effective as antidepressant medication (sertraline) in reducing symptoms of major depression.","title":"Effects of exercise training on older patients with major depression"}]},"Energy":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28030422/","notes":"This foundational paper explains that Zone 2 intensity corresponds to the maximal rate of fat oxidation. Training in this zone improves mitochondrial function and metabolic flexibility, leading to more stable, sustainable energy production from fat stores.","title":"Assessment of Metabolic Flexibility by Means of Measuring Blood Lactate, Fat, and Carbohydrate Oxidation Responses to Exercise in Professional Endurance Athletes and Sedentary Individuals"}]},"Endurance":{"score":10,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/20448628/","notes":"This seminal review synthesizes evidence from elite athletes, concluding that a polarized approach, with approximately 80% of training performed at low intensity (i.e., Zone 2), is optimal for developing maximal endurance.","title":"What is Best Practice for Training Intensity and Duration Distribution in Endurance Athletes?"}]},"heart_health":{"score":95,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"+15–20% VO2 Max, 30% reduction in cardiovascular mortality risk","biomarkers":["VO2 Max","Resting HR","HRV","ApoB","Arterial Elasticity"],"mechanism":"Drives maximal stroke volume expansion, eccentric cardiac hypertrophy, microvascular capillarization, and mitochondrial volume density in slow-twitch type I fibers.","studies":[{"pmid":"23581781","title":"Effects of Exercise on Mitochondrial Content and Function in Aging Human Skeletal Muscle","url":"https://pubmed.ncbi.nlm.nih.gov/23581781/","type":"RCT"},{"pmid":"22425076","title":"Exercise training in heart failure: systematic review and meta-analysis","url":"https://pubmed.ncbi.nlm.nih.gov/22425076/","type":"Meta-Analysis"}]},"Sleep Quality":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28527231/","notes":"This systematic review of meta-analyses confirms that regular physical activity, particularly aerobic exercise like Zone 2 training, is associated with improved sleep quality, including reduced sleep latency and increased sleep duration.","title":"Exercise and sleep: a systematic review of previous meta-analyses"}]},"brain_longevity":{"score":82,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"+20% serum BDNF, preserved hippocampal volume","biomarkers":["Serum BDNF","Executive Processing Speed"],"mechanism":"Circulating muscle-derived myokine FNDC5/irisin crosses blood-brain barrier to trigger hippocampal BDNF transcription and neurogenesis.","studies":[{"pmid":"23995687","title":"Exercise induces hippocampal BDNF via a PGC-1alpha/FNDC5/irisin pathway","url":"https://pubmed.ncbi.nlm.nih.gov/23995687/","type":"Mechanistic / In Vivo"}]},"metabolic_health":{"score":90,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"35% increase in insulin sensitivity, enhanced fat oxidation clearance","biomarkers":["Fasting Insulin","HOMA-IR","HbA1c"],"mechanism":"Enhances cellular lipid droplet oxidation via CPT-1 upregulation while driving insulin-independent GLUT4 glucose uptake.","studies":[{"pmid":"29241717","title":"Zone 2 aerobic exercise training and insulin sensitivity in adults","url":"https://pubmed.ncbi.nlm.nih.gov/29241717/","type":"Clinical Trial"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction"]'::text[] WHERE id = 'zone_2_cardio';

