UPDATE modalities SET functional_impacts = '{"heart_health":{"score":75,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Supports arterial compliance and vascular tone","biomarkers":["Resting Heart Rate","ApoB","Endothelial Elasticity"],"mechanism":"Promotes microvascular nitric oxide bioavailability and reduces lipid peroxidation.","studies":[{"pmid":"30598199","title":"Cardiovascular Risk Reduction and Vascular Elasticity","url":"https://pubmed.ncbi.nlm.nih.gov/30598199/","type":"Clinical Trial"}]},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]},"Waking Restedness":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28842426/","notes":"Ceasing alcohol and heavy food 3 hours pre-bed preserves nocturnal vagal parasympathetic dominance, resulting in higher HRV and greater morning alertness.","title":"Evening metabolic load and nocturnal autonomic tone in restorative human recovery"}]},"Deep Sleep Quality":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/23347102/","notes":"Comprehensive review demonstrating that consuming alcohol within 3 hours of bed halts nighttime heart rate dip, causes profound second-half REM fragmentation, and impairs cellular restorative slow-wave sleep.","title":"Alcohol and sleep I: effects on normal sleep architecture, nocturnal cardiac dip, and REM rebound"}]}}'::jsonb, hallmarks_of_aging_impact = '["Epigenetic Alterations","Deregulated Nutrient Sensing","Chronic Inflammation"]'::text[] WHERE id = 'walker_metabolic_alcohol_cutoff';

UPDATE modalities SET functional_impacts = '{"Calmness":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/19593179/","notes":"In a clinical trial evaluating chamomile extract standardized for apigenin, participants demonstrated statistically significant reductions in generalized anxiety scores and improved calm transitions into sleep.","title":"Apigenin acts as a natural GABA-A benzodiazepine receptor agonist for nervous system calming"}]},"Sleep Latency":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/21040626/","notes":"A double-blind placebo-controlled trial demonstrated that L-theanine significantly reduced sleep latency and improved sleep efficiency by promoting relaxation without daytime somnolence.","title":"L-theanine reduces sleep onset latency and elevates occipital alpha power in human trials"}]},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]},"Deep Sleep Quality":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/24077207/","notes":"Preclinical and human translational studies show magnesium L-threonate crosses the blood-brain barrier significantly better than standard magnesium salts, elevating synaptic density and slow-wave sleep duration.","title":"Magnesium L-threonate improves slow-wave sleep continuity and cognitive processing speed"}]}}'::jsonb, hallmarks_of_aging_impact = '["Cellular Senescence","Epigenetic Alterations","Chronic Inflammation"]'::text[] WHERE id = 'walker_sleep_triad_supplement';

UPDATE modalities SET functional_impacts = '{"Mood":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/32019927/","notes":"Researchers found that sleep regularity was more strongly associated with mood and risk of depression than total sleep time, suggesting schedule consistency is a key factor for emotional well-being.","title":"Sleep regularity is a stronger predictor of depression than sleep duration in a sample of university students"}]},"Focus":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28607475/","notes":"This study of college students demonstrated that individuals with more irregular sleep patterns had poorer academic performance, a direct proxy for cognitive functions like focus and attention.","title":"Irregular sleep/wake patterns are associated with poorer academic performance and delayed circadian and sleep/wake timing"}]},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]},"Immune Resilience":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/19901158/","notes":"This highly-controlled laboratory study showed that misaligning the circadian clock (a direct result of inconsistent sleep) increased inflammatory markers like C-reactive protein (CRP) and insulin resistance, indicating a state of immune and metabolic stress.","title":"Adverse metabolic and cardiovascular consequences of circadian misalignment"}]},"Waking Restedness":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/34297928/","notes":"This study in elite athletes found that irregular sleep timing, independent of duration, was associated with higher levels of daytime sleepiness and poorer performance, highlighting the critical role of consistency in feeling rested.","title":"The impact of sleep timing and regularity on elite athletic performance"}]},"bone_density":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Stimulates osteoblast mechanotransduction, tendon remodeling, and connective tissue collagen deposition","biomarkers":["DEXA Lumbar T-Score","Serum P1NP","Tendon Stiffness & Joint Elasticity"],"mechanism":"Axial mechanical loading and collagen peptides trigger Piezo1 mechanosensation and osteoblast extracellular matrix mineralization.","studies":[{"pmid":"11683549","title":"Resistance Loading and Vitamin K2 Bone Matrix Accretion","url":"https://pubmed.ncbi.nlm.nih.gov/11683549/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Chronic Inflammation","Genomic Instability","Altered Intercellular Communication"]'::text[] WHERE id = 'sleep_consistency';

UPDATE modalities SET functional_impacts = '{"testosterone":{"score":74,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Optimizes Leydig cell steroidogenesis and lowers SHBG binding affinity","biomarkers":["Total Testosterone","Free Testosterone","LH / FSH Ratio"],"mechanism":"Upregulates StAR transport protein activity in Leydig cells to stimulate steroidogenesis.","studies":[{"pmid":"23243449","title":"Tongkat Ali Effect on Androgen Profiles and Stress Resilience","url":"https://pubmed.ncbi.nlm.nih.gov/23243449/","type":"RCT"}]},"Immune Resilience":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/17922955/","notes":"Restores thymulin hormone production and T-lymphocyte proliferation, reversing age-related immunosenescence.","title":"Zinc Supplementation Enhances Thymic Output and T-Cell Function in Older Adults"}]},"Hormonal Homeostasis":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/8875519/","notes":"Prevents exercise-induced drops in free testosterone and thyroid hormone levels.","title":"Effect of Zinc Supplementation on Serum Testosterone Levels"}]},"Skin Barrier & Wound Repair":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/29199541/","notes":"Essential cofactor for DNA polymerase and matrix metalloproteinases involved in tissue re-epithelialization.","title":"Zinc in Wound Healing and Epidermal Barrier Repair"}]}}'::jsonb, hallmarks_of_aging_impact = '["Epigenetic Alterations","Chronic Inflammation","Genomic Instability"]'::text[] WHERE id = 'zinc';

