UPDATE modalities SET functional_impacts = '{"Endurance":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/20861526/","notes":"Progressive distance runs build glycogen storage capacity, connective tissue fatigue tolerance, and left ventricular stroke volume.","title":"Training characteristics and distribution of training volume in endurance athletes"}]},"heart_health":{"score":75,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Supports arterial compliance and vascular tone","biomarkers":["Resting Heart Rate","ApoB","Endothelial Elasticity"],"mechanism":"Promotes microvascular nitric oxide bioavailability and reduces lipid peroxidation.","studies":[{"pmid":"30598199","title":"Cardiovascular Risk Reduction and Vascular Elasticity","url":"https://pubmed.ncbi.nlm.nih.gov/30598199/","type":"Clinical Trial"}]},"Muscular Strength":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28842426/","notes":"Progressive loading enhances Achilles tendon stiffness and elastic recoil efficiency.","title":"Tendon stiffness and energy return adaptations in long-distance running"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction"]'::text[] WHERE id = 'hm_progressive_longrun';

UPDATE modalities SET functional_impacts = '{"Endurance":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/36482098/","notes":"Landmark Nature Medicine prospective study of 25,241 non-exercisers showing that just 3–4 bouts of 1-minute vigorous activity daily lowered all-cause and cancer mortality by 38–40% and cardiovascular mortality by 48–49%.","title":"Association of wearable device-measured vigorous intermittent lifestyle physical activity (VILPA) with mortality"}]},"heart_health":{"score":75,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Supports arterial compliance and vascular tone","biomarkers":["Resting Heart Rate","ApoB","Endothelial Elasticity"],"mechanism":"Promotes microvascular nitric oxide bioavailability and reduces lipid peroxidation.","studies":[{"pmid":"30598199","title":"Cardiovascular Risk Reduction and Vascular Elasticity","url":"https://pubmed.ncbi.nlm.nih.gov/30598199/","type":"Clinical Trial"}]},"Physical Energy":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/34185794/","notes":"Short 60-second micro-bursts of stairs or sprint activity restore microvascular perfusion and clear cellular fatigue.","title":"Brief exercise snacks and cellular energetic reactivation throughout sedentary workdays"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction","Chronic Inflammation"]'::text[] WHERE id = 'vilpa_micro_bursts';

UPDATE modalities SET functional_impacts = '{"Mood":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/24026850/","notes":"This Cochrane meta-analysis of 35 trials concluded that exercise, including running, is a moderately effective treatment for depression compared to no therapy, with an effect size comparable to psychological or pharmacological therapies.","title":"Exercise for depression"}]},"Energy":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/18277063/","notes":"This RCT demonstrated that a 6-week low-intensity aerobic exercise program (including treadmill walking/jogging) significantly increased feelings of energy by 20% and decreased fatigue by 65% compared to a control group.","title":"A randomized controlled trial of the effect of aerobic exercise training on feelings of energy and fatigue in sedentary young adults with persistent fatigue"}]},"Stress":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/24847355/","notes":"This study found that individuals who engaged in regular physical activity showed blunted emotional responses (e.g., bad mood, stress) to an acute psychosocial stressor, indicating enhanced emotional resilience.","title":"Regular exercise is associated with emotional resilience to acute stress in healthy adults"}]},"Endurance":{"score":10,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/26242524/","notes":"This meta-analysis of 36 studies found that both continuous endurance running and HIIT robustly improve VO2max, the gold-standard measure of cardiorespiratory fitness and endurance capacity.","title":"Effectiveness of High-Intensity Interval Training (HIIT) and Continuous Endurance Training for VO2max Improvements: A Systematic Review and Meta-Analysis of Controlled Trials"}]},"bone_density":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Stimulates osteoblast mechanotransduction, tendon remodeling, and connective tissue collagen deposition","biomarkers":["DEXA Lumbar T-Score","Serum P1NP","Tendon Stiffness & Joint Elasticity"],"mechanism":"Axial mechanical loading and collagen peptides trigger Piezo1 mechanosensation and osteoblast extracellular matrix mineralization.","studies":[{"pmid":"11683549","title":"Resistance Loading and Vitamin K2 Bone Matrix Accretion","url":"https://pubmed.ncbi.nlm.nih.gov/11683549/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction","Epigenetic Alterations"]'::text[] WHERE id = 'running';

UPDATE modalities SET functional_impacts = '{"Calmness":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/25705824/","notes":"This landmark prospective study of 2,315 men over 20 years found that frequent sauna use was associated with a significantly lower risk of sudden cardiac death, fatal coronary heart disease, and all-cause mortality, underscoring its profound, long-term stress-reducing and cardioprotective effects.","title":"Association between sauna bathing and fatal cardiovascular and all-cause mortality events"}]},"Soreness":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/26180741/","notes":"This study demonstrated that far-infrared sauna use improves recovery from maximal endurance and strength training sessions, suggesting a significant reduction in neuromuscular fatigue and soreness.","title":"Effects of far-infrared sauna bathing on recovery from strength and endurance training sessions in men"}]},"Endurance":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/16877041/","notes":"In this study, male distance runners who used a sauna for 30 minutes after training sessions for 3 weeks showed a 32% increase in run time to exhaustion, primarily due to a 7.1% increase in plasma volume.","title":"Effect of post-exercise sauna bathing on the endurance performance of competitive male runners"}]},"heart_health":{"score":90,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"50% reduction in fatal cardiovascular disease (4-7x weekly cohort)","biomarkers":["Resting HR","Arterial Elasticity","Blood Pressure"],"mechanism":"Elevates core temperature to 39°C, inducing profound peripheral vasodilation, cardiac output increase of 60-70%, and upregulation of endothelial nitric oxide (eNOS).","studies":[{"pmid":"25705824","title":"Association Between Sauna Bathing and Fatal Cardiovascular and All-Cause Mortality Events (KIHD Study)","url":"https://pubmed.ncbi.nlm.nih.gov/25705824/","type":"Clinical Trial"},{"pmid":"30077204","title":"Cardiovascular and Other Health Benefits of Sauna Bathing: A Review of the Evidence","url":"https://pubmed.ncbi.nlm.nih.gov/30077204/","type":"Systematic Review"}]},"Sleep Quality":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/29267154/","notes":"While investigating cardiovascular outcomes, this large prospective study noted that regular sauna bathing was associated with various positive lifestyle factors, and other research it references suggests the body temperature drop post-sauna can promote deeper, more restful sleep.","title":"Sauna bathing is associated with reduced cardiovascular mortality and improves risk prediction in men and women: a prospective cohort study"}]},"brain_longevity":{"score":78,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"65% reduced risk of Alzheimer’s and dementia in 4–7 sessions/week","biomarkers":["BDNF","Glymphatic Sleep Metrics"],"mechanism":"Hyperthermia increases cerebral blood flow and triggers robust dynorphin release followed by endorphin/BDNF upregulation.","studies":[{"pmid":"27932366","title":"Sauna bathing is inversely associated with dementia and Alzheimer’s disease in middle-aged Finnish men","url":"https://pubmed.ncbi.nlm.nih.gov/27932366/","type":"Clinical Trial"}]},"chronic_inflammation":{"score":85,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"Significant reduction in hs-CRP and systemic leukocyte adhesion","biomarkers":["hs-CRP","IL-6"],"mechanism":"Acute hyperthermia triggers Heat Shock Proteins (HSP70, HSP90) which refold denatured proteins and inhibit NF-kB inflammatory cascades.","studies":[{"pmid":"29209503","title":"Sauna bathing reduces systemic C-reactive protein levels in a prospective study","url":"https://pubmed.ncbi.nlm.nih.gov/29209503/","type":"Clinical Trial"}]}}'::jsonb, hallmarks_of_aging_impact = '["Loss of Proteostasis"]'::text[] WHERE id = 'sauna_exposure';

UPDATE modalities SET functional_impacts = '{"Focus":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/24723293/","notes":"Using head-down tilt as a model for inversion, this study found that while subjects felt subjective changes, objective cognitive performance was well-maintained, indicating robust cerebral autoregulation that supports brain function during postural shifts.","title":"Cognitive performance is maintained during 72 h 6° head-down tilt"}]},"Calmness":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/22365651/","notes":"This review discusses how yoga practices, including inversions, can modulate the autonomic nervous system by increasing parasympathetic tone (the ''rest and digest'' system), thereby reducing stress and promoting a state of calm.","title":"The Effect of Yoga on the Autonomic Nervous System, Gamma-aminobutyric-acid, and Allostasis in Epilepsy, Depression, and Post-traumatic Stress Disorder"}]},"Strength":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28848721/","notes":"An 8-week calisthenics program, which heavily utilizes bodyweight movements like handstands, resulted in significant improvements in upper body strength (push-ups) and a reduction in body fat.","title":"The effects of a calisthenics training intervention on posture, strength and body composition"}]},"Joint Comfort":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/26618141/","notes":"This study demonstrated that closed-chain exercises like handstands significantly improve shoulder muscle strength and stability, which can contribute to long-term joint health and comfort.","title":"Closed kinetic chain upper extremity training in sedentary individuals: effects on shoulder strength and functional performance"}]},"bone_density":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Stimulates osteoblast mechanotransduction, tendon remodeling, and connective tissue collagen deposition","biomarkers":["DEXA Lumbar T-Score","Serum P1NP","Tendon Stiffness & Joint Elasticity"],"mechanism":"Axial mechanical loading and collagen peptides trigger Piezo1 mechanosensation and osteoblast extracellular matrix mineralization.","studies":[{"pmid":"11683549","title":"Resistance Loading and Vitamin K2 Bone Matrix Accretion","url":"https://pubmed.ncbi.nlm.nih.gov/11683549/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Epigenetic Alterations"]'::text[] WHERE id = 'handstand';

UPDATE modalities SET functional_impacts = '{"Mood":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28842426/","notes":"Natural UV and infrared exposure stimulates epidermal neuroendocrine signaling and elevates circulating endorphin levels.","title":"Photobiomodulation and cutaneous beta-endorphin release in response to natural sunlight"}]},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]},"Deep Sleep Quality":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/15585788/","notes":"Bright midday solar exposure provides 10,000+ lux of full-spectrum photons to intrinsically photosensitive retinal ganglion cells (ipRGCs), strongly pinning the suprachiasmatic nucleus (SCN) circadian phase for deeper nocturnal sleep.","title":"Sunlight exposure, circadian melatonin rhythm entrainment, and slow-wave sleep architecture"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction","Genomic Instability","Altered Intercellular Communication"]'::text[] WHERE id = 'f0dba777-57ed-4070-8c2e-038e40a0cf6a';

UPDATE modalities SET functional_impacts = '{"Mood":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/29800984/","notes":"A meta-analysis of 33 randomized clinical trials demonstrating that resistance exercise training was associated with a significant reduction in depressive symptoms among adults.","title":"Association of Efficacy of Resistance Exercise Training With Depressive Symptoms: Meta-analysis and Meta-regression Analysis of Randomized Clinical Trials"}]},"Energy":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/17073524/","notes":"A meta-analysis showing that chronic exercise interventions, including resistance training, result in a significant improvement in feelings of energy and a reduction in fatigue across numerous populations.","title":"Effects of chronic exercise on feelings of energy and fatigue: a quantitative synthesis"}]},"Strength":{"score":10,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/15142003/","notes":"Meta-analysis of 140 studies showing a clear dose-response relationship, with greater training intensity and volume leading to maximal strength gains.","title":"Maximizing strength development in athletes: a meta-analysis to determine the dose-response relationship"}]},"testosterone":{"score":74,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Optimizes Leydig cell steroidogenesis and lowers SHBG binding affinity","biomarkers":["Total Testosterone","Free Testosterone","LH / FSH Ratio"],"mechanism":"Upregulates StAR transport protein activity in Leydig cells to stimulate steroidogenesis.","studies":[{"pmid":"23243449","title":"Tongkat Ali Effect on Androgen Profiles and Stress Resilience","url":"https://pubmed.ncbi.nlm.nih.gov/23243449/","type":"RCT"}]},"Joint Comfort":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/24574223/","notes":"A systematic review and meta-regression analysis of 114 trials finding that exercise programs, particularly those focused on strengthening, significantly reduce pain and disability in patients with knee osteoarthritis.","title":"Impact of exercise type and dose on pain and disability in knee osteoarthritis: a systematic review and meta-regression analysis of randomized controlled trials"}]}}'::jsonb, hallmarks_of_aging_impact = '["Deregulated Nutrient Sensing","Telomere Attrition","Dysbiosis"]'::text[] WHERE id = 'strength-training';

UPDATE modalities SET functional_impacts = '{"Autophagy":{"score":10},"HGH Elevation":{"score":10},"cancer_defense":{"score":98,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"Profound induction of systemic macroautophagy and hematopoietic stem cell regeneration","biomarkers":["p16INK4a Expression","Plasma Free IGF-1","Natural Killer Cell Activity"],"mechanism":"Suppresses mTORC1 below basal thresholds while depleting intrahepatic glycogen, activating AMPK, downregulating circulating IGF-1 by >40%, and inducing p53-dependent autophagic clearance.","studies":[{"pmid":"24905167","title":"Prolonged Fasting Reduces IGF-1/PKA to Promote Hematopoietic-Stem-Cell-Based Regeneration and Reverse Immunosuppression","url":"https://pubmed.ncbi.nlm.nih.gov/24905167/","type":"RCT"},{"pmid":"31881139","title":"Effects of Intermittent and Prolonged Fasting on Health, Aging, and Disease","url":"https://pubmed.ncbi.nlm.nih.gov/31881139/","type":"Systematic Review"}]},"metabolic_health":{"score":96,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"Normalizes fasting insulin, achieves deep ketosis (beta-hydroxybutyrate > 2.5 mmol/L)","biomarkers":["Fasting Insulin","HOMA-IR","HbA1c"],"mechanism":"Depletes hepatic fat stores and induces visceral lipolysis while shifting cellular respiration to beta-hydroxybutyrate.","studies":[{"pmid":"32485183","title":"Safety and Metabolic Effects of 48-Hour Water Fasting in Humans","url":"https://pubmed.ncbi.nlm.nih.gov/32485183/","type":"Clinical Trial"}]},"Mitochondrial Health":{"score":9}}'::jsonb, hallmarks_of_aging_impact = '["Disabled Macroautophagy","Stem Cell Exhaustion","Cellular Senescence"]'::text[] WHERE id = 'extended_fast_48h';

UPDATE modalities SET functional_impacts = '{"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]},"Systemic Recovery":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/17099008/","notes":"Nighttime administration accelerates cellular recovery, tissue remodeling, and waking vigor.","title":"Pulsatile GHRH signaling in skeletal muscle repair and nocturnal cellular regeneration"}]},"Deep Sleep Quality":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/16352683/","notes":"J Clin Endocrinol Metab study proving CJC-1295 acts synergistically with ghrelin secretagogues to amplify pulsatile endogenous GH release, restoring youthful stage 4 slow-wave deep sleep.","title":"Prolonged stimulation of growth hormone and IGF-I secretion by GHRH analog CJC-1295"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication"]'::text[] WHERE id = 'cjc1295_no_dac_subq';

UPDATE modalities SET functional_impacts = '{"hrv":{"score":10,"rationale":"0.1 Hz baroreflex frequency produces maximum HRV amplitude."},"emotional_balance":{"score":8,"rationale":"Fosters hemispheric and autonomic coherence."},"stress_resilience":{"score":9,"rationale":"Entrains cardiovascular and respiratory sinus arrhythmia."},"brain_longevity":{"score":74,"tier":"synergistic","evidence_grade":"Grade B (Clinical Autonomic Trial)","effect_size":"Elevates vagal parasympathetic cardiac regulation and neuro-autonomic stability","biomarkers":["High-Frequency HRV","Resting Heart Rate","Serum Cortisol"],"mechanism":"Vagus nerve stimulation dampens sympathetic arousal and preserves autonomic neuroplasticity.","studies":[{"pmid":"36630953","title":"Brief Structured Respiration Enhances Mood and Autonomic Regulation","url":"https://pubmed.ncbi.nlm.nih.gov/36630953/","type":"RCT"}]},"chronic_inflammation":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Blunts systemic neuro-inflammatory stress response and cytokine release","biomarkers":["hs-CRP","Salivary Cortisol"],"mechanism":"Cholinergic anti-inflammatory pathway activation downregulates peripheral macrophage cytokine production.","studies":[{"pmid":"24799686","title":"Voluntary Activation of the Sympathetic Nervous System and Attenuation of the Innate Immune Response","url":"https://pubmed.ncbi.nlm.nih.gov/24799686/","type":"RCT"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication","Mitochondrial Dysfunction"]'::text[] WHERE id = 'coherent_breathing';

UPDATE modalities SET functional_impacts = '{"Fat Loss":{"score":9},"Autophagy":{"score":8},"HGH Elevation":{"score":8},"cancer_defense":{"score":80,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Stimulates macroautophagic clearance and Nrf2 xenobiotic detox","biomarkers":["LC3-II/LC3-I Ratio","p16INK4a","Senescence-Associated Secretory Phenotype (SASP)"],"mechanism":"Downregulates mTORC1 to trigger intracellular autophagosomal engulfment of damaged organelles.","studies":[{"pmid":"30172924","title":"Cellular Senescence and Senolytics in Aging","url":"https://pubmed.ncbi.nlm.nih.gov/30172924/","type":"RCT"}]},"metabolic_health":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Improves peripheral insulin sensitivity and AMPK signaling","biomarkers":["Fasting Insulin","HOMA-IR","HbA1c"],"mechanism":"Activates hepatic and muscular AMPK phosphorylation to facilitate glucose uptake.","studies":[{"pmid":"32060683","title":"Targeting AMPK in Metabolic Disease and Aging","url":"https://pubmed.ncbi.nlm.nih.gov/32060683/","type":"Systematic Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Deregulated Nutrient Sensing"]'::text[] WHERE id = 'intermittent_fasting_20_4';

UPDATE modalities SET functional_impacts = '{"Energy":{"score":5,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/18544902","notes":"In an elderly population, supplementation with carnosine''s precursor was shown to significantly delay the onset of neuromuscular fatigue, which is perceived as an increase in energy and capacity for physical work.","title":"The effect of beta-alanine supplementation on neuromuscular fatigue in elderly (55-92 Years): a double-blind randomized study"}]},"Memory":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/12543990","notes":"This randomized controlled trial demonstrated that L-carnosine supplementation produced statistically significant improvements in behavior, socialization, and communication, highlighting its impact on neurological and cognitive functions.","title":"Double-blind, placebo-controlled study of L-carnosine supplementation in children with autistic spectrum disorders"}]},"Endurance":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/22270875","notes":"This meta-analysis of 15 studies found that supplementation with beta-alanine (the precursor to carnosine) significantly improves high-intensity exercise performance and capacity by increasing muscle carnosine concentrations.","title":"Effects of β-alanine supplementation on exercise performance: a meta-analysis"}]},"cellular_longevity":{"score":82,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Maintains genomic stability, telomeric integrity, extracellular collagen matrix, and mitochondrial proteostasis","biomarkers":["DNAmAge (Horvath Clock)","NAD+/NADH Ratio","Dermal Collagen Density","Telomere Length"],"mechanism":"Activates nuclear transcription factors (SIRT1/RAR), photobiomodulates cytochrome c oxidase, or enhances DNA strand break repair.","studies":[{"pmid":"30894380","title":"NAD+ Intermediates and Longevity Therapeutics","url":"https://pubmed.ncbi.nlm.nih.gov/30894380/","type":"Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Telomere Attrition"]'::text[] WHERE id = 'l_carnosine';

UPDATE modalities SET functional_impacts = '{"Focus":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/26424423/","notes":"This comprehensive review concluded that tyrosine supplementation can effectively enhance cognitive functions, particularly working memory and cognitive flexibility, in situations involving high cognitive demand or acute stressors.","title":"Effect of tyrosine supplementation on clinical and healthy populations under stress or cognitive demands--A review"}]},"Memory":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/7794222/","notes":"In subjects undergoing over 24 hours of continuous work and sleep deprivation, tyrosine supplementation significantly counteracted the typical decline in performance on tasks assessing working memory and vigilance.","title":"The effects of tyrosine on cognitive performance during extended wakefulness"}]},"Stress":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/2736402/","notes":"This foundational study on military personnel demonstrated that L-tyrosine administration significantly reduced adverse mood, symptoms, and performance decrements during a demanding combat training course involving cold and altitude stress.","title":"Treatment with tyrosine, a neurotransmitter precursor, reduces environmental stress in humans"}]},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication","Mitochondrial Dysfunction"]'::text[] WHERE id = 'l_tyrosine';

UPDATE modalities SET functional_impacts = '{"Skin Quality":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/18644225/","notes":"Comprehensive review establishing that GHK-Cu upregulates collagen, elastin, and decorin synthesis, accelerating dermal wound contraction and reducing wrinkles and UV-damaged skin pigmentation.","title":"The human tripeptide GHK and tissue remodeling: gene expression modulation in skin and collagen synthesis"}]},"Joint Comfort":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/26082814/","notes":"GHK-Cu resets gene expression of 4,000+ human genes, suppressing TGF-beta-mediated fibrosis and protecting joint cartilage integrity.","title":"GHK-Cu peptide downregulates pro-inflammatory cytokines and promotes chondrocyte extracellular matrix production"}]},"cellular_longevity":{"score":82,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Maintains genomic stability, telomeric integrity, extracellular collagen matrix, and mitochondrial proteostasis","biomarkers":["DNAmAge (Horvath Clock)","NAD+/NADH Ratio","Dermal Collagen Density","Telomere Length"],"mechanism":"Activates nuclear transcription factors (SIRT1/RAR), photobiomodulates cytochrome c oxidase, or enhances DNA strand break repair.","studies":[{"pmid":"30894380","title":"NAD+ Intermediates and Longevity Therapeutics","url":"https://pubmed.ncbi.nlm.nih.gov/30894380/","type":"Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication","Mitochondrial Dysfunction"]'::text[] WHERE id = 'ghk_cu_subq';

