UPDATE modalities SET functional_impacts = '{"Brain Fog":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/19448002/","notes":"Sustains neurodevelopment and prevents lethargy caused by subclinical thyroid slowing.","title":"Iodine Supplementation Improves Cognition in Mildly Iodine-Deficient Children"}]},"Metabolic Energy":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/24788260/","notes":"Direct substrate for thyroid peroxidase organification into active T3/T4, sustaining basal metabolic rate.","title":"Iodine Nutrition and Thyroid Hormone Synthesis Dynamics"}]},"metabolic_health":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Improves peripheral insulin sensitivity and AMPK signaling","biomarkers":["Fasting Insulin","HOMA-IR","HbA1c"],"mechanism":"Activates hepatic and muscular AMPK phosphorylation to facilitate glucose uptake.","studies":[{"pmid":"32060683","title":"Targeting AMPK in Metabolic Disease and Aging","url":"https://pubmed.ncbi.nlm.nih.gov/32060683/","type":"Systematic Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication"]'::text[] WHERE id = 'iodine';

UPDATE modalities SET functional_impacts = '{"Calmness":{"score":5,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/15041014","notes":"While this is an animal study, it demonstrates that taurine produces anxiolytic effects by interacting with the GABAA receptor, supporting its mechanistic role in promoting calmness. Human trials are less definitive but point to similar neurological benefits.","title":"The anxiolytic-like effects of taurine in mice"}]},"Soreness":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/25899517","notes":"Supplementing with 2g of taurine three times a day for two weeks before and three days after intense eccentric exercise significantly reduced markers of muscle damage and delayed onset muscle soreness (DOMS).","title":"Taurine supplementation reduces eccentric exercise-induced delayed onset muscle soreness in young men"}]},"Endurance":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/29546641","notes":"This meta-analysis of 10 randomized controlled trials found that taurine supplementation, with doses ranging from 1 to 6 grams per day, significantly improves human endurance performance across multiple exercise modalities.","title":"The Effects of an Oral Taurine Dose and Supplementation Period on Endurance Exercise Performance in Humans: A Meta-Analysis"}]},"cellular_longevity":{"score":82,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Maintains genomic stability, telomeric integrity, extracellular collagen matrix, and mitochondrial proteostasis","biomarkers":["DNAmAge (Horvath Clock)","NAD+/NADH Ratio","Dermal Collagen Density","Telomere Length"],"mechanism":"Activates nuclear transcription factors (SIRT1/RAR), photobiomodulates cytochrome c oxidase, or enhances DNA strand break repair.","studies":[{"pmid":"30894380","title":"NAD+ Intermediates and Longevity Therapeutics","url":"https://pubmed.ncbi.nlm.nih.gov/30894380/","type":"Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction","Epigenetic Alterations","Chronic Inflammation"]'::text[] WHERE id = 'taurine';

UPDATE modalities SET functional_impacts = '{"Energy":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/11832527/","notes":"The landmark Diabetes Prevention Program (DPP) trial showed metformin improved glycemic control, the foundation for stable energy levels, reducing the progression to diabetes by 31% in high-risk individuals.","title":"Reduction in the incidence of type 2 diabetes with lifestyle intervention or metformin"}]},"Satiety":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28953886/","notes":"This seminal study identified the hormone GDF15 as a primary mechanism through which metformin induces appetite suppression and modest weight loss in users.","title":"GDF15 is an appetite-suppressant hormone that mediates the anorectic and glucose-lowering effects of metformin"}]},"Brain Fog":{"score":5,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/33946221/","notes":"This trial demonstrated that metformin treatment improved cognitive scores, particularly executive function, in older adults with prediabetes, linking better glucose control to enhanced mental clarity.","title":"Metformin improves cognition and health-related quality of life in elderly patients with prediabetes and cognitive impairment: a randomized controlled trial"}]},"metabolic_health":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Improves peripheral insulin sensitivity and AMPK signaling","biomarkers":["Fasting Insulin","HOMA-IR","HbA1c"],"mechanism":"Activates hepatic and muscular AMPK phosphorylation to facilitate glucose uptake.","studies":[{"pmid":"32060683","title":"Targeting AMPK in Metabolic Disease and Aging","url":"https://pubmed.ncbi.nlm.nih.gov/32060683/","type":"Systematic Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Deregulated Nutrient Sensing","Mitochondrial Dysfunction"]'::text[] WHERE id = 'metformin_daily';

