UPDATE modalities SET functional_impacts = '{"Energy":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/36728795/","notes":"This RCT showed a significant reduction in perceived fatigue during exercise protocols in men supplementing with AKG for 4 weeks, directly correlating to improved energy availability.","title":"Effects of 4-Week Alpha-Ketoglutarate Supplementation on Markers of Physical Performance, Body Composition and Hormonal Profile in Resistance-Trained Males: A Randomized, Double-Blind, Placebo-Controlled Trial"}]},"Endurance":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/36728795/","notes":"An RCT in resistance-trained men found that 4 weeks of AKG supplementation improved exercise performance (1-RM strength) and significantly reduced perceived fatigue.","title":"Effects of 4-Week Alpha-Ketoglutarate Supplementation on Markers of Physical Performance, Body Composition and Hormonal Profile in Resistance-Trained Males: A Randomized, Double-Blind, Placebo-Controlled Trial"}]},"Joint Comfort":{"score":5,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/36811904/","notes":"This open-label human study reported statistically significant improvements in self-reported joint-related pain, aches, and stiffness after 4-10 months of supplementation with a Ca-AKG formulation.","title":"Calcium alpha-ketoglutarate, a modulator of aging, may help with joint problems"}]},"Immune Resilience":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/34969241/","notes":"In this human observational study, supplementation with an AKG-based formula was associated with a reduction in inflammatory cytokines like IL-6, suggesting a beneficial modulation of the immune system.","title":"Rejuvant®, a potential life-extending compound formulation with alpha-ketoglutarate and vitamins, conferred an average 8 year reduction in biological age after an average of 7 months of use"}]},"cellular_longevity":{"score":82,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Maintains genomic stability, telomeric integrity, extracellular collagen matrix, and mitochondrial proteostasis","biomarkers":["DNAmAge (Horvath Clock)","NAD+/NADH Ratio","Dermal Collagen Density","Telomere Length"],"mechanism":"Activates nuclear transcription factors (SIRT1/RAR), photobiomodulates cytochrome c oxidase, or enhances DNA strand break repair.","studies":[{"pmid":"30894380","title":"NAD+ Intermediates and Longevity Therapeutics","url":"https://pubmed.ncbi.nlm.nih.gov/30894380/","type":"Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Epigenetic Alterations","Stem Cell Exhaustion"]'::text[] WHERE id = 'alpha_ketoglutarate_akg';

