UPDATE modalities SET functional_impacts = '{"Stress":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/17182482/","notes":"This study demonstrated that GABA intake attenuated the decrease in salivary stress markers (chromogranin A and cortisol) during a psychological stress task, indicating a stress-reducing effect.","title":"Relaxation and immunity enhancement effects of Gamma-Aminobutyric acid (GABA) administration in humans"}]},"Calmness":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/17182482/","notes":"Oral GABA administration significantly increased alpha waves, an indicator of a relaxed state, and decreased levels of immunoglobulin A (a marker of stress) in the study participants.","title":"Relaxation and immunity enhancement effects of Gamma-Aminobutyric acid (GABA) administration in humans"}]},"Sleep Latency":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/26052150/","notes":"Participants who took 100mg of GABA before bed showed a significant reduction in the time it took to fall asleep (sleep latency) compared to the placebo group.","title":"Effect of oral γ-aminobutyric acid (GABA) administration on sleep and its absorption in humans"}]},"Sleep Quality":{"score":5,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/30707852/","notes":"This study on a GABA and L-theanine combination found a significant increase in non-REM (NREM) sleep time, which is crucial for physical and mental restoration, indicating improved sleep quality.","title":"GABA and L-theanine mixture decreases sleep latency and improves NREM sleep"}]},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction","Cellular Senescence","Epigenetic Alterations"]'::text[] WHERE id = 'gaba';

