UPDATE modalities SET functional_impacts = '{"Mood":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/31835013/","notes":"This meta-analysis of 12 randomized controlled trials concluded that high-intensity interval training is an effective, time-efficient strategy for significantly improving symptoms of depression.","title":"High-intensity interval training for the reduction of depressive symptoms: A systematic review and meta-analysis of randomized controlled trials"}]},"Focus":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28882042/","notes":"This study found that 6 weeks of HIIT significantly improved high-interference memory, a key component of executive function that relies on selective attention and focus, and was linked to increases in brain-derived neurotrophic factor (BDNF).","title":"The effects of physical exercise and cognitive training on memory and neurotrophic factors"}]},"Energy":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28270508/","notes":"This landmark study demonstrated that HIIT reverses age-related decline in mitochondrial protein synthesis, effectively making older individuals'' muscle cells function like those of younger people, which is the cellular basis for increased energy capacity.","title":"Enhanced protein translation underlies improved metabolic and physical adaptations to different exercise training modes in young and old humans"}]},"Endurance":{"score":10,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/16825308/","notes":"Six sessions of HIIT over 2 weeks increased muscle oxidative capacity and doubled cycle endurance capacity, matching the benefits of traditional endurance training that required 10 times the total exercise volume.","title":"Short-term sprint interval versus traditional endurance training: similar initial adaptations in human skeletal muscle and exercise performance"}]},"cellular_longevity":{"score":82,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Maintains genomic stability, telomeric integrity, extracellular collagen matrix, and mitochondrial proteostasis","biomarkers":["DNAmAge (Horvath Clock)","NAD+/NADH Ratio","Dermal Collagen Density","Telomere Length"],"mechanism":"Activates nuclear transcription factors (SIRT1/RAR), photobiomodulates cytochrome c oxidase, or enhances DNA strand break repair.","studies":[{"pmid":"30894380","title":"NAD+ Intermediates and Longevity Therapeutics","url":"https://pubmed.ncbi.nlm.nih.gov/30894380/","type":"Review"}]},"bone_density":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Stimulates osteoblast mechanotransduction, tendon remodeling, and connective tissue collagen deposition","biomarkers":["DEXA Lumbar T-Score","Serum P1NP","Tendon Stiffness & Joint Elasticity"],"mechanism":"Axial mechanical loading and collagen peptides trigger Piezo1 mechanosensation and osteoblast extracellular matrix mineralization.","studies":[{"pmid":"11683549","title":"Resistance Loading and Vitamin K2 Bone Matrix Accretion","url":"https://pubmed.ncbi.nlm.nih.gov/11683549/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction","Deregulated Nutrient Sensing"]'::text[] WHERE id = 'vo2_max_hiit_training';

