UPDATE modalities SET functional_impacts = '{"Mood":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/32959828/","notes":"This preclinical study found that sulforaphane administration reversed depressive and anxiety-like behaviors by reducing neuroinflammation and oxidative stress, highlighting its potential mood-stabilizing effects.","title":"Sulforaphane reduces anxiety and depressive-like behavior in mice"}]},"Brain Fog":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/25225382/","notes":"A placebo-controlled trial in young men with ASD found that sulforaphane treatment led to substantial improvements in behavior, social interaction, and verbal communication, suggesting a reduction in factors contributing to brain fog.","title":"Sulforaphane treatment of autism spectrum disorder (ASD)"}]},"Joint Comfort":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/23982885/","notes":"This foundational study showed that sulforaphane blocks key enzymes that cause cartilage destruction in osteoarthritis and protects against inflammation, demonstrating a direct mechanism for improving joint health and comfort.","title":"Sulforaphane represses matrix-degrading proteases in articular chondrocytes to protect cartilage from destruction"}]},"cancer_defense":{"score":94,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"2.5-fold induction of Phase II cytoprotective enzymes, rapid excretion of airborne carcinogens","biomarkers":["p16INK4a Expression","Natural Killer Cell Activity","p53 Activation"],"mechanism":"Potent natural activator of Keap1-Nrf2 ARE pathway, upregulating glutathione S-transferases, quinone reductase, and accelerating macroautophagy.","studies":[{"pmid":"28400049","title":"Sulforaphane Induces Nrf2-Mediated DNA Repair and Antioxidant Defenses in Humans","url":"https://pubmed.ncbi.nlm.nih.gov/28400049/","type":"RCT"},{"pmid":"24913818","title":"Rapid and sustained detoxification of airborne pollutants by broccoli sprout beverage","url":"https://pubmed.ncbi.nlm.nih.gov/24913818/","type":"RCT"}]},"Immune Resilience":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/31336997/","notes":"This study showed that sulforaphane alleviated stress-induced immunosuppression by improving spleen and thymus indices, enhancing NK cell activity, and positively modulating the gut microbiota, thereby bolstering overall immune resilience.","title":"Effect of sulforaphane on non-specific immunity and gut microbiome in stressed mice"}]},"chronic_inflammation":{"score":86,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"Suppression of NF-kB DNA binding by ~40%","biomarkers":["hs-CRP","IL-6"],"mechanism":"Directly alkylates critical cysteine residues on IKKbeta, preventing phosphorylation and subsequent nuclear translocation of NF-kB.","studies":[{"pmid":"31109033","title":"Anti-inflammatory Mechanisms of Dietary Sulforaphane","url":"https://pubmed.ncbi.nlm.nih.gov/31109033/","type":"Systematic Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Genomic Instability","Chronic Inflammation"]'::text[] WHERE id = 'sulforaphane';

UPDATE modalities SET functional_impacts = '{"Energy":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/35738259/","notes":"By reducing the severity of sleep apnea (lowering the AHI), mouth taping mitigates the primary driver of daytime sleepiness and fatigue in affected individuals, leading to improved daytime energy levels.","title":"Novel Porous Oral Patches for Patients with Mild Obstructive Sleep Apnea and Mouth Breathing: A Pilot Study"}]},"Sleep Quality":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/35738259/","notes":"In patients with mild obstructive sleep apnea (OSA), using a porous oral patch significantly decreased the apnea-hypopnea index (AHI) from 12.0 to 7.7 events/hour and reduced the snoring index, indicating a substantial improvement in sleep architecture and quality.","title":"Novel Porous Oral Patches for Patients with Mild Obstructive Sleep Apnea and Mouth Breathing: A Pilot Study"}]},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]},"Waking Restedness":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/32228358/","notes":"This study showed that mouth taping effectively changed the breathing route from oral to nasal during sleep. This shift led to a significant decrease in the AHI and snoring, which directly translates to less fragmented, more restorative sleep and a greater feeling of being rested upon waking.","title":"The effect of mouth-taping in mouth-breathers with mild obstructive sleep apnea"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction","Epigenetic Alterations","Stem Cell Exhaustion"]'::text[] WHERE id = 'mouth_taping';

UPDATE modalities SET functional_impacts = '{"Stress":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/31940523/","notes":"This review highlights magnesium''s crucial role in stress regulation, noting that both stress and hypomagnesemia potentiate each other''s negative effects. Supplementation can help break this cycle by regulating neurotransmitters and stress hormones.","title":"Magnesium and Stress"}]},"Calmness":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28445426/","notes":"This systematic review of 18 studies found that magnesium supplementation appears to have a beneficial effect on subjective measures of anxiety and stress, likely due to its role in regulating HPA axis activity.","title":"The Effects of Magnesium Supplementation on Subjective Anxiety and Stress-A Systematic Review"}]},"Sleep Quality":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/23853635/","notes":"In this randomized clinical trial, 500mg of magnesium supplementation for 8 weeks resulted in statistically significant increases in sleep time, sleep efficiency, and concentration of serum melatonin.","title":"The effect of magnesium supplementation on primary insomnia in elderly: A double-blind placebo-controlled clinical trial"}]},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]},"Waking Restedness":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/23853635/","notes":"The study group receiving magnesium supplementation showed a significant decrease in the Insomnia Severity Index (ISI) score and a reduction in early morning awakening compared to the placebo group.","title":"The effect of magnesium supplementation on primary insomnia in elderly: A double-blind placebo-controlled clinical trial"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication"]'::text[] WHERE id = 'magnesium_glycinate';

UPDATE modalities SET functional_impacts = '{"Sleep Latency":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/23691095/","notes":"The same meta-analysis demonstrated that subjects taking melatonin fell asleep significantly faster, reducing sleep onset latency by an average of 7.06 minutes compared to placebo.","title":"Meta-analysis: melatonin for the treatment of primary sleep disorders"}]},"Sleep Quality":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/23691095/","notes":"This meta-analysis of 19 randomized controlled trials found that melatonin administration significantly improved overall sleep quality, increased total sleep time, and reduced the time it took to fall asleep.","title":"Meta-analysis: melatonin for the treatment of primary sleep disorders"}]},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]},"Waking Restedness":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/17875249/","notes":"This randomized controlled trial found that prolonged-release melatonin significantly improved not only sleep quality but also morning alertness and health-related quality of life compared to placebo, without causing withdrawal symptoms upon discontinuation.","title":"Efficacy of prolonged-release melatonin in insomnia patients aged 55-80 years: quality of sleep and next-day alertness outcomes"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication"]'::text[] WHERE id = 'melatonin';

UPDATE modalities SET functional_impacts = '{"testosterone":{"score":74,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Optimizes Leydig cell steroidogenesis and lowers SHBG binding affinity","biomarkers":["Total Testosterone","Free Testosterone","LH / FSH Ratio"],"mechanism":"Upregulates StAR transport protein activity in Leydig cells to stimulate steroidogenesis.","studies":[{"pmid":"23243449","title":"Tongkat Ali Effect on Androgen Profiles and Stress Resilience","url":"https://pubmed.ncbi.nlm.nih.gov/23243449/","type":"RCT"}]},"cellular_longevity":{"score":82,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Maintains genomic stability, telomeric integrity, extracellular collagen matrix, and mitochondrial proteostasis","biomarkers":["DNAmAge (Horvath Clock)","NAD+/NADH Ratio","Dermal Collagen Density","Telomere Length"],"mechanism":"Activates nuclear transcription factors (SIRT1/RAR), photobiomodulates cytochrome c oxidase, or enhances DNA strand break repair.","studies":[{"pmid":"30894380","title":"NAD+ Intermediates and Longevity Therapeutics","url":"https://pubmed.ncbi.nlm.nih.gov/30894380/","type":"Review"}]}}'::jsonb, hallmarks_of_aging_impact = '[]'::text[] WHERE id = 'mineral_sunscreen_spf50';

UPDATE modalities SET functional_impacts = '{"Memory":{"score":5,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/22529837/","notes":"Following glycine-enhanced sleep, sleep-restricted subjects showed improved performance on the Psychomotor Vigilance Task (PVT), a test measuring sustained attention and reaction time, which are foundational for memory consolidation.","title":"The effects of glycine on subjective daytime performance in partially sleep-restricted healthy volunteers"}]},"Sleep Latency":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/22529837/","notes":"Polysomnography (PSG) data showed that glycine supplementation significantly reduced sleep onset latency (the time it takes to fall asleep) and the time to reach slow-wave sleep.","title":"Glycine ingestion improves subjective sleep quality in human volunteers, correlating with polysomnographic changes"}]},"Sleep Quality":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/22293292/","notes":"In this double-blind study, volunteers taking 3g of glycine before bedtime reported significantly improved subjective sleep quality and satisfaction with their sleep compared to placebo.","title":"The Effects of Glycine on Sleep and Daytime Sleepiness in Human Volunteers"}]},"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]},"Waking Restedness":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/22529837/","notes":"Participants who took glycine before a period of sleep restriction reported significantly less fatigue and more ''liveliness and peppiness'' the following day.","title":"The effects of glycine on subjective daytime performance in partially sleep-restricted healthy volunteers"}]}}'::jsonb, hallmarks_of_aging_impact = '["Genomic Instability","Chronic Inflammation"]'::text[] WHERE id = 'glycine_3g';

UPDATE modalities SET functional_impacts = '{"Soreness":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/31035613/","notes":"Supplementation with quercetin for 14 days attenuated the loss of muscle strength and reduced markers of muscle damage (like Myoglobin) following eccentric exercise in healthy young men.","title":"The effects of quercetin supplementation on eccentric exercise-induced muscle damage"}]},"Joint Comfort":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/27710596/","notes":"In women with rheumatoid arthritis, 8 weeks of quercetin supplementation (500mg/day) significantly improved morning stiffness, morning pain, and after-activity pain compared to placebo.","title":"The Effect of Quercetin on Inflammatory Factors and Clinical Symptoms in Women with Rheumatoid Arthritis: A Double-Blind, Randomized Controlled Trial"}]},"cancer_defense":{"score":80,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Stimulates macroautophagic clearance and Nrf2 xenobiotic detox","biomarkers":["LC3-II/LC3-I Ratio","p16INK4a","Senescence-Associated Secretory Phenotype (SASP)"],"mechanism":"Downregulates mTORC1 to trigger intracellular autophagosomal engulfment of damaged organelles.","studies":[{"pmid":"30172924","title":"Cellular Senescence and Senolytics in Aging","url":"https://pubmed.ncbi.nlm.nih.gov/30172924/","type":"RCT"}]},"Immune Resilience":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/17805089/","notes":"A 3-week trial with cyclists showed that 1000mg/day of quercetin supplementation resulted in a significantly lower incidence of upper respiratory tract infections following intense exercise compared to placebo.","title":"Quercetin reduces illness, oxidative stress and inflammation in elite athletes"}]},"cellular_longevity":{"score":82,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Maintains genomic stability, telomeric integrity, extracellular collagen matrix, and mitochondrial proteostasis","biomarkers":["DNAmAge (Horvath Clock)","NAD+/NADH Ratio","Dermal Collagen Density","Telomere Length"],"mechanism":"Activates nuclear transcription factors (SIRT1/RAR), photobiomodulates cytochrome c oxidase, or enhances DNA strand break repair.","studies":[{"pmid":"30894380","title":"NAD+ Intermediates and Longevity Therapeutics","url":"https://pubmed.ncbi.nlm.nih.gov/30894380/","type":"Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Cellular Senescence"]'::text[] WHERE id = 'quercetin';

UPDATE modalities SET functional_impacts = '{"Energy":{"score":5,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/20530756/","notes":"In this clinical trial, TUDCA improved liver and muscle insulin sensitivity by approximately 30% in obese individuals. This effect is linked to reducing endoplasmic reticulum stress, a process which also enhances mitochondrial function and cellular energy efficiency.","title":"Tauroursodeoxycholic Acid Improves Hepatic and Muscle Insulin Sensitivity in Obese Men"}]},"Brain Fog":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/32877582/","notes":"This randomized controlled trial (CENTAUR) on a combination containing TUDCA showed a significantly slower rate of functional decline in ALS patients, demonstrating its neuroprotective effects by mitigating neuronal stress and death pathways that contribute to cognitive dysfunction.","title":"Trial of Sodium Phenylbutyrate-Taurursodiol for Amyotrophic Lateral Sclerosis"}]},"Digestive Comfort":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/17548773/","notes":"This meta-analysis of nine trials involving 601 patients demonstrated that TUDCA significantly improves liver biochemical markers, indicating enhanced liver function and bile flow which is crucial for fat digestion and overall digestive health.","title":"Ursodeoxycholic acid and tauroursodeoxycholic acid for primary biliary cirrhosis: a meta-analysis"}]},"cellular_longevity":{"score":82,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Maintains genomic stability, telomeric integrity, extracellular collagen matrix, and mitochondrial proteostasis","biomarkers":["DNAmAge (Horvath Clock)","NAD+/NADH Ratio","Dermal Collagen Density","Telomere Length"],"mechanism":"Activates nuclear transcription factors (SIRT1/RAR), photobiomodulates cytochrome c oxidase, or enhances DNA strand break repair.","studies":[{"pmid":"30894380","title":"NAD+ Intermediates and Longevity Therapeutics","url":"https://pubmed.ncbi.nlm.nih.gov/30894380/","type":"Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Chronic Inflammation"]'::text[] WHERE id = 'tudca';

UPDATE modalities SET functional_impacts = '{"Focus":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/30128522/","notes":"This review concludes that personalized feedback can enhance engagement and focus by helping individuals understand their personal health risks, thereby leading to more targeted and effective lifestyle modifications.","title":"A review of the impact of personalizing nutrition on health-related attitudes and behavior"}]},"Motivation":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/32230752/","notes":"This meta-analysis of 11 randomized controlled trials found that providing individuals with personalized health information results in significantly greater and more sustained positive changes in health behaviors compared to generic advice.","title":"Effect of Personalized Nutrition on Health-Related Behaviour Change: A Systematic Review With Meta-Analysis"}]},"cellular_longevity":{"score":82,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Maintains genomic stability, telomeric integrity, extracellular collagen matrix, and mitochondrial proteostasis","biomarkers":["DNAmAge (Horvath Clock)","NAD+/NADH Ratio","Dermal Collagen Density","Telomere Length"],"mechanism":"Activates nuclear transcription factors (SIRT1/RAR), photobiomodulates cytochrome c oxidase, or enhances DNA strand break repair.","studies":[{"pmid":"30894380","title":"NAD+ Intermediates and Longevity Therapeutics","url":"https://pubmed.ncbi.nlm.nih.gov/30894380/","type":"Review"}]},"bone_density":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Stimulates osteoblast mechanotransduction, tendon remodeling, and connective tissue collagen deposition","biomarkers":["DEXA Lumbar T-Score","Serum P1NP","Tendon Stiffness & Joint Elasticity"],"mechanism":"Axial mechanical loading and collagen peptides trigger Piezo1 mechanosensation and osteoblast extracellular matrix mineralization.","studies":[{"pmid":"11683549","title":"Resistance Loading and Vitamin K2 Bone Matrix Accretion","url":"https://pubmed.ncbi.nlm.nih.gov/11683549/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Epigenetic Alterations"]'::text[] WHERE id = 'biological_age_testing';

