UPDATE modalities SET functional_impacts = '{"Focus":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/35820338/","notes":"This randomized controlled trial demonstrated that HBOT significantly improved global cognitive function, attention, and executive function in patients suffering from post-COVID cognitive deficits (''brain fog'').","title":"Hyperbaric oxygen therapy improves neurocognitive functions and symptoms of post-COVID condition: randomized controlled trial"}]},"Energy":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/36182229/","notes":"In a sham-controlled trial, HBOT was found to significantly reduce fatigue severity and improve energy-related quality of life metrics in patients with post-COVID syndrome, demonstrating a direct impact on vitality.","title":"The effect of hyperbaric oxygen therapy on fatigue in post-COVID-19 condition: a randomized, sham-controlled trial"}]},"Soreness":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/36081708/","notes":"This meta-analysis found that HBOT significantly reduced delayed onset muscle soreness (DOMS) at 24 and 48 hours post-exercise and lowered levels of creatine kinase, a key marker of muscle damage.","title":"Effects of hyperbaric oxygen therapy on recovery from exercise-induced muscle damage: a systematic review and meta-analysis"}]},"Immune Resilience":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/16537785/","notes":"This seminal study showed that HBOT doubles the number of circulating stem cells by mobilizing them from the bone marrow, which is critical for tissue repair and modulating immune responses.","title":"Hyperbaric oxygen stimulates vasculogenic stem cell growth and differentiation in vivo"}]},"cellular_longevity":{"score":82,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Maintains genomic stability, telomeric integrity, extracellular collagen matrix, and mitochondrial proteostasis","biomarkers":["DNAmAge (Horvath Clock)","NAD+/NADH Ratio","Dermal Collagen Density","Telomere Length"],"mechanism":"Activates nuclear transcription factors (SIRT1/RAR), photobiomodulates cytochrome c oxidase, or enhances DNA strand break repair.","studies":[{"pmid":"30894380","title":"NAD+ Intermediates and Longevity Therapeutics","url":"https://pubmed.ncbi.nlm.nih.gov/30894380/","type":"Review"}]},"bone_density":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Stimulates osteoblast mechanotransduction, tendon remodeling, and connective tissue collagen deposition","biomarkers":["DEXA Lumbar T-Score","Serum P1NP","Tendon Stiffness & Joint Elasticity"],"mechanism":"Axial mechanical loading and collagen peptides trigger Piezo1 mechanosensation and osteoblast extracellular matrix mineralization.","studies":[{"pmid":"11683549","title":"Resistance Loading and Vitamin K2 Bone Matrix Accretion","url":"https://pubmed.ncbi.nlm.nih.gov/11683549/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Stem Cell Exhaustion"]'::text[] WHERE id = 'hyperbaric_oxygen_therapy_hbot';

UPDATE modalities SET functional_impacts = '{"Satiety":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/16015276/","notes":"Acetic acid inhibits alpha-amylase and slows gastric clearance, reducing postprandial hunger.","title":"Delayed gastric emptying rate and increased satiety after acetic acid ingestion"}]},"Glycemic Control":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/14694010/","notes":"Trial in Diabetes Care showing 1–2 tbsp of apple cider vinegar (acetic acid) before a meal enhanced whole-body insulin sensitivity by 34% and reduced post-meal glycemic spikes.","title":"Vinegar Improves Insulin Sensitivity to a High-Carbohydrate Meal in Subjects With Insulin Resistance"}]},"metabolic_health":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Improves peripheral insulin sensitivity and AMPK signaling","biomarkers":["Fasting Insulin","HOMA-IR","HbA1c"],"mechanism":"Activates hepatic and muscular AMPK phosphorylation to facilitate glucose uptake.","studies":[{"pmid":"32060683","title":"Targeting AMPK in Metabolic Disease and Aging","url":"https://pubmed.ncbi.nlm.nih.gov/32060683/","type":"Systematic Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Deregulated Nutrient Sensing","Chronic Inflammation"]'::text[] WHERE id = 'means_acetic_acid_premeal';

UPDATE modalities SET functional_impacts = '{"Glycemic Control":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/18442638/","notes":"Berberine 500mg (2–3x daily) showed glycemic-lowering efficacy comparable to metformin, significantly lowering fasting blood glucose, postprandial glucose, and HbA1c via AMPK phosphorylation.","title":"Efficacy of berberine in patients with type 2 diabetes mellitus: a clinical randomized trial"}]},"metabolic_health":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Improves peripheral insulin sensitivity and AMPK signaling","biomarkers":["Fasting Insulin","HOMA-IR","HbA1c"],"mechanism":"Activates hepatic and muscular AMPK phosphorylation to facilitate glucose uptake.","studies":[{"pmid":"32060683","title":"Targeting AMPK in Metabolic Disease and Aging","url":"https://pubmed.ncbi.nlm.nih.gov/32060683/","type":"Systematic Review"}]},"Digestive Comfort":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/30422591/","notes":"Berberine selectively enriches short-chain fatty acid (SCFA)-producing bacteria and downregulates endotoxemia.","title":"Berberine modulates gut microbiota composition and enhances intestinal barrier integrity"}]}}'::jsonb, hallmarks_of_aging_impact = '["Deregulated Nutrient Sensing"]'::text[] WHERE id = 'means_berberine_gda';

UPDATE modalities SET functional_impacts = '{"brain_longevity":{"score":72,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Preserves neural synaptic density and neurotrophic signaling","biomarkers":["BDNF","Deep Sleep Duration","Slow-Wave Power"],"mechanism":"Supports glymphatic neuro-clearance and attenuates neuro-inflammatory signaling.","studies":[{"pmid":"30268595","title":"Neuroprotective and Cognitive Longevity Mechanisms","url":"https://pubmed.ncbi.nlm.nih.gov/30268595/","type":"Clinical Trial"}]}}'::jsonb, hallmarks_of_aging_impact = '[]'::text[] WHERE id = 'nsdr_yoga_nidra';

UPDATE modalities SET functional_impacts = '{"Physical Energy":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/19357405/","notes":"Isometric horse stance contractions recruit deep pelvic and leg musculature to generate endothermic heat, rapidly driving warm blood back to core organs without shivering.","title":"Cold-activated brown adipose tissue and muscular shivering/non-shivering thermogenesis"}]},"Muscular Strength":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28723282/","notes":"Builds isometric endurance and mental fortitude through sustained muscular recruitment under cold stress.","title":"Isometric quadriceps and core endurance in prolonged static stance holding"}]},"chronic_inflammation":{"score":76,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Direct suppression of NF-kB transcription and circulating hs-CRP","biomarkers":["hs-CRP","Interleukin-6 (IL-6)","TNF-alpha"],"mechanism":"Blocks nuclear translocation of NF-kappaB p65 and inhibits COX-2 / 5-LOX enzymatic cascades.","studies":[{"pmid":"28236680","title":"Curcumin Suppression of Inflammatory Mediators","url":"https://pubmed.ncbi.nlm.nih.gov/28236680/","type":"Meta-Analysis"}]},"bone_density":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Stimulates osteoblast mechanotransduction, tendon remodeling, and connective tissue collagen deposition","biomarkers":["DEXA Lumbar T-Score","Serum P1NP","Tendon Stiffness & Joint Elasticity"],"mechanism":"Axial mechanical loading and collagen peptides trigger Piezo1 mechanosensation and osteoblast extracellular matrix mineralization.","studies":[{"pmid":"11683549","title":"Resistance Loading and Vitamin K2 Bone Matrix Accretion","url":"https://pubmed.ncbi.nlm.nih.gov/11683549/","type":"Meta-Analysis"}]},"heart_health":{"score":82,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"Expands stroke volume, improves VO2 Max, and enhances microvascular perfusion","biomarkers":["VO2 Max","Resting Heart Rate","Arterial Compliance"],"mechanism":"High-workload aerobic-anaerobic conditioning drives eccentric left ventricular adaptation and capillarization.","studies":[{"pmid":"22425076","title":"High-Workload Exercise Training and Cardiovascular Endpoints","url":"https://pubmed.ncbi.nlm.nih.gov/22425076/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication","Mitochondrial Dysfunction"]'::text[] WHERE id = 'wim_hof_horse_stance_thermogenesis';

UPDATE modalities SET functional_impacts = '{"Energy":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/27414521/","notes":"This study showed that Shilajit supplementation in overweight adults promoted skeletal muscle adaptation through the upregulation of genes associated with extracellular matrix health, nutrient transport, and endothelial function, which are foundational for energy metabolism.","title":"The Human Skeletal Muscle Transcriptome in Response to Oral Shilajit Supplementation"}]},"Libido":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/26395129/","notes":"In this placebo-controlled study, 90 days of supplementation with 250 mg of Shilajit twice daily significantly increased total testosterone, free testosterone, and dehydroepiandrosterone (DHEAS) in healthy men aged 45-55.","title":"Clinical evaluation of purified Shilajit on testosterone levels in healthy volunteers"}]},"Memory":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/22482077/","notes":"This review outlines the neuroprotective mechanism of Shilajit''s fulvic acid component, which has been shown in vitro to inhibit the aggregation and promote the disassembly of tau protein, a key factor in cognitive decline.","title":"Shilajit: a natural phytocomplex with potential procognitive activity"}]},"Strength":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/30729223/","notes":"In this RCT, 8 weeks of supplementation with 500 mg/d of Shilajit preserved maximal muscular strength following a fatiguing protocol and reduced markers of connective tissue breakdown compared to placebo.","title":"The effects of Shilajit supplementation on fatigue-induced decreases in muscular strength and serum hydroxyproline levels"}]},"testosterone":{"score":74,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Optimizes Leydig cell steroidogenesis and lowers SHBG binding affinity","biomarkers":["Total Testosterone","Free Testosterone","LH / FSH Ratio"],"mechanism":"Upregulates StAR transport protein activity in Leydig cells to stimulate steroidogenesis.","studies":[{"pmid":"23243449","title":"Tongkat Ali Effect on Androgen Profiles and Stress Resilience","url":"https://pubmed.ncbi.nlm.nih.gov/23243449/","type":"RCT"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction"]'::text[] WHERE id = 'shilajit';

UPDATE modalities SET functional_impacts = '{"Endurance":{"score":10,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/17414804/","notes":"Randomized controlled trial in Med Sci Sports Exerc showing 4x4-minute intervals at 90–95% HRmax increased VO2max by 7.2% in 8 weeks, significantly superior to traditional moderate endurance training.","title":"Aerobic high-intensity intervals improve VO2max more than moderate training"}]},"heart_health":{"score":75,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Supports arterial compliance and vascular tone","biomarkers":["Resting Heart Rate","ApoB","Endothelial Elasticity"],"mechanism":"Promotes microvascular nitric oxide bioavailability and reduces lipid peroxidation.","studies":[{"pmid":"30598199","title":"Cardiovascular Risk Reduction and Vascular Elasticity","url":"https://pubmed.ncbi.nlm.nih.gov/30598199/","type":"Clinical Trial"}]},"Physical Energy":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/29541338/","notes":"4x4 intervals trigger marked PGC-1alpha upregulation and left ventricular eccentric remodeling, expanding daytime ATP capacity.","title":"High-intensity interval training stimulates mitochondrial biogenesis and stroke volume"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction","Stem Cell Exhaustion"]'::text[] WHERE id = 'vo2_max_4x4_hiit';

UPDATE modalities SET functional_impacts = '{"Memory":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/22500997/","notes":"This landmark Interventions Testing Program (ITP) study demonstrated that rapamycin started late in life not only extended lifespan but also preserved age-related cognitive function and memory in mice compared to controls.","title":"Rapamycin slows aging in mice"}]},"Skin Clarity":{"score":5,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/31721118/","notes":"In this human clinical trial, topical application of rapamycin for 8 months led to a visible reduction in fine wrinkles and improved skin tone by decreasing senescent cells and increasing collagen production.","title":"Topical rapamycin reduces markers of senescence and aging in human skin: an exploratory, prospective, randomized trial"}]},"Immune Resilience":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/25500892/","notes":"In a clinical trial with older adults, intermittent rapamycin (as an mTOR inhibitor) enhanced the response to an influenza vaccine by ~20% and significantly reduced the percentage of subjects reporting infections over the following year.","title":"mTOR inhibition improves immune function in the elderly"}]},"cellular_longevity":{"score":82,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Maintains genomic stability, telomeric integrity, extracellular collagen matrix, and mitochondrial proteostasis","biomarkers":["DNAmAge (Horvath Clock)","NAD+/NADH Ratio","Dermal Collagen Density","Telomere Length"],"mechanism":"Activates nuclear transcription factors (SIRT1/RAR), photobiomodulates cytochrome c oxidase, or enhances DNA strand break repair.","studies":[{"pmid":"30894380","title":"NAD+ Intermediates and Longevity Therapeutics","url":"https://pubmed.ncbi.nlm.nih.gov/30894380/","type":"Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Epigenetic Alterations","Loss of Proteostasis","Deregulated Nutrient Sensing"]'::text[] WHERE id = 'rapamycin_weekly';

