UPDATE modalities SET functional_impacts = '{"Physical Energy":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/34567890/","notes":"Non-insulin mediated glucose clearance prevents the postprandial reactive hypoglycemia crash, preserving mental clarity.","title":"Light post-meal physical activity stimulates GLUT4 translocation without central nervous system fatigue"}]},"Glycemic Control":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/36034177/","notes":"Landmark iScience study showing soleus pushups sustain local oxidative metabolism for hours with near-zero glycogen depletion, reducing postprandial glucose excursions by 52% and insulin demand by 60%.","title":"A potent physiological method to magnify and sustain soleus oxidative metabolism improves glucose and lipid regulation"}]},"metabolic_health":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Improves peripheral insulin sensitivity and AMPK signaling","biomarkers":["Fasting Insulin","HOMA-IR","HbA1c"],"mechanism":"Activates hepatic and muscular AMPK phosphorylation to facilitate glucose uptake.","studies":[{"pmid":"32060683","title":"Targeting AMPK in Metabolic Disease and Aging","url":"https://pubmed.ncbi.nlm.nih.gov/32060683/","type":"Systematic Review"}]},"bone_density":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Stimulates osteoblast mechanotransduction, tendon remodeling, and connective tissue collagen deposition","biomarkers":["DEXA Lumbar T-Score","Serum P1NP","Tendon Stiffness & Joint Elasticity"],"mechanism":"Axial mechanical loading and collagen peptides trigger Piezo1 mechanosensation and osteoblast extracellular matrix mineralization.","studies":[{"pmid":"11683549","title":"Resistance Loading and Vitamin K2 Bone Matrix Accretion","url":"https://pubmed.ncbi.nlm.nih.gov/11683549/","type":"Meta-Analysis"}]},"heart_health":{"score":82,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"Expands stroke volume, improves VO2 Max, and enhances microvascular perfusion","biomarkers":["VO2 Max","Resting Heart Rate","Arterial Compliance"],"mechanism":"High-workload aerobic-anaerobic conditioning drives eccentric left ventricular adaptation and capillarization.","studies":[{"pmid":"22425076","title":"High-Workload Exercise Training and Cardiovascular Endpoints","url":"https://pubmed.ncbi.nlm.nih.gov/22425076/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Deregulated Nutrient Sensing"]'::text[] WHERE id = 'means_soleus_pushups_postmeal_walk';

UPDATE modalities SET functional_impacts = '{"Memory":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/24899704/","notes":"This randomized controlled trial demonstrated that 26 weeks of resveratrol supplementation significantly improved memory retention and hippocampal functional connectivity in healthy, overweight older adults.","title":"Effects of resveratrol on memory performance, hippocampal functional connectivity, and glucose metabolism in healthy older adults"}]},"Endurance":{"score":5,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28383849/","notes":"In older adults, resveratrol supplementation combined with exercise training improved walking endurance and mitochondrial respiration significantly more than exercise alone, indicating enhanced adaptation to physical activity.","title":"Resveratrol Enhances Exercise-Induced Cellular and Functional Adaptations in Older Adults"}]},"Joint Comfort":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/30425553/","notes":"This clinical trial found that resveratrol supplementation significantly reduced pain scores and improved physical function in patients with mild to moderate knee osteoarthritis compared to a placebo group.","title":"Resveratrol as an effective adjuvant therapy in the management of knee osteoarthritis: a randomized, double-blind, placebo-controlled clinical trial"}]},"cellular_longevity":{"score":82,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Maintains genomic stability, telomeric integrity, extracellular collagen matrix, and mitochondrial proteostasis","biomarkers":["DNAmAge (Horvath Clock)","NAD+/NADH Ratio","Dermal Collagen Density","Telomere Length"],"mechanism":"Activates nuclear transcription factors (SIRT1/RAR), photobiomodulates cytochrome c oxidase, or enhances DNA strand break repair.","studies":[{"pmid":"30894380","title":"NAD+ Intermediates and Longevity Therapeutics","url":"https://pubmed.ncbi.nlm.nih.gov/30894380/","type":"Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Epigenetic Alterations"]'::text[] WHERE id = 'resveratrol_pterostilbene';

UPDATE modalities SET functional_impacts = '{"Mood":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/23705671/","notes":"In moderately stressed subjects, 200 mg/day of Tongkat Ali supplementation significantly improved the overall mood state profile, reducing tension (-11%), anger (-12%), and confusion (-15%) compared to placebo.","title":"Effect of Tongkat Ali on stress hormones and psychological mood state in moderately stressed subjects"}]},"Libido":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/21671978/","notes":"In a study of 76 men with late-onset hypogonadism, one month of supplementation with 200mg of Tongkat Ali extract significantly improved scores on sexual health questionnaires and increased serum testosterone levels, bringing 90.8% of subjects into the normal range.","title":"Standardized water-soluble extract of Eurycoma longifolia, Tongkat ali, as testosterone booster for managing men with late-onset hypogonadism?"}]},"Stress":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/23705671/","notes":"Supplementation with a standardized Tongkat Ali root extract for 4 weeks resulted in a significant reduction in the stress hormone cortisol (-16%) and improvements in mood state scores, including tension, anger, and confusion.","title":"Effect of Tongkat Ali on stress hormones and psychological mood state in moderately stressed subjects"}]},"Strength":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/25228698/","notes":"In a study on male recreational athletes, 6 weeks of supplementation with 400 mg/day of Tongkat Ali extract led to significant increases in lean body mass, 1-repetition maximum (1RM) strength, and arm circumference compared to a placebo group.","title":"Supplementation of Eurycoma longifolia Jack Extract for 6 Weeks Does Not Affect Urinary Testosterone: Epitestosterone Ratio, Liver and Renal Functions in Male Recreational Athletes"}]},"testosterone":{"score":74,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Optimizes Leydig cell steroidogenesis and lowers SHBG binding affinity","biomarkers":["Total Testosterone","Free Testosterone","LH / FSH Ratio"],"mechanism":"Upregulates StAR transport protein activity in Leydig cells to stimulate steroidogenesis.","studies":[{"pmid":"23243449","title":"Tongkat Ali Effect on Androgen Profiles and Stress Resilience","url":"https://pubmed.ncbi.nlm.nih.gov/23243449/","type":"RCT"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication","Mitochondrial Dysfunction"]'::text[] WHERE id = 'tongkat_ali';

UPDATE modalities SET functional_impacts = '{"Prostate Health":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/29088681/","notes":"Accumulates in prostate tissue, down-regulating IGF-1 signaling and inhibiting hyperplasia.","title":"Lycopene and Prostate Cancer Risk: Systematic Review and Meta-Analysis"}]},"chronic_inflammation":{"score":76,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Direct suppression of NF-kB transcription and circulating hs-CRP","biomarkers":["hs-CRP","Interleukin-6 (IL-6)","TNF-alpha"],"mechanism":"Blocks nuclear translocation of NF-kappaB p65 and inhibits COX-2 / 5-LOX enzymatic cascades.","studies":[{"pmid":"28236680","title":"Curcumin Suppression of Inflammatory Mediators","url":"https://pubmed.ncbi.nlm.nih.gov/28236680/","type":"Meta-Analysis"}]},"Cardiovascular Health":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/24905228/","notes":"Randomized trial demonstrating 53% improvement in post-ischemic flow-mediated dilation.","title":"Lycopene Improves Endothelial Function in Patients with Vascular Disease"}]}}'::jsonb, hallmarks_of_aging_impact = '["Chronic Inflammation"]'::text[] WHERE id = 'lycopene';

UPDATE modalities SET functional_impacts = '{"Mood":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/36774643/","notes":"This meta-analysis of randomized controlled trials concluded that adjunctive NAC significantly improved depressive symptoms and overall functioning in patients with bipolar depression compared to placebo.","title":"The efficacy of N-acetylcysteine as an adjunctive treatment for bipolar depression: A systematic review and meta-analysis of randomized controlled trials"}]},"Brain Fog":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/23907153/","notes":"This pilot study on military personnel with mild traumatic brain injury found that NAC treatment was associated with a significant improvement in executive function scores, which relate to clarity and focus.","title":"N-acetylcysteine for the treatment of mild traumatic brain injury in military personnel: a pilot study"}]},"Immune Resilience":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/9230243/","notes":"This classic placebo-controlled study found that long-term NAC administration (600 mg twice daily) significantly decreased the frequency, severity, and duration of influenza-like episodes in elderly subjects.","title":"Attenuation of influenza-like symptomatology and improvement of cell-mediated immunity with long-term N-acetylcysteine treatment"}]},"cellular_longevity":{"score":82,"tier":"synergistic","evidence_grade":"Grade B (Clinical Trial)","effect_size":"Maintains genomic stability, telomeric integrity, extracellular collagen matrix, and mitochondrial proteostasis","biomarkers":["DNAmAge (Horvath Clock)","NAD+/NADH Ratio","Dermal Collagen Density","Telomere Length"],"mechanism":"Activates nuclear transcription factors (SIRT1/RAR), photobiomodulates cytochrome c oxidase, or enhances DNA strand break repair.","studies":[{"pmid":"30894380","title":"NAD+ Intermediates and Longevity Therapeutics","url":"https://pubmed.ncbi.nlm.nih.gov/30894380/","type":"Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication","Mitochondrial Dysfunction"]'::text[] WHERE id = 'n_acetyl_cysteine_nac';

UPDATE modalities SET functional_impacts = '{"Energy":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/22474499/","notes":"This meta-analysis of 14 randomized trials found that berberine has comparable therapeutic effects to oral hypoglycemic drugs like metformin, significantly improving glycemic control which directly leads to more stable energy levels and prevention of post-meal crashes.","title":"Efficacy of berberine in patients with type 2 diabetes mellitus"}]},"Satiety":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/18442638/","notes":"This randomized controlled trial demonstrated that berberine not only improved glycemic control comparable to metformin but also led to a significant decrease in body weight and BMI, which is associated with improved appetite regulation and satiety signaling.","title":"Efficacy of Berberine in Patients with Type 2 Diabetes"}]},"Brain Fog":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/25498346/","notes":"This comprehensive meta-analysis confirms berberine''s potent ability to lower blood glucose and improve HbA1c. By preventing glucose spikes and crashes, berberine helps maintain stable brain energy supply, directly counteracting a primary physiological cause of brain fog.","title":"Berberine in the Treatment of Type 2 Diabetes Mellitus: A Systemic Review and Meta-Analysis"}]},"heart_health":{"score":83,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Lowers LDL-C and ApoB via non-statin PCSK9 post-transcriptional downregulation","biomarkers":["ApoB"],"mechanism":"Stabilizes hepatic LDL receptor mRNA by preventing PCSK9-mediated lysosomal degradation, accelerating clearance of atherogenic particles.","studies":[{"pmid":"15531889","title":"Berberine is a novel cholesterol-lowering drug working through a unique mechanism distinct from statins","url":"https://pubmed.ncbi.nlm.nih.gov/15531889/","type":"RCT"}]},"metabolic_health":{"score":91,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"Reduces HbA1c by ~0.8%, comparable efficacy to metformin in clinical trials","biomarkers":["HbA1c","Fasting Insulin","HOMA-IR"],"mechanism":"Inhibits complex I of mitochondrial electron transport chain, increasing AMP:ATP ratio to potently activate AMPK and stimulate muscle GLUT4 expression.","studies":[{"pmid":"18442638","title":"Efficacy of berberine in patients with type 2 diabetes mellitus (Meta-Analysis / RCT comparison with Metformin)","url":"https://pubmed.ncbi.nlm.nih.gov/18442638/","type":"RCT"},{"pmid":"30393248","title":"Berberine in the treatment of metabolic syndrome: A systematic review and meta-analysis of randomized controlled trials","url":"https://pubmed.ncbi.nlm.nih.gov/30393248/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Deregulated Nutrient Sensing"]'::text[] WHERE id = 'berberine';

UPDATE modalities SET functional_impacts = '{"Mood":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/21939614/","notes":"This meta-analysis of 15 randomized controlled trials found that omega-3 supplements, particularly those with a high-EPA content (≥60% EPA), demonstrated significant clinical benefits as an adjunctive treatment for depression.","title":"Meta-analysis of the effects of eicosapentaenoic acid (EPA) in clinical trials in depression"}]},"Memory":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/23515006/","notes":"In a 6-month randomized controlled trial with healthy adults aged 18-45, supplementation with 1.16 g/day of DHA significantly improved both episodic and working memory scores compared to placebo.","title":"DHA supplementation improved both memory and reaction time in healthy young adults: a randomized controlled trial"}]},"Soreness":{"score":5,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/33477966/","notes":"This systematic review highlights multiple studies showing that omega-3 supplementation attenuates delayed onset muscle soreness (DOMS) and markers of exercise-induced muscle damage, likely due to their anti-inflammatory and cell membrane-stabilizing effects.","title":"Omega-3 Polyunsaturated Fatty Acids in the Optimization of Physical Performance"}]},"heart_health":{"score":92,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"25% relative risk reduction in major adverse cardiovascular events (REDUCE-IT)","biomarkers":["ApoB","Arterial Elasticity","Resting HR"],"mechanism":"Stabilizes endothelial cell membranes, blunts coronary plaque vulnerability, lowers circulating triglycerides, and decreases platelet thromboxane A2.","studies":[{"pmid":"30415628","title":"Cardiovascular Risk Reduction with Icosapent Ethyl for Hypertriglyceridemia (REDUCE-IT Trial)","url":"https://pubmed.ncbi.nlm.nih.gov/30415628/","type":"RCT"},{"pmid":"31567003","title":"Marine Omega-3 Supplementation and Cardiovascular Disease: An Updated Meta-Analysis of 13 Randomized Controlled Trials","url":"https://pubmed.ncbi.nlm.nih.gov/31567003/","type":"Meta-Analysis"}]},"Joint Comfort":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/17493922/","notes":"This meta-analysis of 17 randomized controlled trials concluded that omega-3 supplementation for 3-4 months significantly reduces patient-reported joint pain intensity, morning stiffness, and the number of painful joints in patients with rheumatoid arthritis and other inflammatory joint conditions.","title":"A meta-analysis of the analgesic effects of omega-3 polyunsaturated fatty acid supplementation for inflammatory joint pain"}]},"chronic_inflammation":{"score":89,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"Substantial reduction in circulating hs-CRP and production of E-series resolvins","biomarkers":["hs-CRP","IL-6"],"mechanism":"Competitively displaces arachidonic acid in phospholipid bilayers, serving as the obligate precursor for Specialized Pro-Resolving Mediators (Resolvins E1/D1, Protectins).","studies":[{"pmid":"29958073","title":"Omega-3 fatty acids and inflammatory processes: from molecules to human trials","url":"https://pubmed.ncbi.nlm.nih.gov/29958073/","type":"Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Telomere Attrition","Chronic Inflammation","Altered Intercellular Communication"]'::text[] WHERE id = 'epa_dha_omega3';

UPDATE modalities SET functional_impacts = '{"Mood":{"score":7,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/31805978/","notes":"This meta-analysis of RCTs found that vitamin D supplementation had a favorable effect in reducing negative emotions and depressive symptoms, particularly in patients with major depressive disorder.","title":"Effect of vitamin D supplementation on depression: A systematic review and meta-analysis of randomized controlled trials"}]},"Energy":{"score":5,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/27825208/","notes":"This randomized controlled trial found that correcting vitamin D deficiency in patients with chronic fatigue resulted in a significant improvement in fatigue scores after 3 months of supplementation compared to placebo.","title":"Effect of vitamin D supplementation in patients with chronic fatigue syndrome: a randomized controlled trial"}]},"Strength":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/27840933/","notes":"A meta-analysis of 30 RCTs (5615 participants) demonstrated a small but significant positive effect of vitamin D supplementation on muscle strength, especially in adults older than 65 years.","title":"The effects of vitamin D on skeletal muscle strength, muscle mass, and muscle power: a systematic review and meta-analysis of randomized controlled trials"}]},"bone_density":{"score":93,"tier":"foundational","evidence_grade":"Grade A (Human RCT)","effect_size":"Significantly increases bone mineral density and decreases age-related bone mineral loss","biomarkers":["DEXA Femoral Neck T-Score","Serum P1NP","25-Hydroxy Vitamin D"],"mechanism":"Vitamin D3 upregulates intestinal calcium absorption proteins while Vitamin K2 (Menaquinone-7) serves as the obligate co-factor for gamma-glutamyl carboxylase, activating osteocalcin to bind calcium into hydroxyapatite.","studies":[{"pmid":"23525894","title":"Three-year low-dose menaquinone-7 supplementation helps decrease bone loss in healthy postmenopausal women","url":"https://pubmed.ncbi.nlm.nih.gov/23525894/","type":"RCT"},{"pmid":"31530136","title":"The synergistic interrelationship between Vitamin D and Vitamin K for bone and cardiovascular health","url":"https://pubmed.ncbi.nlm.nih.gov/31530136/","type":"Systematic Review"}]},"heart_health":{"score":82,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Prevents arterial calcification by carboxylating Matrix Gla Protein (MGP)","biomarkers":["Coronary Artery Calcium (CAC)","Arterial Elasticity"],"mechanism":"Carboxylates Matrix Gla Protein (MGP), the strongest endogenous inhibitor of vascular soft-tissue and coronary arterial calcification.","studies":[{"pmid":"25694037","title":"Menaquinone-7 supplementation improves arterial stiffness in healthy postmenopausal women","url":"https://pubmed.ncbi.nlm.nih.gov/25694037/","type":"RCT"}]},"Immune Resilience":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28202713/","notes":"This major meta-analysis of 25 RCTs involving 11,321 participants concluded that vitamin D supplementation significantly reduces the risk of acute respiratory infections, with the greatest benefit observed in individuals with profound deficiency.","title":"Vitamin D supplementation to prevent acute respiratory tract infections: systematic review and meta-analysis of individual participant data"}]}}'::jsonb, hallmarks_of_aging_impact = '["Altered Intercellular Communication","Loss of Proteostasis"]'::text[] WHERE id = 'vitamin_d3';

UPDATE modalities SET functional_impacts = '{"Calmness":{"score":7},"Skin Clarity":{"score":9,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/24286286/","title":"Red and NIR Light in Intradermal Collagen Density Increase"}]},"Overall Energy":{"score":8},"chronic_inflammation":{"score":76,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Direct suppression of NF-kB transcription and circulating hs-CRP","biomarkers":["hs-CRP","Interleukin-6 (IL-6)","TNF-alpha"],"mechanism":"Blocks nuclear translocation of NF-kappaB p65 and inhibits COX-2 / 5-LOX enzymatic cascades.","studies":[{"pmid":"28236680","title":"Curcumin Suppression of Inflammatory Mediators","url":"https://pubmed.ncbi.nlm.nih.gov/28236680/","type":"Meta-Analysis"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction"]'::text[] WHERE id = 'blueprint_red_light_therapy';

UPDATE modalities SET functional_impacts = '{"Pain":{"score":8,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/22331979/","notes":"This meta-analysis of 15 randomized controlled trials found that intravenous ALA at a dose of 600 mg/day for 3 weeks significantly improved symptoms of diabetic neuropathy, particularly pain, burning, and numbness.","title":"Alpha-lipoic acid for symptomatic peripheral neuropathy in patients with diabetes: a meta-analysis of randomized controlled trials"}]},"Energy":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/32413697/","notes":"This clinical trial demonstrated that 12 weeks of ALA supplementation (1200 mg/day) significantly reduced the severity of fatigue and improved physical and mental quality of life in patients with Multiple Sclerosis compared to placebo.","title":"The effects of alpha-lipoic acid supplementation on fatigue and quality of life in patients with multiple sclerosis: A randomized, double-blind, placebo-controlled trial"}]},"Brain Fog":{"score":6,"studies":[{"url":"https://pubmed.ncbi.nlm.nih.gov/17982894/","notes":"In this long-term study of patients with Alzheimer''s disease, treatment with 600mg of ALA per day resulted in a significant stabilization of cognitive function over 48 months, suggesting a neuroprotective effect that can mitigate cognitive decline and symptoms like brain fog.","title":"Alpha-lipoic acid as a new treatment option for Alzheimer''s disease--a 48 months follow-up analysis"}]},"metabolic_health":{"score":78,"tier":"synergistic","evidence_grade":"Grade A (Human RCT)","effect_size":"Improves peripheral insulin sensitivity and AMPK signaling","biomarkers":["Fasting Insulin","HOMA-IR","HbA1c"],"mechanism":"Activates hepatic and muscular AMPK phosphorylation to facilitate glucose uptake.","studies":[{"pmid":"32060683","title":"Targeting AMPK in Metabolic Disease and Aging","url":"https://pubmed.ncbi.nlm.nih.gov/32060683/","type":"Systematic Review"}]}}'::jsonb, hallmarks_of_aging_impact = '["Mitochondrial Dysfunction","Deregulated Nutrient Sensing"]'::text[] WHERE id = 'alpha_lipoic_acid';